from typing import List

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # Find rotation index (smallest element)
        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1
            else:
                hi = mid
        rot = lo

        # Standard binary search with offset
        lo, hi = 0, n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            real_mid = (mid + rot) % n
            if nums[real_mid] == target:
                return real_mid
            if nums[real_mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return -1

