from typing import List

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        base = nums[0]
        while left <= right:
            mid = (left + right) // 2
            val = nums[mid]
            if (val >= base) == (target >= base):
                comp = val
            else:
                comp = float('inf') if target >= base else -float('inf')
            if comp == target:
                return mid
            if comp < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

