from typing import List

class Solution:
    def numberOfCleanRooms(self, room: List[List[int]]) -> int:
        m, n = len(room), len(room[0])
        moves = [(0,1), (1,0), (0,-1), (-1,0)]

        # Use bitmask per cell to track visited directions: 0..3 bits for right,down,left,up
        visited_mask = {}
        cleaned_cells = set()

        r = c = 0
        d = 0
        cleaned_cells.add((r, c))

        while True:
            mask = visited_mask.get((r, c), 0)
            bit = 1 << d
            if mask & bit:
                break
            visited_mask[(r, c)] = mask | bit

            nr, nc = r + moves[d][0], c + moves[d][1]
            if not (0 <= nr < m and 0 <= nc < n) or room[nr][nc] == 1:
                d = (d + 1) % 4
                continue
            r, c = nr, nc
            if (r, c) not in cleaned_cells:
                cleaned_cells.add((r, c))

        return len(cleaned_cells)

