from typing import List

class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        coins.sort()
        i = 0
        total = 0
        n = len(coins)

        def can_extend(current: int, val: int) -> bool:
            return val <= current + 1

        def extend(current: int, val: int) -> int:
            return current + val

        while i < n:
            if can_extend(total, coins[i]):
                total = extend(total, coins[i])
                i += 1
            else:
                break
        return total + 1

