from typing import List
import heapq

class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        heap = list(coins)
        heapq.heapify(heap)
        reach = 0
        while heap and heap[0] <= reach + 1:
            reach += heapq.heappop(heap)
        return reach + 1

