from typing import List, Tuple

class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        MOD = 10**9 + 7
        rows, cols = m, n
        cur = [[0] * cols for _ in range(rows)]
        cur[startRow][startColumn] = 1
        total = 0

        moves: Tuple[Tuple[int, int], ...] = ((1, 0), (-1, 0), (0, 1), (0, -1))

        for _ in range(maxMove):
            nxt = [[0] * cols for _ in range(rows)]
            for r in range(rows):
                for c in range(cols):
                    if not cur[r][c]:
                        continue
                    val = cur[r][c]
                    for dr, dc in moves:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            nxt[nr][nc] = (nxt[nr][nc] + val) % MOD
                        else:
                            total = (total + val) % MOD
            cur = nxt

        return total % MOD

