from typing import List

class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        MOD = 10**9 + 7
        grid = [[0] * n for _ in range(m)]
        grid[startRow][startColumn] = 1
        ans = 0
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
        moves = maxMove

        def add_contributions(i: int, j: int, val: int, target: List[List[int]]) -> None:
            nonlocal ans
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n:
                    target[ni][nj] = (target[ni][nj] + val) % MOD
                else:
                    ans = (ans + val) % MOD

        while moves > 0:
            next_grid = [[0] * n for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    v = grid[i][j]
                    if v:
                        add_contributions(i, j, v, next_grid)
            grid = next_grid
            moves -= 1

        return ans % MOD

