from typing import Dict, Tuple

class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        MOD = 10**9 + 7
        current: Dict[Tuple[int, int], int] = {(startRow, startColumn): 1}
        ans = 0
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

        for _ in range(maxMove):
            nxt = defaultdict(int)
            for (i, j), cnt in current.items():
                if cnt == 0:
                    continue
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n:
                        nxt[(ni, nj)] = (nxt[(ni, nj)] + cnt) % MOD
                    else:
                        ans = (ans + cnt) % MOD
            current = nxt

        return ans % MOD

