from typing import List

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        arr = list(nums)
        n = len(arr)
        ops = 0
        while True:
            odd = 0
            for i in range(n):
                if arr[i] & 1:
                    odd += 1
                    arr[i] -= 1
            ops += odd
            if all(v == 0 for v in arr):
                break
            for i in range(n):
                arr[i] //= 2
            ops += 1
        return ops

