from typing import Iterable, List, Tuple

class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        pairs: List[Tuple[str, str]] = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]
        mids: List[str] = ['0', '1', '8']

        def gen(n: int, total: int) -> Iterable[str]:
            if n == 0:
                yield ""
                return
            if n == 1:
                for c in mids:
                    yield c
                return
            for inner in gen(n - 2, total):
                for a, b in pairs:
                    if n == total and a == '0':
                        continue
                    yield a + inner + b

        len_low = len(low)
        len_high = len(high)

        def within_range(s: str, L: int) -> bool:
            if L == len_low and s < low:
                return False
            if L == len_high and s > high:
                return False
            return True

        total = 0
        L = len_low
        while L <= len_high:
            for s in gen(L, L):
                if within_range(s, L):
                    total += 1
            L += 1
        return total

