class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        mirror_pairs: List[Tuple[str, str]] = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]
        center_digits: List[str] = ['0', '1', '8']

        def make(n: int, tot: int) -> Iterable[str]:
            if n == 0:
                yield ""
                return
            if n == 1:
                for ch in center_digits:
                    yield ch
                return
            for mid in make(n - 2, tot):
                for left, right in mirror_pairs:
                    if n == tot and left == '0':
                        continue
                    yield left + mid + right

        n_lo = len(low)
        n_hi = len(high)
        ans = 0

        for width in range(n_lo, n_hi + 1):
            for s in make(width, width):
                if width == n_lo and not (s >= low):
                    continue
                if width == n_hi and not (s <= high):
                    continue
                ans += 1
        return ans

