class Solution:
    def longestIdealString(self, s: str, k: int) -> int:
        class SegTree:
            def __init__(self, n: int):
                self.N = 1
                while self.N < n:
                    self.N <<= 1
                self.data = [0] * (2 * self.N)

            def update_max(self, i: int, val: int) -> None:
                pos = self.N + i
                if val > self.data[pos]:
                    self.data[pos] = val
                    pos //= 2
                    while pos:
                        left = self.data[pos * 2]
                        right = self.data[pos * 2 + 1]
                        self.data[pos] = left if left >= right else right
                        pos //= 2

            def query(self, l: int, r: int) -> int:
                l += self.N
                r += self.N
                res = 0
                while l <= r:
                    if (l & 1) == 1:
                        if self.data[l] > res:
                            res = self.data[l]
                        l += 1
                    if (r & 1) == 0:
                        if self.data[r] > res:
                            res = self.data[r]
                        r -= 1
                    l //= 2
                    r //= 2
                return res

        st = SegTree(26)
        ans = 0
        a0 = ord('a')
        for ch in s:
            idx = ord(ch) - a0
            l = idx - k
            if l < 0:
                l = 0
            r = idx + k
            if r > 25:
                r = 25
            best = st.query(l, r)
            nxt = best + 1
            if nxt > ans:
                ans = nxt
            st.update_max(idx, nxt)
        return ans

