import heapq

class Solution:
    def splitNum(self, num: int) -> int:
        digits = sorted(int(c) for c in str(num))
        heap = [(0, 0, 0), (0, 0, 1)]  # (value, length, id)
        for d in digits:
            val, length, idx = heapq.heappop(heap)
            new_val = val * 10 + d
            heapq.heappush(heap, (new_val, length + 1, idx))
        first = heapq.heappop(heap)[0]
        second = heapq.heappop(heap)[0]
        return first + second

