from typing import List

class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Structural Transformation: track component count during unions
        if len(connections) < n - 1:
            return -1

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def try_union(a: int, b: int) -> bool:
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1
            return True

        groups = n
        for a, b in connections:
            if try_union(a, b):
                groups -= 1

        return groups - 1

