from typing import List

class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Meaning-Preserving Rewrite
        if (n - 1) > len(connections):
            return -1

        par = list(range(n))
        rnk = [0] * n

        def find(u: int) -> int:
            while par[u] != u:
                par[u] = par[par[u]]
                u = par[u]
            return u

        def link(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rnk[rx] < rnk[ry]:
                par[rx] = ry
            elif rnk[rx] > rnk[ry]:
                par[ry] = rx
            else:
                par[ry] = rx
                rnk[rx] += 1

        for u, v in connections:
            link(u, v)

        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots) - 1

