from typing import List
from collections import deque

class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Algorithm / Data-Structure Variant: DFS/BFS instead of DSU
        if len(connections) < n - 1:
            return -1

        graph = [[] for _ in range(n)]
        for a, b in connections:
            graph[a].append(b)
            graph[b].append(a)

        visited = [False] * n
        components = 0

        for start in range(n):
            if visited[start]:
                continue
            components += 1
            dq = deque([start])
            visited[start] = True
            while dq:
                u = dq.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        dq.append(v)

        return components - 1

