from typing import Dict, Tuple, List

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n > m:
            n, m = m, n

        cols: List[int] = [0] * m
        ans = n * m
        cache: Dict[Tuple[int, ...], int] = {}

        def search(used: int) -> None:
            nonlocal ans

            if used >= ans:
                return

            key = tuple(cols)
            prev = cache.get(key)
            if prev is not None and used >= prev:
                return
            cache[key] = used

            level = min(cols)
            if level == n:
                if used < ans:
                    ans = used
                return

            i = cols.index(level)

            j = i
            while j < m and cols[j] == level:
                j += 1

            max_side = min(n - level, j - i)

            for size in range(max_side, 0, -1):
                for t in range(i, i + size):
                    cols[t] += size

                search(used + 1)

                for t in range(i, i + size):
                    cols[t] -= size

        search(0)
        return ans

