from typing import Dict, Tuple, List

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n > m:
            n, m = m, n

        heights: List[int] = [0] * m
        best = n * m
        seen: Dict[Tuple[int, ...], int] = {}

        def raise_columns(start: int, size: int, up: bool) -> None:
            delta = size if up else -size
            t = start
            end = start + size
            while t < end:
                heights[t] += delta
                t += 1

        def contiguous_same_min(start_idx: int, val: int) -> int:
            j = start_idx
            while j < m and heights[j] == val:
                j += 1
            return j

        def dfs(count: int) -> None:
            nonlocal best

            # Prune by current best
            if count >= best:
                return

            key = tuple(heights)
            old = seen.get(key)
            if old is not None and count >= old:
                return
            seen[key] = count

            min_h = min(heights)
            if min_h == n:
                if count < best:
                    best = count
                return

            i = heights.index(min_h)
            j = contiguous_same_min(i, min_h)
            max_k = min(n - min_h, j - i)

            k = max_k
            while k >= 1:
                raise_columns(i, k, True)
                dfs(count + 1)
                raise_columns(i, k, False)
                k -= 1

        dfs(0)
        return best

