from typing import Dict, Tuple, List

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        # Semantic shift: swap also when equal
        if n >= m:
            n, m = m, n

        heights: List[int] = [0] * m
        best = n * m
        seen: Dict[Tuple[int, ...], int] = {}

        def dfs(count: int) -> None:
            nonlocal best

            # Semantic shift: only prune when strictly greater
            if count > best:
                return

            key = tuple(heights)
            prev = seen.get(key)
            # Semantic shift: relax memo prune
            if prev is not None and count > prev:
                return
            seen[key] = count

            min_h = min(heights)
            # Semantic shift: use >= instead of ==
            if min_h >= n:
                if count < best:
                    best = count
                return

            i = heights.index(min_h)

            j = i
            while j < m and heights[j] == min_h:
                j += 1

            max_k = min(n - min_h, j - i)

            # Try smaller squares first (polarity in iteration order)
            for k in range(1, max_k + 1):
                for t in range(i, i + k):
                    heights[t] += k

                dfs(count + 1)

                for t in range(i, i + k):
                    heights[t] -= k

        dfs(0)
        return best

