from typing import List

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n > m:
            n, m = m, n

        board = [[0] * m for _ in range(n)]
        best = n * m

        def find_first_empty():
            for r in range(n):
                for c in range(m):
                    if board[r][c] == 0:
                        return r, c
            return None

        def can_place(r: int, c: int, size: int) -> bool:
            if r + size > n or c + size > m:
                return False
            for i in range(r, r + size):
                for j in range(c, c + size):
                    if board[i][j]:
                        return False
            return True

        def place(r: int, c: int, size: int, val: int) -> None:
            for i in range(r, r + size):
                for j in range(c, c + size):
                    board[i][j] = val

        def dfs(count: int) -> None:
            nonlocal best
            if count >= best:
                return

            pos = find_first_empty()
            if pos is None:
                if count < best:
                    best = count
                return

            r, c = pos

            max_size = min(n - r, m - c)
            # Determine the largest possible square at this position
            s = 1
            valid_max = 0
            while s <= max_size and can_place(r, c, s):
                valid_max = s
                s += 1

            for size in range(valid_max, 0, -1):
                place(r, c, size, 1)
                dfs(count + 1)
                place(r, c, size, 0)

        dfs(0)
        return best

