from typing import Tuple, Dict, List
from collections import deque

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n > m:
            n, m = m, n

        start: Tuple[int, ...] = tuple([0] * m)
        target_height = n

        def next_states(state: Tuple[int, ...]) -> List[Tuple[int, ...]]:
            heights = list(state)
            # Find minimum height and leftmost index
            min_h = min(heights)
            if min_h == target_height:
                return []

            i = heights.index(min_h)
            j = i
            while j < m and heights[j] == min_h:
                j += 1
            max_k = min(target_height - min_h, j - i)

            res: List[Tuple[int, ...]] = []
            for k in range(max_k, 0, -1):
                new_h = list(heights)
                for t in range(i, i + k):
                    new_h[t] += k
                res.append(tuple(new_h))
            return res

        q = deque()
        q.append((0, start))
        visited: Dict[Tuple[int, ...], int] = {start: 0}

        while q:
            cnt, state = q.popleft()
            min_h = min(state)
            if min_h == target_height:
                return cnt
            for nxt in next_states(state):
                if nxt not in visited:
                    visited[nxt] = cnt + 1
                    q.append((cnt + 1, nxt))

        return n * m

