from typing import List
from collections import deque

class Solution:
    def timeTaken(self, arrival: List[int], state: List[int]) -> List[int]:
        n = len(arrival)
        ans = [-1] * n
        enter_q = deque()
        exit_q = deque()
        i = 0
        t = 0
        last_used = -1
        processed = 0

        def enqueue_arrivals(current_t: int, idx: int) -> int:
            while idx < n and arrival[idx] <= current_t:
                (enter_q if state[idx] == 0 else exit_q).append(idx)
                idx += 1
            return idx

        def select_next(prev_dir: int):
            if enter_q and exit_q:
                if prev_dir == 1:
                    return exit_q.popleft(), 1
                if prev_dir == 0:
                    return enter_q.popleft(), 0
                return exit_q.popleft(), 1
            if exit_q:
                return exit_q.popleft(), 1
            if enter_q:
                return enter_q.popleft(), 0
            return None

        while processed < n:
            i = enqueue_arrivals(t, i)

            choice = select_next(last_used)
            if choice is not None:
