class Solution:
    def maximumTime(self, time: str) -> str:
        chars = list(time)

        # Handle hours
        if chars[0] == '?':
            if chars[1] == '?' or chars[1] <= '3':
                chars[0] = '2'
            else:
                chars[0] = '1'
        if chars[1] == '?':
            chars[1] = '3' if chars[0] == '2' else '9'

        # Handle minutes
