class Solution:
    def maximumTime(self, time: str) -> str:
        parts = list(time)

        def fill_hours(h0: str, h1: str):
            if h0 == '?':
                if h1 == '?' or h1 <= '3':
                    h0 = '2'
                else:
                    h0 = '1'
            if h1 == '?':
                h1 = '3' if h0 == '2' else '9'
            return h0, h1

        def fill_minutes(m0: str, m1: str):
            if m0 == '?':
                m0 = '5'
            if m1 == '?':
                m1 = '9'
            return m0, m1

        parts[0], parts[1] = fill_hours(parts[0], parts[1])
        parts[3], parts[4] = fill_minutes(parts[3], parts[4])

        return ''.join(parts)

