class Solution:
    def maximumTime(self, time: str) -> str:
        # Search from the latest time downwards and return the first match
        for h in range(23, -1, -1):
            for m in range(59, -1, -1):
                cand = f"{h:02d}:{m:02d}"
                ok = True
                for i in (0, 1, 3, 4):
                    if time[i] != '?' and time[i] != cand[i]:
                        ok = False
                        break
                if ok:
                    return cand
        return time

