# Mutation 5
from itertools import product

class Solution:
    def maximumTime(self, time: str) -> str:
        # Build candidate sets per position
        p0 = [time[0]] if time[0] != '?' else ['0', '1', '2']
        p1 = [time[1]] if time[1] != '?' else list('0123456789')
        p3 = [time[3]] if time[3] != '?' else list('012345')
        p4 = [time[4]] if time[4] != '?' else list('0123456789')

        best_total = -1
        best_str = None

        for h0, h1, m0, m1 in product(p0, p1, p3, p4):
            hh = int(h0 + h1)
            mm = int(m0 + m1)
            if 0 <= hh <= 23 and 0 <= mm <= 59:
                cand = f"{h0}{h1}:{m0}{m1}"
                # Ensure exact match with non-'?' positions
                if (time[0] != '?' and time[0] != h0) or \
                   (time[1] != '?' and time[1] != h1) or \
                   (time[3] != '?' and time[3] != m0) or \
                   (time[4] != '?' and time[4] != m1):
                    continue
                total = hh * 60 + mm
                if total > best_total:
                    best_total = total
                    best_str = cand

        return best_str if best_str is not None else time

