import math

class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        def feasible(limit: int) -> bool:
            return sum(math.ceil(q / limit) for q in quantities) <= n

        lo, hi = 1, max(quantities)
        while lo < hi:
            guess = (lo + hi) // 2
            if feasible(guess):
                hi = guess
            else:
                lo = guess + 1
        return lo

