class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        def stores_needed(x: int) -> int:
            total = 0
            i = 0
            m = len(quantities)
            while i < m:
                q = quantities[i]
                total += (q + x - 1) // x
                if total > n:
                    break
                i += 1
            return total

        def search(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi) // 2
            if stores_needed(mid) <= n:
                return search(lo, mid)
            else:
                return search(mid + 1, hi)

        return search(1, max(quantities))

