from typing import List
import heapq

class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        m = len(quantities)
        # Each type must have at least one store; m <= n by constraints
        if n == m:
            return max(quantities)

        # Max-heap on current per-store maximum for each product type
        heap = []
        for q in quantities:
            # initial parts = 1
            current = (q + 1 - 1) // 1
            heapq.heappush(heap, (-current, q, 1))

        extra = n - m
        for _ in range(extra):
            neg_val, q, parts = heapq.heappop(heap)
            parts += 1
            new_val = (q + parts - 1) // parts
            heapq.heappush(heap, (-new_val, q, parts))

        return -heap[0][0]

