class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        def can(limit: int) -> bool:
            req = 0
            for q in quantities:
                req += (q + limit - 1) // limit
                if req > n:
                    return False
            return True

        hi = max(quantities)
        ans = 0
        step = 1 << (hi.bit_length() - 1)
        while step:
            if ans + step <= hi and not can(ans + step):
                ans += step
            step >>= 1
