from typing import List

class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        class TrieNode:
            __slots__ = ("kids", "freq")
            def __init__(self):
                self.kids = {}
                self.freq = 0

        root = TrieNode()

        # Build trie and count prefixes
        for word in words:
            cur = root
            for ch in word:
                cur = cur.kids.setdefault(ch, TrieNode())
                cur.freq += 1

        # Compute sums of prefix scores for each word
        result: List[int] = []
        for word in words:
            cur = root
            s = 0
            for ch in word:
                cur = cur.kids[ch]
                s += cur.freq
            result.append(s)

        return result

