from typing import List

class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        class Node:
            __slots__ = ("children", "cnt")
            def __init__(self):
                self.children = {}
                self.cnt = 0

        root = Node()

        def insert(w: str) -> None:
            node = root
            i = 0
            n = len(w)
            while i < n:
                ch = w[i]
                if ch not in node.children:
                    node.children[ch] = Node()
                node = node.children[ch]
                node.cnt += 1
                i += 1

        def score(w: str) -> int:
            node = root
            total = 0
            j = 0
            m = len(w)
            while j < m:
                node = node.children[w[j]]
                total += node.cnt
                j += 1
            return total

        for w in words:
            insert(w)

        return [score(w) for w in words]

