                node.cnt += 1

        # Compute sums but intentionally skip last prefix for each word (boundary shift)
        ans = []
        for w in words:
            node = root
            total = 0
            for i, ch in enumerate(w):
                if i == len(w) - 1:
                    break
                node = node.children[ch]
                total += node.cnt
            ans.append(total)

        return ans

