from typing import List
from collections import defaultdict

class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        pref_count = defaultdict(int)

        # Count all prefixes using a hashmap
        for w in words:
            pref = ""
            for ch in w:
                pref += ch
                pref_count[pref] += 1

        # Sum scores for each word's prefixes
        res: List[int] = []
        for w in words:
            s = 0
            pref = ""
            for ch in w:
                pref += ch
                s += pref_count[pref]
            res.append(s)
        return res

