from typing import List

class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        class Node:
            __slots__ = ("child", "cnt")
            def __init__(self):
                self.child = [None] * 26
                self.cnt = 0

        root = Node()

        def add(node: Node, s: str, i: int) -> None:
            if i == len(s):
                return
            idx = ord(s[i]) - 97
            if node.child[idx] is None:
                node.child[idx] = Node()
            nxt = node.child[idx]
            nxt.cnt += 1
            add(nxt, s, i + 1)

        def calc(node: Node, s: str, i: int) -> int:
            if i == len(s):
                return 0
            idx = ord(s[i]) - 97
            nxt = node.child[idx]
            return nxt.cnt + calc(nxt, s, i + 1)

        for w in words:
            add(root, w, 0)

        return [calc(root, w, 0) for w in words]

