from typing import List

class Solution:
    def validSquare(self, p1: List[int], p2: List[int], p3: List[int], p4: List[int]) -> bool:
        def sqd(u: List[int], v: List[int]) -> int:
            dx = u[0] - v[0]
            dy = u[1] - v[1]
            return dx * dx + dy * dy

        pts = [p1, p2, p3, p4]
        d = sorted([sqd(pts[i], pts[j]) for i in range(4) for j in range(i + 1, 4)])
        return d[0] != 0 and len({d[0], d[1], d[2], d[3]}) == 1 and d[4] == d[5] and d[4] == 2 * d[0]

