from typing import List

class Solution:
    def validSquare(self, p1: List[int], p2: List[int], p3: List[int], p4: List[int]) -> bool:
        def dist2(a: List[int], b: List[int]) -> int:
            return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

        def check(ds: List[int]) -> bool:
            if ds[0] == 0:
                return False
            if not (ds[0] == ds[1] == ds[2] == ds[3]):
                return False
            if ds[4] != ds[5]:
                return False
            return ds[4] == 2 * ds[0]

        pts = [p1, p2, p3, p4]
        ds: List[int] = []
