from typing import List
from collections import deque

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        rows, cols = len(mat), len(mat[0])
        # encode initial matrix into bitmask
        initial_state = 0
        for r in range(rows):
            for c in range(cols):
                if mat[r][c]:
                    initial_state |= 1 << (r * cols + c)
        if not initial_state:
            return 0

        # precompute flip masks for each cell
        offsets = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
        flip_masks = []
        for r in range(rows):
            for c in range(cols):
                msk = 0
                for dr, dc in offsets:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        msk ^= 1 << (nr * cols + nc)
                flip_masks.append(msk)

        # BFS over bitmask states
        queue = deque()
        queue.append((initial_state, 0))
        seen = {initial_state}

        while queue:
            cur, dist = queue.popleft()
            if cur == 0:
                return dist
            for fm in flip_masks:
                nxt = cur ^ fm
                if nxt in seen:
                    continue
                seen.add(nxt)
                queue.append((nxt, dist + 1))
        return -1

