from typing import List
from collections import deque

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])

        def encode_state() -> int:
            i = 0
            j = 0
            state = 0
            while i < m:
                j = 0
                while j < n:
                    if mat[i][j]:
                        state |= 1 << (i * n + j)
                    j += 1
                i += 1
            return state

        def compute_flips() -> List[int]:
            dirs = [(0,0), (1,0), (-1,0), (0,1), (0,-1)]
            res = []
            i = 0
            while i < m:
                j = 0
                while j < n:
                    mask = 0
                    k = 0
                    while k < len(dirs):
                        dx, dy = dirs[k]
                        x, y = i + dx, j + dy
                        if 0 <= x < m and 0 <= y < n:
                            mask ^= 1 << (x * n + y)
                        k += 1
                    res.append(mask)
                    j += 1
                i += 1
            return res

        start = encode_state()
        if start == 0:
            return 0

        flips = compute_flips()
        dq = deque()
        dq.append((start, 0))
        visited = set([start])

        while dq:
            state, steps = dq.popleft()
            if state == 0:
                return steps
            idx = 0
            while idx < len(flips):
                nxt = state ^ flips[idx]
                if nxt not in visited:
                    visited.add(nxt)
                    dq.append((nxt, steps + 1))
                idx += 1

        return -1

