from typing import List

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])

        # Encode starting state
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j]:
                    start |= 1 << (i * n + j)
        if start == 0:
            return 0

        # Precompute flip masks
        flips = []
        for i in range(m):
            for j in range(n):
                mask = 0
                for dx, dy in [(0,0),(1,0),(-1,0),(0,1),(0,-1)]:
                    x, y = i + dx, j + dy
                    if 0 <= x < m and 0 <= y < n:
                        mask ^= 1 << (x * n + y)
                flips.append(mask)

        # Bidirectional BFS using sets
        front = {start}
        back = {0}
        visited_front = {start}
        visited_back = {0}
        steps = 0

        while front and back:
            # Always expand the smaller frontier
            if len(front) > len(back):
                front, back = back, front
                visited_front, visited_back = visited_back, visited_front

            next_front = set()
            for state in front:
                for mask in flips:
                    nxt = state ^ mask
                    if nxt in visited_front:
                        continue
                    if nxt in back:
                        return steps + 1
                    visited_front.add(nxt)
                    next_front.add(nxt)
            front = next_front
            steps += 1

        return -1

