from typing import List

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])

        # Convert mat to bitmask
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j]:
                    start |= 1 << (i * n + j)
        if start == 0:
            return 0

        # Precompute flip masks
        flips = []
        for i in range(m):
            for j in range(n):
                mask = 0
                for dx, dy in [(0,0),(1,0),(-1,0),(0,1),(0,-1)]:
                    x, y = i + dx, j + dy
                    if 0 <= x < m and 0 <= y < n:
                        mask ^= 1 << (x * n + y)
                flips.append(mask)

        # Iterative Deepening DFS with memoization per depth
        limit = m * n

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(state: int, depth: int) -> bool:
            if state == 0:
                return True
            if depth == 0:
                return False
            for mask in flips:
                if dfs(state ^ mask, depth - 1):
                    return True
            return False

        for d in range(limit + 1):
            if dfs(start, d):
                return d
        return -1

