from typing import List

class Solution:
    def reversePairs(self, nums: List[int]) -> int:
        def count_cross(arr: List[int], l: int, m: int, r: int) -> int:
            cnt = 0
            i, j = l, m
            while i < m:
                while j < r and arr[i] > 2 * arr[j]:
                    j += 1
                cnt += j - m
                i += 1
            return cnt

        def merge_range(arr: List[int], l: int, m: int, r: int) -> None:
            tmp = []
            i, j = l, m
            while i < m and j < r:
                if arr[i] <= arr[j]:
                    tmp.append(arr[i])
                    i += 1
                else:
                    tmp.append(arr[j])
                    j += 1
            if i < m:
                tmp.extend(arr[i:m])
            if j < r:
                tmp.extend(arr[j:r])
            arr[l:r] = tmp

        def divide_and_conquer(arr: List[int], l: int, r: int) -> int:
            if r - l <= 1:
                return 0
            m = (l + r) // 2
            res = divide_and_conquer(arr, l, m)
            res += divide_and_conquer(arr, m, r)
            res += count_cross(arr, l, m, r)
            merge_range(arr, l, m, r)
            return res

        return divide_and_conquer(nums, 0, len(nums))

