class Solution:
    def reversePairs(self, nums: List[int]) -> int:
        def merge_and_count(a: List[int], lo: int, hi: int) -> int:
            if hi - lo <= 1:
                return 0
            mid = (lo + hi) // 2
            total = merge_and_count(a, lo, mid) + merge_and_count(a, mid, hi)

            right = mid
            for left in range(lo, mid):
                while right < hi and a[left] > 2 * a[right]:
                    right += 1
                total += right - mid

            merged = []
            i, j = lo, mid
            while i < mid or j < hi:
                if j >= hi or (i < mid and a[i] <= a[j]):
                    merged.append(a[i])
                    i += 1
                else:
                    merged.append(a[j])
                    j += 1
            a[lo:hi] = merged
            return total

        return merge_and_count(nums, 0, len(nums))

