from typing import List
from bisect import bisect_left, bisect_right

class Solution:
    def reversePairs(self, nums: List[int]) -> int:
        if not nums:
            return 0

        values = sorted(set(nums + [2 * x for x in nums]))
        n = len(values)

        class BIT:
            def __init__(self, size: int):
                self.n = size
                self.bit = [0] * (size + 1)

            def update(self, i: int, delta: int) -> None:
                while i <= self.n:
                    self.bit[i] += delta
                    i += i & -i

            def query(self, i: int) -> int:
                s = 0
                while i > 0:
                    s += self.bit[i]
                    i -= i & -i
                return s

        bit = BIT(n)
        total = 0
        result = 0
        for v in nums:
            # count of prior numbers > 2*v
            idx = bisect_right(values, 2 * v)  # number of coords <= 2*v
            result += total - bit.query(idx)
            pos = bisect_left(values, v) + 1
            bit.update(pos, 1)
            total += 1
        return result

