class Solution:
    def nextGreaterElement(self, n: int) -> int:
        arr = list(str(n))
        pivot = -1
        for k in range(len(arr) - 2, -1, -1):
            if arr[k] < arr[k + 1]:
                pivot = k
                break
        if pivot == -1:
            return -1

        for t in range(len(arr) - 1, -1, -1):
            if arr[t] > arr[pivot]:
                swap_idx = t
                break

        arr[pivot], arr[swap_idx] = arr[swap_idx], arr[pivot]
        arr[pivot + 1:] = arr[pivot + 1:][::-1]

        ans = int(''.join(arr))
        return ans if ans <= 0x7FFFFFFF else -1

