            while i >= 0 and chars[i] >= chars[i + 1]:
                i -= 1
            if i < 0:
                return False
            j = len(chars) - 1
            while j >= 0 and chars[j] <= chars[i]:
                j -= 1
            chars[i], chars[j] = chars[j], chars[i]
            l, r = i + 1, len(chars) - 1
            while l < r:
                chars[l], chars[r] = chars[r], chars[l]
                l += 1
                r -= 1
            return True

