from bisect import bisect_right

class Solution:
    def nextGreaterElement(self, n: int) -> int:
        s = list(str(n))
        i = len(s) - 2
        while i >= 0 and s[i] >= s[i + 1]:
            i -= 1
        if i < 0:
            return -1

        pivot = s[i]
        suffix = sorted(s[i + 1:])
        pos = bisect_right(suffix, pivot)
        if pos == len(suffix):
            return -1
        chosen = suffix.pop(pos)
        tail = sorted(suffix + [pivot])

        out_chars = s[:i] + [chosen] + tail
        res = int(''.join(out_chars))
        return res if res <= 2**31 - 1 else -1

