from typing import List

class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        if paint == []:
            return []
        max_r = max(b for _, b in paint)
        nxt = list(range(max_r + 1))  # sentinel at max_r

        def next_unpainted(x: int) -> int:
            while nxt[x] != x:
                nxt[x] = nxt[nxt[x]]
                x = nxt[x]
            return x

        worklog: List[int] = []
        for start, end in paint:
            pos = next_unpainted(start)
            added = 0
            while pos < end:
                nxt[pos] = next_unpainted(pos + 1)
                added += 1
                pos = nxt[pos]
            worklog.append(added)
        return worklog

