from typing import List

class Solution:
    def selfDividingNumbers(self, left: int, right: int) -> List[int]:
        def is_self_dividing(x: int) -> bool:
            y = x
            while y > 0:
                d = y % 10
                if d == 0 or x % d != 0:
                    return False
                y //= 10
            return True

        res: List[int] = []
        current = left
        while current <= right:
            if is_self_dividing(current):
                res.append(current)
            current += 1
        return res

