class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)

        def matches(step: int) -> bool:
            start = step * k
            return word.startswith(word[start:])

        max_steps = (n + k - 1) // k
        t = 1
        while t <= max_steps:
            if matches(t):
                return t
            t += 1
        return max_steps

