class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        import math
        total = len(word)
        limit = math.ceil(total / k)
        for step in range(1, limit + 1):
            tail = word[step * k:]
            if word[:len(tail)] == tail:
                return step
        return limit

