class Solution:
    def minInsertions(self, s: str) -> int:
        res = 0
        need = 0  # number of ')' still needed to balance opens (counted as pairs)
        for ch in s:
            if ch == '(':
                need += 2
                if need % 2 == 1:
                    # We have an odd need, meaning there was a single ')' before.
                    # Insert one ')' to complete a pair.
                    res += 1
                    need -= 1
            else:  # ch == ')'
                need -= 1
                if need == -1:
                    # We have a ')' without a matching '('. Insert '('.
                    res += 1
                    # After inserting '(', one more ')' is needed to complete its pair.
                    need = 1
        # Add remaining needed ')' insertions
        res += need
        return res

