from typing import List

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()
        n1, n2 = len(nums1), len(nums2)
        ans = None

        # Try aligning nums2[0] with one of the first three elements of nums1
        for i in range(min(3, n1)):
            x = nums2[0] - nums1[i]
            p1 = 0
            p2 = 0
            removed = 0
            while p1 < n1:
                if p2 < n2 and nums1[p1] + x == nums2[p2]:
                    p1 += 1
                    p2 += 1
                else:
                    removed += 1
                    p1 += 1
            if p2 == n2 and removed == n1 - n2:
                if ans is None or x < ans:
                    ans = x

        # Per problem statement, a solution always exists
        return ans if ans is not None else 0

