        nums1.sort()
        nums2.sort()
        n1 = len(nums1)
        n2 = len(nums2)
        best_x = None

        for idx in range(min(3, n1)):
            shift = nums2[0] - nums1[idx]
            j = 0
            removed_cnt = 0
            for val in nums1:
                if j < n2 and val + shift == nums2[j]:
                    j += 1
                else:
                    removed_cnt += 1
            if j == n2 and removed_cnt == 2:
                if best_x is None or shift < best_x:
                    best_x = shift

        return best_x if best_x is not None else 0

