        nums1.sort()
        nums2.sort()
        n1, n2 = len(nums1), len(nums2)
        res = None

        # Try up to the first four elements instead of three (semantic boundary shift)
        for i in range(min(4, n1)):
            x = nums2[0] - nums1[i]
            p1 = 0
            p2 = 0
            removed = 0
            while p1 < n1:
                # Invert condition style
                if not (p2 < n2 and nums1[p1] + x == nums2[p2]):
                    removed += 1
                    p1 += 1
                else:
                    p1 += 1
                    p2 += 1
            # Allow removing at least the required amount (semantic polarity shift)
            if p2 == n2 and removed >= (n1 - n2):
                if res is None or x < res:
                    res = x

        return res if res is not None else 0

