from typing import List
from collections import Counter

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()
        n1, n2 = len(nums1), len(nums2)

        # Candidate shifts from aligning nums2[0] with one of the smallest three nums1 elements
        candidates = []
        for i in range(min(3, n1)):
            candidates.append(nums2[0] - nums1[i])

        target = Counter(nums2)
        best = None

        for x in candidates:
            shifted = Counter(v + x for v in nums1)
            # Check all target counts are available
            feasible = True
            for k, need in target.items():
                if shifted.get(k, 0) < need:
                    feasible = False
                    break
            if not feasible:
                continue
            # Count how many extras remain (must be exactly 2)
            matched = 0
            for k in set(shifted.keys()) | set(target.keys()):
                matched += min(shifted.get(k, 0), target.get(k, 0))
            extras = n1 - matched
            if extras == 2:
                if best is None or x < best:
                    best = x

        return best if best is not None else 0

