from typing import List

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        # Try removing all pairs of elements and check feasibility directly
        nums1.sort()
        nums2.sort()
        n1, n2 = len(nums1), len(nums2)
        ans = None

        for i in range(n1):
            for j in range(i + 1, n1):
                reduced = []
                for k in range(n1):
                    if k == i or k == j:
                        continue
                    reduced.append(nums1[k])
                if not reduced:
                    continue
                x = nums2[0] - reduced[0]
                ok = True
                for idx in range(n2):
                    if reduced[idx] + x != nums2[idx]:
                        ok = False
                        break
                if ok:
                    if ans is None or x < ans:
                        ans = x

        return ans if ans is not None else 0

