from typing import List

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()
        n1, n2 = len(nums1), len(nums2)

        def can_match(shift: int) -> bool:
            # Recursive check that exactly two elements are removed from nums1
            from functools import lru_cache

            @lru_cache(None)
            def dfs(i: int, j: int, skips: int) -> bool:
                if i == n1:
                    return j == n2 and skips == 0
                if j < n2 and nums1[i] + shift == nums2[j]:
                    if dfs(i + 1, j + 1, skips):
                        return True
                if skips > 0:
                    if dfs(i + 1, j, skips - 1):
                        return True
                return False

            return dfs(0, 0, 2)

        answer = None
        for i in range(min(3, n1)):
            x = nums2[0] - nums1[i]
            if can_match(x):
                if answer is None or x < answer:
                    answer = x
        return answer if answer is not None else 0

