from typing import List

class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        MOD = 10**9 + 7

        # Variant: Kadane over two concatenations via modular indexing (no list concatenation)
        def kadane_twice(a: List[int]) -> int:
            n = len(a)
            max_end = 0
            max_so_far = 0
            for i in range(n * 2):
                max_end = max(0, max_end + a[i % n])
                if max_end > max_so_far:
                    max_so_far = max_end
            return max_so_far

        total = sum(arr)
        if k == 1:
            # Single pass Kadane
            max_end = 0
            best = 0
            for x in arr:
                max_end = max(0, max_end + x)
                if max_end > best:
                    best = max_end
            return best % MOD

        max_two = kadane_twice(arr)

        if total > 0:
            # Max prefix
            running = 0
            max_prefix = float('-inf')
            for x in arr:
                running += x
                if running > max_prefix:
                    max_prefix = running
            # Max suffix
            running = 0
            max_suffix = float('-inf')
            for x in reversed(arr):
                running += x
                if running > max_suffix:
                    max_suffix = running

            ans = max(max_two, max_suffix + max_prefix + (k - 2) * total)
        else:
            ans = max_two

        return max(0, ans) % MOD

