class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        MOD = 10**9 + 7

        def kadane_loop(a: List[int]) -> int:
            i = 0
            n = len(a)
            max_end = 0
            max_so_far = 0
            while i < n:
                max_end = max(0, max_end + a[i])
                if max_end > max_so_far:
                    max_so_far = max_end
                i += 1
            return max_so_far

        def prefix_suffix_max(a: List[int]) -> (int, int):
            # prefix
            i = 0
            cur = 0
            max_pref = float('-inf')
            while i < len(a):
                cur += a[i]
                if cur > max_pref:
                    max_pref = cur
                i += 1
            # suffix
            j = len(a) - 1
            cur = 0
            max_suf = float('-inf')
            while j >= 0:
                cur += a[j]
                if cur > max_suf:
                    max_suf = cur
                j -= 1
            return max_pref, max_suf

        tot = sum(arr)
        if k == 1:
            return kadane_loop(arr) % MOD

        max_two = kadane_loop(arr + arr)

        if tot > 0:
            max_pref, max_suf = prefix_suffix_max(arr)
            ans = max(max_two, max_suf + max_pref + (k - 2) * tot)
        else:
            ans = max_two

        return max(0, ans) % MOD

