from typing import List

class Solution:
    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
        s, e = newInterval
        placed = False
        merged: List[List[int]] = []

        for iv in intervals:
            if iv[1] < s:
                merged.append(iv)
            elif iv[0] > e:
                if not placed:
                    merged.append([s, e])
                    placed = True
                merged.append(iv)
            else:
                s = min(s, iv[0])
                e = max(e, iv[1])

        if not placed:
            merged.append([s, e])

        return merged

