class Solution:
    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
        arr = intervals + [newInterval]
        arr.sort(key=lambda x: x[0])

        merged: List[List[int]] = []
        for st, en in arr:
            if not merged or merged[-1][1] < st:
                merged.append([st, en])
            else:
                if en > merged[-1][1]:
                    merged[-1][1] = en
        return merged

