from typing import List

class Solution:
    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
        n = len(intervals)
        s, e = newInterval
        out: List[List[int]] = []

        def process(i: int, a: int, b: int) -> List[List[int]]:
            if i >= n:
                out.append([a, b])
                return out
            curr = intervals[i]
            if curr[1] < a:
                out.append(curr)
                return process(i + 1, a, b)
            if curr[0] <= b:
                a = min(a, curr[0])
                b = max(b, curr[1])
                return process(i + 1, a, b)
            out.append([a, b])
            out.extend(intervals[i:])
            return out

        return process(0, s, e)

