from typing import List

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        def ones(n: int) -> int:
            return bin(n).count('1')
        buckets = {}
        for v in arr:
            c = ones(v)
            if c not in buckets:
                buckets[c] = []
            buckets[c].append(v)
        result = []
        for c in sorted(buckets.keys()):
            bucket = buckets[c]
            bucket.sort()
            result.extend(bucket)
        return result

