import heapq

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        def count1s(n: int) -> int:
            return bin(n).count('1')
        heap = [(count1s(v), v) for v in arr]
        heapq.heapify(heap)
        out = []
        while heap:
            _, val = heapq.heappop(heap)
            out.append(val)
        return out

