from typing import List

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        fives = 0
        tens = 0

        for bill in bills:
            if bill == 5:
                fives += 1
                continue

            change = bill - 5
            # Prefer giving a $10 first, then $5 bills
            while change >= 10 and tens > 0:
                tens -= 1
                change -= 10
            while change >= 5 and fives > 0:
                fives -= 1
                change -= 5
            if change != 0:
                return False

            if bill == 10:
                tens += 1
            # We don't track $20 bills since they are never used for change

        return True

