from typing import List

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        def handle(c5: int, c10: int, b: int):
            if b == 5:
                return c5 + 1, c10, True
            if b == 10:
                if c5 == 0:
                    return c5, c10, False
                return c5 - 1, c10 + 1, True
            # b == 20
            if c10 > 0 and c5 > 0:
                return c5 - 1, c10 - 1, True
            if c5 >= 3:
                return c5 - 3, c10, True
            return c5, c10, False

        c5 = 0
        c10 = 0
        for bill in bills:
            c5, c10, ok = handle(c5, c10, bill)
            if not ok:
                return False
        return True

