from typing import List

class Solution:
    def secondGreaterElement(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [-1 for _ in range(n)]
        first_wait = []
        second_wait = []
        for idx, val in enumerate(nums):
            while second_wait and nums[second_wait[-1]] < val:
                result[second_wait.pop()] = val

            moved = []
            while first_wait and nums[first_wait[-1]] < val:
                moved.append(first_wait.pop())
            if moved:
                second_wait.extend(reversed(moved))

            first_wait.append(idx)
        return result

