from typing import List

class Solution:
    def secondGreaterElement(self, nums: List[int]) -> List[int]:
        n = len(nums)
        res = [-1] * n
        s1 = []
        s2 = []

        def resolve_seconds(v: int) -> None:
            while s2 and nums[s2[-1]] < v:
                res[s2.pop()] = v

        def promote_firsts(v: int) -> None:
            buffer = []
            while s1 and nums[s1[-1]] < v:
                buffer.append(s1.pop())
            while buffer:
                s2.append(buffer.pop())

        i = 0
        while i < n:
            x = nums[i]
            resolve_seconds(x)
            promote_firsts(x)
            s1.append(i)
            i += 1

        return res

