from collections import deque

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        if sum(colsum) != upper + lower:
            return []

        top = [0] * n
        bottom = [0] * n
        ones = deque()

        for i, c in enumerate(colsum):
            if c == 2:
                top[i] = 1
                bottom[i] = 1
                upper -= 1
                lower -= 1
                if upper < 0 or lower < 0:
                    return []
            elif c == 1:
                ones.append(i)

        if upper < 0 or lower < 0 or upper + lower != len(ones):
            return []

        while upper > 0 and ones:
            idx = ones.popleft()
            top[idx] = 1
            upper -= 1

        while ones:
            idx = ones.popleft()
            bottom[idx] = 1
            lower -= 1
            if lower < 0:
                return []

        if upper != 0 or lower != 0:
            return []
        return [top, bottom]

