from typing import List

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        patches = 0
        reach = 0
        i = 0
        n = len(coins)
        while reach < target:
            if i < n and coins[i] <= reach + 1:
                reach += coins[i]
                i += 1
            else:
                patches += 1
                reach += reach + 1
        return patches

