from typing import List

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        if n == 1:
            return 0

        parent = [i for i in range(n + 1)]
        rank = [0] * (n + 1)

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def unite(a: int, b: int) -> bool:
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        edges = sorted(connections, key=lambda t: t[2])

        total = 0
        remaining = n
        i = 0
        m = len(edges)
        while i < m and remaining > 1:
            x, y, w = edges[i]
            if unite(x, y):
                total += w
                remaining -= 1
            i += 1

        return total if remaining == 1 else -1

