import heapq

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        if n == 1:
            return 0

        adj = [[] for _ in range(n + 1)]
        for x, y, w in connections:
            adj[x].append((w, y))
            adj[y].append((w, x))

        visited = [False] * (n + 1)
        visited[1] = True
        added = 1
        total = 0

        heap = []
        for w, v in adj[1]:
            heapq.heappush(heap, (w, v))

        while heap and added < n:
            w, v = heapq.heappop(heap)
            if visited[v]:
                continue
            visited[v] = True
            added += 1
            total += w
            for w2, to in adj[v]:
                if not visited[to]:
                    heapq.heappush(heap, (w2, to))

        return total if added == n else -1

