from typing import List
import heapq

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        if n == 1:
            return 0

        uf = [-1] * (n + 1)

        def find(a: int) -> int:
            while uf[a] >= 0:
                if uf[uf[a]] >= 0:
                    uf[a] = uf[uf[a]]
                a = uf[a]
            return a

        def unite(a: int, b: int) -> bool:
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if uf[ra] > uf[rb]:
                ra, rb = rb, ra
            uf[ra] += uf[rb]
            uf[rb] = ra
            return True

        heap = [(c, x, y) for x, y, c in connections]
        heapq.heapify(heap)

        total = 0
        comps = n
        while heap and comps > 1:
            c, x, y = heapq.heappop(heap)
            if unite(x, y):
                total += c
                comps -= 1

        return total if comps == 1 else -1

