            while uf[a] >= 0:
                if uf[uf[a]] >= 0:
                    uf[a] = uf[uf[a]]
                a = uf[a]
            return a

        def unite(a: int, b: int) -> bool:
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if uf[ra] > uf[rb]:
                ra, rb = rb, ra
            uf[ra] += uf[rb]
            uf[rb] = ra
            return True

        heap = [(c, x, y) for x, y, c in connections]
