from typing import List
from collections import deque

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        window = deque()  # stores (x_i, y_i - x_i) in decreasing order of (y_i - x_i)
        best = -10**20

        for x_val, y_val in points:
            # Evict points outside the window constraint
            while window and (x_val - window[0][0]) > k:
                window.popleft()

            if window:
                best = max(best, window[0][1] + y_val + x_val)

            score = y_val - x_val
            while window and window[-1][1] <= score:
                window.pop()
            window.append((x_val, score))

        return best

