from typing import List
from collections import deque

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        dq = deque()
        ans = -10**20

        def prune(curr_x: int) -> None:
            while dq and curr_x - dq[0][0] > k:
                dq.popleft()

        def push(curr_x: int, curr_y: int) -> None:
            val = curr_y - curr_x
            while dq and dq[-1][1] <= val:
                dq.pop()
            dq.append((curr_x, val))

        n = len(points)
        i = 0
        while i < n:
            x, y = points[i]
            prune(x)
            if dq:
                ans = max(ans, dq[0][1] + y + x)
            push(x, y)
            i += 1

        return ans

