class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        # Deque will store tuples (xi, yi - xi) with decreasing (yi - xi)
        dq = deque()
        ans = -10**20  # effectively negative infinity for given constraints

        for x, y in points:
            # Remove points whose x is out of the allowed window (x - xi > k)
            while dq and x - dq[0][0] > k:
                dq.popleft()

            # If there is any valid point, update the answer
            if dq:
                ans = max(ans, dq[0][1] + y + x)  # (yi - xi) + (yj + xj)

            # Maintain deque: remove from back while current (y - x) is greater
            curr = y - x
            while dq and dq[-1][1] <= curr:
                dq.pop()
            dq.append((x, curr))

        return ans

