class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        value_to_id = {}
        table = []  # table[val_id][t]
        best = [0] * (k + 1)  # global best for each t

        for val in nums:
            if val not in value_to_id:
                value_to_id[val] = len(table)
                table.append([0] * (k + 1))
            idx = value_to_id[val]

            prev_row = table[idx][:]
            prev_best = best[:]

            new_row = []
            for t in range(k + 1):
                extend_same = prev_row[t] + 1
                switch_other = prev_best[t - 1] + 1 if t > 0 else 0
                new_row.append(max(prev_row[t], extend_same, switch_other))

            table[idx] = new_row
            best = [max(best[t], new_row[t]) for t in range(k + 1)]

        return max(best)

