from typing import List

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        # Coordinate compression
        idx = {}
        dp = []  # dp[val_id][t]
        best_len = [0] * (k + 1)      # best global length for t transitions
        best_val = [-1] * (k + 1)     # value id that attains best_len[t]
        second_len = [0] * (k + 1)    # second best global length for t transitions

        for x in nums:
            if x not in idx:
                idx[x] = len(dp)
                dp.append([0] * (k + 1))
            vid = idx[x]

            old_row = dp[vid][:]
            old_best_len = best_len[:]
            old_best_val = best_val[:]
            old_second_len = second_len[:]

            new_row = [0] * (k + 1)
            for t in range(k + 1):
                same = old_row[t] + 1
                switch = 0
                if t > 0:
                    if old_best_val[t - 1] != vid:
                        switch = old_best_len[t - 1] + 1
                    else:
                        switch = old_second_len[t - 1] + 1
                new_row[t] = max(old_row[t], same, switch)

            dp[vid] = new_row

            for t in range(k + 1):
                val_len = new_row[t]
                if val_len > best_len[t]:
                    # Promote previous best to second best
                    prev_best_len = best_len[t]
                    best_len[t] = val_len
                    best_val[t] = vid
                    if prev_best_len > second_len[t]:
                        second_len[t] = prev_best_len
                elif vid != best_val[t] and val_len > second_len[t]:
                    second_len[t] = val_len

        return max(best_len)

