from typing import List

class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        sumAcc = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]

        # 2D prefix sums for fast region sum
        ps = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            run = 0
            for j in range(n):
                run += image[i][j]
                ps[i + 1][j + 1] = ps[i][j + 1] + run

        def sum3x3(i: int, j: int) -> int:
            x1, y1 = i, j
            x2, y2 = i + 3, j + 3
            return ps[x2][y2] - ps[x1][y2] - ps[x2][y1] + ps[x1][y1]

        for i in range(m - 2):
            for j in range(n - 2):
                valid = True
                for r in range(i, i + 3):
                    row = image[r]
                    if (abs(row[j] - row[j + 1]) > threshold or
                        abs(row[j + 1] - row[j + 2]) > threshold):
                        valid = False
                        break
                if not valid:
                    continue
                for c in range(j, j + 3):
                    if (abs(image[i][c] - image[i + 1][c]) > threshold or
                        abs(image[i + 1][c] - image[i + 2][c]) > threshold):
                        valid = False
                        break
                if not valid:
                    continue

                avg = sum3x3(i, j) // 9

                for r in range(i, i + 3):
                    saRow = sumAcc[r]
                    cntRow = cnt[r]
                    for c in range(j, j + 3):
                        saRow[c] += avg
                        cntRow[c] += 1

        result = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if cnt[i][j] > 0:
                    result[i][j] = sumAcc[i][j] // cnt[i][j]
                else:
                    result[i][j] = image[i][j]
        return result

