class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        rows, cols = len(image), len(image[0])
        agg = [[0] * cols for _ in range(rows)]
        count = [[0] * cols for _ in range(rows)]

        for r0 in range(rows - 2):
            for c0 in range(cols - 2):
                ok = True
                for rr in range(r0, r0 + 3):
                    line = image[rr]
                    if abs(line[c0] - line[c0 + 1]) > threshold or abs(line[c0 + 1] - line[c0 + 2]) > threshold:
                        ok = False
                        break
                if not ok:
                    continue
                for cc in range(c0, c0 + 3):
                    if abs(image[r0][cc] - image[r0 + 1][cc]) > threshold or abs(image[r0 + 1][cc] - image[r0 + 2][cc]) > threshold:
                        ok = False
                        break
                if not ok:
                    continue

                total = sum(sum(row[c0:c0 + 3]) for row in image[r0:r0 + 3])
                avg_val = total // 9

                for rr in range(r0, r0 + 3):
                    for cc in range(c0, c0 + 3):
                        agg[rr][cc] += avg_val
                        count[rr][cc] += 1

        return [[(agg[i][j] // count[i][j]) if count[i][j] else image[i][j] for j in range(cols)] for i in range(rows)]

