from typing import List

class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        sumAcc = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]

        def valid_sub(i: int, j: int) -> bool:
            for r in range(i, i + 3):
                if abs(image[r][j] - image[r][j + 1]) > threshold or abs(image[r][j + 1] - image[r][j + 2]) > threshold:
                    return False
            for c in range(j, j + 3):
                if abs(image[i][c] - image[i + 1][c]) > threshold or abs(image[i + 1][c] - image[i + 2][c]) > threshold:
                    return False
            return True

        def region_avg(i: int, j: int) -> int:
            s = 0
            for r in range(i, i + 3):
                for c in range(j, j + 3):
                    s += image[r][c]
            return s // 9

        def accumulate(i: int, j: int, avg: int) -> None:
            for r in range(i, i + 3):
                saRow = sumAcc[r]
                cntRow = cnt[r]
                for c in range(j, j + 3):
                    saRow[c] += avg
                    cntRow[c] += 1

        for i in range(m - 2):
            for j in range(n - 2):
                if not valid_sub(i, j):
                    continue
                avg = region_avg(i, j)
                accumulate(i, j, avg)

        result = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if cnt[i][j] > 0:
                    result[i][j] = sumAcc[i][j] // cnt[i][j]
                else:
                    result[i][j] = image[i][j]
        return result

