class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        sumAcc = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]

        i = 0
        while i <= m - 3:
            j = 0
            while j <= n - 3:
                valid = True

                r = i
                while r < i + 3:
                    row = image[r]
                    if abs(row[j] - row[j + 1]) > threshold or abs(row[j + 1] - row[j + 2]) > threshold:
                        valid = False
                        break
                    r += 1
                if valid:
