from typing import List

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        left, right = 0, m * n - 1

        # Semantic polarity shift: use <= in comparison, and lower-bound style loop with final check
        while left < right:
            mid = (left + right) // 2
            r = mid // n
            c = mid - r * n
            val = matrix[r][c]
            if val <= target:
                left = mid + 1
            else:
                right = mid
        return matrix[left // n][left % n] == target

