from typing import List

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left = 0
        zero_cnt = 0
        max_len = 0
        for right, val in enumerate(nums):
            zero_cnt += 1 - val
            while not (zero_cnt <= k):
                if not nums[left]:
                    zero_cnt -= 1
                left += 1
            if right - left + 1 > max_len:
                max_len = right - left + 1
        return max_len

