from typing import Optional

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def gameResult(self, head: Optional['ListNode']) -> str:
        def tally(node: Optional['ListNode']) -> tuple[int, int]:
            if not node or not node.next:
                return (0, 0)
            even_inc = 1 if node.val > node.next.val else 0
            odd_inc = 0 if node.val > node.next.val else 1
            e_next, o_next = tally(node.next.next)
            return (even_inc + e_next, odd_inc + o_next)

        even_points, odd_points = tally(head)
        if even_points > odd_points:
            return "Even"
        if odd_points > even_points:
            return "Odd"
        return "Tie"

