from typing import Optional

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def gameResult(self, head: Optional['ListNode']) -> str:
        # Algorithm variant: convert linked list to array of values, then scan in steps of 2
        vals = []
        node = head
        while node:
            vals.append(node.val)
            node = node.next
        total_pairs = len(vals) // 2
        even_points = sum(1 for i in range(0, len(vals), 2) if vals[i] > vals[i + 1])
        odd_points = total_pairs - even_points  # award Odd on ties and when odd value is greater
        if even_points == odd_points:
            return "Tie"
        return "Even" if even_points > odd_points else "Odd"

