#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def gameResult(self, head: Optional['ListNode']) -> str:
        def pair_iter(start: Optional['ListNode']) -> Iterator[Tuple[int, int]]:
            node = start
            while node and node.next:
                yield (node.val, node.next.val)
                node = node.next.next

