from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        if k > n - 1:
            return -1

        adj = [[] for _ in range(n)]
        for a, b, w in highways:
            adj[a].append((b, w))
            adj[b].append((a, w))

        current = {}
        for i in range(n):
