    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        if k > n - 1:
            return -1

        adj = [[] for _ in range(n)]
        for a, b, w in highways:
            adj[a].append((b, w))
            adj[b].append((a, w))

        max_mask = 1 << n
        dp = [[-1] * n for _ in range(max_mask)]
        for i in range(n):
            dp[1 << i][i] = 0

        def process_mask(mask: int, level: int) -> int:
            local_best = -1
            t = mask
            while t:
                lsb = t & -t
                v = lsb.bit_length() - 1
                t ^= lsb
                prev_mask = mask ^ (1 << v)
                best_val = -1
                for u, w in adj[v]:
                    if (prev_mask >> u) & 1:
                        prev_val = dp[prev_mask][u]
                        if prev_val != -1:
                            cand = prev_val + w
                            if cand > best_val:
                                best_val = cand
                dp[mask][v] = best_val
                if level == k + 1 and best_val != -1:
                    if best_val > local_best:
                        local_best = best_val
            return local_best

