# Mutation 1
from typing import Optional

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        def walk(n, acc):
            if n is None:
                return 0
            nxt = acc * 10 + n.val
            if n.left is None and n.right is None:
                return nxt
            return sum(walk(ch, nxt) for ch in (n.left, n.right))
        return walk(root, 0)

