from typing import List
from collections import deque

class Solution:
    def minimumObstacles(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        total = rows * cols
        INF = 10**9
        cost = [INF] * total
        cost[0] = 0
        q = deque([0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            cur = q.popleft()
            if cur == total - 1:
                return cost[cur]

            r, c = divmod(cur, cols)
            current_cost = cost[cur]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    ni = nr * cols + nc
                    w = grid[nr][nc]
                    new_cost = current_cost + w
                    if new_cost < cost[ni]:
                        cost[ni] = new_cost
                        if w == 0:
                            q.appendleft(ni)
                        else:
                            q.append(ni)

        return cost[total - 1]

