from typing import List
import heapq

class Solution:
    def minimumObstacles(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        INF = 10**9
        dist = [[INF] * n for _ in range(m)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]  # (cost, r, c)

        while pq:
            d, r, c = heapq.heappop(pq)
            if (r, c) == (m - 1, n - 1):
                return d
            if d != dist[r][c]:
                continue

            if r > 0:
                nd = d + grid[r - 1][c]
                if nd < dist[r - 1][c]:
                    dist[r - 1][c] = nd
                    heapq.heappush(pq, (nd, r - 1, c))
            if r + 1 < m:
                nd = d + grid[r + 1][c]
                if nd < dist[r + 1][c]:
                    dist[r + 1][c] = nd
                    heapq.heappush(pq, (nd, r + 1, c))
            if c > 0:
                nd = d + grid[r][c - 1]
                if nd < dist[r][c - 1]:
                    dist[r][c - 1] = nd
                    heapq.heappush(pq, (nd, r, c - 1))
            if c + 1 < n:
                nd = d + grid[r][c + 1]
                if nd < dist[r][c + 1]:
                    dist[r][c + 1] = nd
                    heapq.heappush(pq, (nd, r, c + 1))

        return dist[m - 1][n - 1]

