class Solution:
    def minimumObstacles(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        total = m * n
        INF = 10**9
        dist = [INF] * total
        dist[0] = 0

        q = deque([0])
        in_queue = [False] * total
        in_queue[0] = True

        while q:
            idx = q.popleft()
            in_queue[idx] = False
            r, c = divmod(idx, n)
            base = dist[idx]

            # Up
            if r > 0:
                ni = idx - n
                nd = base + grid[r - 1][c]
                if nd < dist[ni]:
                    dist[ni] = nd
                    if not in_queue[ni]:
                        in_queue[ni] = True
                        q.append(ni)

            # Down
            if r + 1 < m:
                ni = idx + n
                nd = base + grid[r + 1][c]
                if nd < dist[ni]:
                    dist[ni] = nd
                    if not in_queue[ni]:
                        in_queue[ni] = True
                        q.append(ni)

            # Left
            if c > 0:
                ni = idx - 1
                nd = base + grid[r][c - 1]
                if nd < dist[ni]:
                    dist[ni] = nd
                    if not in_queue[ni]:
                        in_queue[ni] = True
                        q.append(ni)

            # Right
            if c + 1 < n:
                ni = idx + 1
                nd = base + grid[r][c + 1]
                if nd < dist[ni]:
                    dist[ni] = nd
                    if not in_queue[ni]:
                        in_queue[ni] = True
                        q.append(ni)

        return dist[total - 1]

