class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        MOD = 10**9 + 7
        k = min(n, target // 2)
        remaining = n - k
        total = k * (k + 1) // 2
        if remaining:
            total += remaining * target + (remaining * (remaining - 1)) // 2
        return total % MOD

