class Solution:
    def minMaxDifference(self, num: int) -> int:
        # Convert number to list of digits (most significant first) using arithmetic
        n = num
        digits = []
        while n > 0:
            digits.append(n % 10)
            n //= 10
        digits.reverse()

        # Compute maximum by replacing first digit != 9 with 9 across all occurrences
        max_digits = digits[:]
        rep = None
        for d in max_digits:
            if d != 9:
                rep = d
                break
        if rep is not None:
            max_digits = [9 if x == rep else x for x in max_digits]

        # Compute minimum by replacing first digit != 0 with 0 across all occurrences
        min_digits = digits[:]
        rep2 = None
        for d in min_digits:
            if d != 0:
                rep2 = d
                break
        if rep2 is not None:
            min_digits = [0 if x == rep2 else x for x in min_digits]

        # Convert digit lists back to integers
        max_val = 0
        for d in max_digits:
            max_val = max_val * 10 + d

        min_val = 0
        for d in min_digits:
            min_val = min_val * 10 + d

        return max_val - min_val

