from typing import List

class Solution:
    def countCharacters(self, words: List[str], chars: str) -> int:
        freq = [0] * 26
        for ch in chars:
            freq[ord(ch) - 97] += 1
        ans = 0
        for word in words:
            counts = [0] * 26
            ok = True
            for ch in word:
                idx = ord(ch) - 97
                counts[idx] += 1
                if counts[idx] > freq[idx]:
                    ok = False
                    break
            if ok:
                ans += len(word)
        return ans

