from typing import List

class Solution:
    def maximumDifference(self, nums: List[int]) -> int:
        smallest = nums[0]
        best = -1
        for idx in range(1, len(nums)):
            val = nums[idx]
            if val > smallest:
                diff = val - smallest
                if diff > best:
                    best = diff
            if val < smallest:
                smallest = val
        return best

