import bisect

class Solution:
    def numJewelsInStones(self, jewels: str, stones: str) -> int:
        sorted_jewels = sorted(jewels)
        cnt = 0
        for c in stones:
            idx = bisect.bisect_left(sorted_jewels, c)
            if idx < len(sorted_jewels) and sorted_jewels[idx] == c:
                cnt += 1
        return cnt

