import math

class Solution:
    def minScoreTriangulation(self, values: List[int]) -> int:
        n = len(values)
        table = [[0] * n for _ in range(n)]
        for span in range(2, n):
            for left in range(n - span):
                right = left + span
                best_cost = math.inf
                for mid in range(left + 1, right):
                    candidate = table[left][mid] + table[mid][right] + values[left] * values[mid] * values[right]
                    if candidate < best_cost:
                        best_cost = candidate
                table[left][right] = 0 if best_cost is math.inf else best_cost
        return table[0][n - 1]

