```python
from typing import List

class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0

        # Precompute prefix sums per column: pref[col][t] = sum_{i=0..t-1} grid[i][col]
        pref = [[0] * (n + 1) for _ in range(n)]
        for j in range(n):
            pj = pref[j]
            s = 0
            for i in range(n):
                s += grid[i][j]
                pj[i + 1] = s

        NEG = -10**30

        # Helper to compute pair contribution between columns j and j+1
        def pair_cost(j: int, dj: int, dk: int) -> int:
            if dj < dk:
                return pref[j][dk] - pref[j][dj]
            elif dk < dj:
                return pref[j + 1][dj] - pref[j + 1][dk]
            else:
                return 0

        # Initialize dp for the first pair of columns (0 and 1):
        # dp[d0][d1] = Pair(0, d0, d1)
        size = n + 1
        dp = [[NEG] * size for _ in range(size)]
        for d0 in range(size):
            for d1 in range(size):
                dp[d0][d1] = pair_cost(0, d0, d1)

        # Process columns j=1..n-2
        for j in range(1, n - 1):
            next_dp = [[NEG] * size for _ in range(size)]
            pref_j = pref[j]
            pref_j1 = pref[j + 1]

            for dj in range(size):
                # Build A[K] = max_{p<=K} dp[p][dj] - max(0, pref_j[p] - pref_j[dj])
                A = [NEG] * size
                run = NEG
                base_dj = pref_j[dj]
                for K in range(size):
                    p = K
                    val = dp[p][dj]
                    delta = pref_j[p] - base_dj
                    if delta > 0:
                        val -= delta
                    if val > run:
                        run = val
                    A[K] = run

                # Build Suf[p] = max_{t>=p} dp[t][dj], length n+2 so Suf[n+1]=NEG
                Suf = [NEG] * (size + 1)
                for p in range(size - 1, -1, -1):
                    v = dp[p][dj]
                    if Suf[p + 1] > v:
                        Suf[p] = Suf[p + 1]
                    else:
                        Suf[p] = v

                # For each dk, compute best previous and add pair cost
                for dk in range(size):
                    # Case d_{j-1} <= dk
                    best_prev = A[dk]
                    # Case d_{j-1} > dk
                    other = Suf[dk + 1] if dk < n else NEG
                    if other != NEG:
                        delta2 = pref_j[dk] - base_dj
                        if delta2 > 0:
                            best_prev = max(best_prev, other - delta2)
                        else:
                            best_prev = max(best_prev, other)

                    # Add pair contribution between columns j and j+1
                    pc = pair_cost(j, dj, dk)
                    total = best_prev + pc
                    next_dp[dj][dk] = total

            dp = next_dp

        # The answer is the maximum over last dp
        ans = NEG
        for row in dp:
            row_max = max(row)
            if row_max > ans:
                ans = row_max
        return ans
```

final_answer:
from typing import List

class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0

        # prefix sums per column: pref[col][t] = sum grid[0..t-1][col]
        size = n + 1
        pref = [[0] * size for _ in range(n)]
        for col in range(n):
            acc = 0
            col_pref = pref[col]
            for r in range(n):
                acc += grid[r][col]
                col_pref[r + 1] = acc

        NEG = -10**30

        def pair_contrib(col: int, cut_left: int, cut_right: int) -> int:
            if cut_left < cut_right:
                return pref[col][cut_right] - pref[col][cut_left]
            elif cut_right < cut_left:
                return pref[col + 1][cut_left] - pref[col + 1][cut_right]
            return 0

        # dp for first pair (columns 0 and 1)
        dp = [[NEG] * size for _ in range(size)]
        for c0 in range(size):
            row = dp[c0]
            for c1 in range(size):
                row[c1] = pair_contrib(0, c0, c1)

        # iterate over column pairs (j, j+1) for j=1..n-2
        for j in range(1, n - 1):
            nxt = [[NEG] * size for _ in range(size)]
            pj = pref[j]

            for dj in range(size):
                base_d = pj[dj]

                # Build A[K] = max_{p<=K} dp[p][dj] - max(0, pref_j[p] - pref_j[dj])
                A = [NEG] * size
                running = NEG
                for K in range(size):
                    p = K
                    v = dp[p][dj]
                    delta = pj[p] - base_d
                    if delta > 0:
                        v -= delta
                    if v > running:
                        running = v
                    A[K] = running

                # Build Suf[p] = max_{t>=p} dp[t][dj]
                Suf = [NEG] * (size + 1)
                best = NEG
                for p in range(size - 1, -1, -1):
                    val = dp[p][dj]
                    if val > best:
                        best = val
                    Suf[p] = best

                for dk in range(size):
                    cand = A[dk]
                    other = Suf[dk + 1] if dk < n else NEG
                    if other != NEG:
                        d2 = pj[dk] - base_d
                        if d2 > 0:
                            cand = max(cand, other - d2)
                        else:
                            cand = max(cand, other)
                    nxt[dj][dk] = cand + pair_contrib(j, dj, dk)

            dp = nxt

        ans = NEG
        for r in dp:
            m = max(r)
            if m > ans:
                ans = m
        return ans

