class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0

        size = n + 1
        pref = [[0] * size for _ in range(n)]
        j = 0
        while j < n:
            s = 0
            i = 0
            while i < n:
                s += grid[i][j]
                pref[j][i + 1] = s
                i += 1
            j += 1

        NEG = -10**30

        def build_A_and_Suf(dp_col: List[List[int]], fixed_dj: int, pref_j: List[int]) -> (List[int], List[int]):
            A = [NEG] * size
            run = NEG
            base = pref_j[fixed_dj]

            K = 0
            while K < size:
                p = K
                val = dp_col[p][fixed_dj]
                delta = pref_j[p] - base
                if delta > 0:
                    val -= delta
                if val > run:
                    run = val
                A[K] = run
                K += 1

            Suf = [NEG] * (size + 1)
            p = size - 1
            best_here = NEG
            while p >= 0:
                v = dp_col[p][fixed_dj]
                if v > best_here:
                    best_here = v
                Suf[p] = best_here
                p -= 1
            return A, Suf

        def pair_cost(col_idx: int, dj: int, dk: int) -> int:
            if dj < dk:
                return pref[col_idx][dk] - pref[col_idx][dj]
            elif dk < dj:
                return pref[col_idx + 1][dj] - pref[col_idx + 1][dk]
            else:
                return 0

        dp = [[NEG] * size for _ in range(size)]
        d0 = 0
        while d0 < size:
            d1 = 0
            while d1 < size:
                dp[d0][d1] = pair_cost(0, d0, d1)
                d1 += 1
            d0 += 1

        j = 1
        while j < n - 1:
            next_dp = [[NEG] * size for _ in range(size)]
            pref_j = pref[j]

            dj = 0
            while dj < size:
                A, Suf = build_A_and_Suf(dp, dj, pref_j)
                dk = 0
                base_dj = pref_j[dj]
                while dk < size:
                    best_prev = A[dk]
                    if dk < n:
                        other = Suf[dk + 1]
                    else:
                        other = NEG
                    if other != NEG:
                        delta2 = pref_j[dk] - base_dj
                        if delta2 > 0:
                            if other - delta2 > best_prev:
                                best_prev = other - delta2
                        else:
                            if other > best_prev:
                                best_prev = other
                    next_dp[dj][dk] = best_prev + pair_cost(j, dj, dk)
                    dk += 1
                dj += 1
            dp = next_dp
            j += 1

        ans = NEG
        r = 0
        while r < size:
            c = 0
            while c < size:
                v = dp[r][c]
                if v > ans:
                    ans = v
                c += 1
            r += 1
        return ans

