from typing import List

class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0

        size = n + 1
        # Build column-wise prefix sums using a slightly different style
        pref = []
        for col in range(n):
            col_pref = [0] * size
            running = 0
            for r in range(n):
                running += grid[r][col]
                col_pref[r + 1] = running
            pref.append(col_pref)

        NEG = -(10**18)

        dp = [[NEG] * size for _ in range(size)]
        # Inline pair cost computation for initialization
        for d0 in range(size):
            base_col = 0
            for d1 in range(size):
                if d0 < d1:
                    dp[d0][d1] = pref[base_col][d1] - pref[base_col][d0]
                elif d1 < d0:
                    dp[d0][d1] = pref[base_col + 1][d0] - pref[base_col + 1][d1]
                else:
                    dp[d0][d1] = 0

        for j in range(1, n - 1):
            next_dp = [[NEG] * size for _ in range(size)]
            pj = pref[j]

            for dj in range(size):
                base_dj = pj[dj]

                # A[K] = max_{p<=K} dp[p][dj] - max(0, pj[p] - pj[dj])
                A = [NEG] * size
                best_so_far = NEG
                for K in range(size):
                    p = K
                    val = dp[p][dj]
                    excess = pj[p] - base_dj
                    if excess > 0:
                        val -= excess
                    if val > best_so_far:
                        best_so_far = val
                    A[K] = best_so_far

                # Suf[p] = max_{t>=p} dp[t][dj]
                Suf = [NEG] * (size + 1)
                cur = NEG
                for p in range(size - 1, -1, -1):
                    v = dp[p][dj]
                    if v > cur:
                        cur = v
                    Suf[p] = cur

                for dk in range(size):
                    # compute best_prev
                    best_prev = A[dk]
                    if dk < n:
                        other = Suf[dk + 1]
                    else:
                        other = NEG
                    if other != NEG:
                        d2 = pj[dk] - base_dj
                        if d2 > 0:
                            if other - d2 > best_prev:
                                best_prev = other - d2
                        else:
                            if other > best_prev:
                                best_prev = other

                    # inline pair cost for (j, j+1)
                    if dj < dk:
                        pc = pref[j][dk] - pref[j][dj]
                    elif dk < dj:
                        pc = pref[j + 1][dj] - pref[j + 1][dk]
                    else:
                        pc = 0

                    next_dp[dj][dk] = best_prev + pc

            dp = next_dp

        # Flatten and get max
        best = NEG
        for row in dp:
            m = max(row)
            if m > best:
                best = m
        return best

