from typing import List

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        n = len(image[0])

        def col_has_one(j: int) -> bool:
            for i in range(m):
                if image[i][j] == '1':
                    return True
            return False

        def row_has_one(i: int) -> bool:
            for j in range(n):
                if image[i][j] == '1':
                    return True
            return False

        def first_true(lo: int, hi: int, pred) -> int:
            while lo < hi:
                mid = (lo + hi) // 2
                if pred(mid):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        def last_true(lo: int, hi: int, pred) -> int:
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if pred(mid):
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        left = first_true(0, y, col_has_one)
        right = last_true(y, n - 1, col_has_one)
        top = first_true(0, x, row_has_one)
        bottom = last_true(x, m - 1, row_has_one)

        return (right - left + 1) * (bottom - top + 1)

