from typing import List
from collections import deque

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        n = len(image[0])

        q = deque()
        q.append((x, y))
        seen = set()
        seen.add((x, y))

        min_r = x
        max_r = x
        min_c = y
        max_c = y

        dirs = [(1,0), (-1,0), (0,1), (0,-1)]

        while q:
            i, j = q.popleft()
            if i < min_r:
                min_r = i
            if i > max_r:
                max_r = i
            if j < min_c:
                min_c = j
            if j > max_c:
                max_c = j

            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and (ni, nj) not in seen and image[ni][nj] == '1':
                    seen.add((ni, nj))
                    q.append((ni, nj))

        return (max_c - min_c + 1) * (max_r - min_r + 1)

