from typing import List

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        n = len(image[0])

        def col_has_one(j: int) -> bool:
            i = 0
            while i < m:
                if image[i][j] == '1':
                    return True
                i += 1
            return False

        def row_has_one(i: int) -> bool:
            j = 0
            while j < n:
                if image[i][j] == '1':
                    return True
                j += 1
            return False

        def search_left(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi) // 2
            if col_has_one(mid):
                return search_left(lo, mid)
            else:
                return search_left(mid + 1, hi)

        def search_right(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi + 1) // 2
            if col_has_one(mid):
                return search_right(mid, hi)
            else:
                return search_right(lo, mid - 1)

        def search_top(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi) // 2
            if row_has_one(mid):
                return search_top(lo, mid)
            else:
                return search_top(mid + 1, hi)

        def search_bottom(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi + 1) // 2
            if row_has_one(mid):
                return search_bottom(mid, hi)
            else:
                return search_bottom(lo, mid - 1)

        left = search_left(0, y)
        right = search_right(y, n - 1)
        top = search_top(0, x)
        bottom = search_bottom(x, m - 1)

        return (right - left + 1) * (bottom - top + 1)

