    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m, n = len(image), len(image[0])

        def row_has_black(r: int) -> bool:
            return any(image[r][c] == '1' for c in range(n))

        def col_has_black(c: int) -> bool:
            return any(image[r][c] == '1' for r in range(m))

        top_l, top_r = 0, x
        while top_l < top_r:
            mid = (top_l + top_r) // 2
            if row_has_black(mid):
                top_r = mid
            else:
                top_l = mid + 1
        top = top_l

        bottom_l, bottom_r = x, m
        while bottom_l < bottom_r:
            mid = (bottom_l + bottom_r) // 2
            if row_has_black(mid):
                bottom_l = mid + 1
            else:
                bottom_r = mid
        bottom = bottom_l

        left_l, left_r = 0, y
        while left_l < left_r:
            mid = (left_l + left_r) // 2
            if col_has_black(mid):
                left_r = mid
            else:
                left_l = mid + 1
        left = left_l

        right_l, right_r = y, n
        while right_l < right_r:
            mid = (right_l + right_r) // 2
            if col_has_black(mid):
                right_l = mid + 1
            else:
                right_r = mid
        right = right_l

        return (bottom - top) * (right - left)

