from typing import List

class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        # Structural Transformation: recursive binary search
        def enough(t: int) -> bool:
            trips = 0
            for d in time:
                trips += t // d
                if trips >= totalTrips:
                    return True
            return False

        def bsearch(lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi) // 2
            if enough(mid):
                return bsearch(lo, mid)
            else:
                return bsearch(mid + 1, hi)

        return bsearch(1, min(time) * totalTrips)

