from typing import List
import heapq

class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        # Algorithm/Data-Structure Variant: simulate with a min-heap of next finish times
        # Each heap entry: (next_finish_time, bus_period)
        heap = [(t, t) for t in time]
        heapq.heapify(heap)

        trips_done = 0
        current_time = 0

        while trips_done < totalTrips:
            current_time, period = heapq.heappop(heap)
            trips_done += 1
            heapq.heappush(heap, (current_time + period, period))

        return current_time

