class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        below_20 = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
                    "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
                    "Seventeen", "Eighteen", "Nineteen"]
        tens = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        def two(n: int) -> str:
            if n == 0:
                return ""
            if n < 20:
                return below_20[n]
            tenner = n // 10
            rest = n % 10
            if rest:
                return tens[tenner] + " " + below_20[rest]
            else:
                return tens[tenner]

        def three(n: int) -> str:
            hundred = n // 100
            rest = n % 100
            if hundred and rest:
                return below_20[hundred] + " Hundred " + two(rest)
            elif hundred and not rest:
                return below_20[hundred] + " Hundred"
            else:
                return two(rest)

        billion = num // 1_000_000_000
        million = (num // 1_000_000) % 1000
        thousand = (num // 1_000) % 1000
        rest = num % 1000

        parts = []
        if billion:
            parts.append(three(billion) + " Billion")
        if million:
            parts.append(three(million) + " Million")
        if thousand:
            parts.append(three(thousand) + " Thousand")
        if rest:
            parts.append(three(rest))

        return " ".join(parts)
