class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        under_twenty = [
            "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
            "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
            "Seventeen", "Eighteen", "Nineteen"
        ]
        tens_names = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        def to_two(n: int) -> str:
            if n == 0:
                return ""
            if n < 20:
                return under_twenty[n]
            ten_part = n // 10
            unit_part = n % 10
            return tens_names[ten_part] if unit_part == 0 else tens_names[ten_part] + " " + under_twenty[unit_part]

        def to_three(n: int) -> str:
            h = n // 100
            r = n % 100
            if h:
                res = under_twenty[h] + " Hundred"
                if r:
                    res += " " + to_two(r)
                return res
            else:
                return to_two(r)

        segments = [
            (num // 1_000_000_000, "Billion"),
            ((num // 1_000_000) % 1000, "Million"),
            ((num // 1000) % 1000, "Thousand"),
            (num % 1000, "")
        ]

        parts = []
        for val, name in segments:
            if val:
                segment = to_three(val)
                parts.append(segment if name == "" else f"{segment} {name}")

        return " ".join(parts)

