class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        below_20 = [
            "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
            "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
            "Seventeen", "Eighteen", "Nineteen"
        ]
        tens = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        def words_under_thousand(n: int) -> str:
            parts = []
            h = n // 100
            r = n % 100
            if h:
                parts.append(below_20[h])
                parts.append("Hundred")
            if r:
                if r < 20:
                    parts.append(below_20[r])
                else:
                    t = r // 10
                    u = r % 10
                    parts.append(tens[t])
                    if u:
                        parts.append(below_20[u])
            return " ".join(parts)

        billion = num // 1_000_000_000
        million = (num // 1_000_000) % 1000
        thousand = (num // 1_000) % 1000
        rest = num % 1000

        scales = ["Billion", "Million", "Thousand", ""]
        values = [billion, million, thousand, rest]
        result = []
        i = 0
        while i < 4:
            val = values[i]
            if val:
                chunk = words_under_thousand(val)
                if scales[i]:
                    result.append(chunk + " " + scales[i])
                else:
                    result.append(chunk)
            i += 1

        return " ".join(result)

