from functools import lru_cache

class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        below_20 = [
            "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
            "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
            "Seventeen", "Eighteen", "Nineteen"
        ]
        tens = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        @lru_cache(None)
        def chunk_to_words(n: int) -> str:
            if n == 0:
                return ""
            if n < 20:
                return below_20[n]
            if n < 100:
                return tens[n // 10] if n % 10 == 0 else tens[n // 10] + " " + below_20[n % 10]
            h = n // 100
            r = n % 100
            return below_20[h] + " Hundred" + ("" if r == 0 else " " + chunk_to_words(r))

        scales = [
            (1_000_000_000, "Billion"),
            (1_000_000, "Million"),
            (1_000, "Thousand"),
            (1, "")
        ]

        parts = []
        for value, name in scales:
            if num >= value:
                chunk = num // value
                if chunk:
                    words = chunk_to_words(chunk)
                    parts.append(words if name == "" else words + " " + name)
                num %= value

        return " ".join(parts)

