        def label(rank_num: int) -> str:
            if rank_num == 1:
                return "Gold Medal"
            if rank_num == 2:
                return "Silver Medal"
            if rank_num == 3:
                return "Bronze Medal"
            return str(rank_num)

        n = len(score)
        ans = [""] * n
        order = sorted(range(n), key=lambda i: -score[i])
        k = 0
