class Solution:
    def isItPossible(self, word1: str, word2: str) -> bool:
        freq1 = [0] * 26
        freq2 = [0] * 26

        base = ord('a')
        for ch in word1:
            freq1[ord(ch) - base] += 1
        for ch in word2:
            freq2[ord(ch) - base] += 1

        uniq1 = sum(1 for v in freq1 if v)
        uniq2 = sum(1 for v in freq2 if v)

        for i in range(26):
            if not freq1[i]:
