                if i == j:
                    if uniq1 == uniq2:
                        return True
                    continue

                n1 = uniq1
                n2 = uniq2

                if freq1[i] == 1:
                    n1 -= 1
                if freq1[j] == 0:
                    n1 += 1

                if freq2[j] == 1:
                    n2 -= 1
                if freq2[i] == 0:
                    n2 += 1

                if n1 == n2:
                    return True

        return False

