        d1 = sum(1 for x in cnt1 if x > 0)
        d2 = sum(1 for x in cnt2 if x > 0)

        def try_j(i: int, j: int) -> bool:
            if j == 26:
                return False
            if cnt2[j] == 0:
                return try_j(i, j + 1)
            if i == j:
