from typing import List

class Solution:
    def decode(self, encoded: List[int]) -> List[int]:
        n = len(encoded) + 1

        total = 0
        for i in range(1, n + 1):
            total ^= i

        odd = 0
        for i in range(1, len(encoded), 2):
            odd ^= encoded[i]

        first = total ^ odd

        perm = [first]
        for val in encoded:
            perm.append(perm[-1] ^ val)

        return perm

from typing import List

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        sumA = sum(nums1)
        sumB = sum(nums2)
        pairs = sorted(zip(nums1, nums2), key=lambda p: p[1])  # sort by b ascending

        # dp[j] = max total reduction by selecting j indices, where the j-th gets s = j
        NEG = -10**18
        dp = [NEG] * (n + 1)
        dp[0] = 0
        for a, b in pairs:
            for j in range(n, 0, -1):
                if dp[j - 1] != NEG:
                    dp[j] = max(dp[j], dp[j - 1] + a + b * j)

        # best[j] = max reduction achievable using up to j selections
        best = [0] * (n + 1)
        best[0] = dp[0]
        for j in range(1, n + 1):
            best[j] = max(best[j - 1], dp[j])

        for t in range(n + 1):
            final_sum = sumA + t * sumB - best[t]
            if final_sum <= x:
                return t
        return -1

from typing import List

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def collect(text: str, pattern: str) -> List[int]:
            out: List[int] = []
            t = text.find(pattern)
            while t != -1:
                out.append(t)
                t = text.find(pattern, t + 1)
            return out

        posA = collect(s, a)
        posB = collect(s, b)
        if not posB:
            return []

        ans: List[int] = []
        p = 0
        m = len(posB)
        for x in posA:
            left = x - k
            right = x + k
            while p < m and posB[p] < left:
                p += 1
            if p < m and posB[p] <= right:
                ans.append(x)
        return ans

