from typing import List

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        top1 = [-1] * 10
        top2 = [-1] * 10

        def maxdigit(v: int) -> int:
            m = 0
            x = v
            while x:
                r = x % 10
                if r > m:
                    m = r
                x //= 10
            return m

        for val in nums:
            d = maxdigit(val)
            if val >= top1[d]:
                top2[d] = top1[d]
                top1[d] = val
            elif val > top2[d]:
                top2[d] = val

        best = -1
        for d in range(10):
            if top2[d] != -1:
                s = top1[d] + top2[d]
                if s > best:
                    best = s
        return best

