            m = 0
            y = x
            while y:
                d = y % 10
                if d > m:
                    m = d
                y //= 10
            return m

        clusters: dict[int, list[int]] = {}
        i = 0
        n = len(nums)
        while i < n:
            num = nums[i]
            ld = largest_digit(num)
            if ld in clusters:
