import heapq

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        heaps = {}
        for num in nums:
            d = max(map(int, str(num)))
            if d not in heaps:
                heaps[d] = []
            heap = heaps[d]
            heapq.heappush(heap, num)
            if len(heap) > 2:
                heapq.heappop(heap)
        ans = -1
        for h in heaps.values():
            if len(h) >= 2:
                s = sum(h)
                if s > ans:
                    ans = s
        return ans

