from typing import List

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        n = len(arr)
        m = arr[(n - 1) // 2]
        l, r = 0, n - 1
        res = []
        for _ in range(k):
            if abs(arr[l] - m) > abs(arr[r] - m):
                res.append(arr[l])
                l += 1
            else:
                res.append(arr[r])
                r -= 1
        return res

