class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        size = len(arr)
        median = arr[(size - 1) // 2]
        left, right = 0, size - 1
        result: List[int] = []
        remaining = k
        while remaining:
            if abs(arr[left] - median) > abs(arr[right] - median):
                result.append(arr[left])
                left += 1
            else:
                result.append(arr[right])
                right -= 1
            remaining -= 1
        return result

