class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        n = len(arr)
        m = arr[(n - 1) // 2]

        def left_is_stronger(l_idx: int, r_idx: int) -> bool:
            return abs(arr[l_idx] - m) > abs(arr[r_idx] - m)

        i, j = 0, n - 1
        ans: List[int] = []
        for _ in range(k):
