from typing import List

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        n = len(arr)
        m = arr[(n - 1) // 2]

        def pick(l: int, r: int, remain: int) -> List[int]:
            if remain == 0:
                return []
            if abs(arr[l] - m) > abs(arr[r] - m):
                return [arr[l]] + pick(l + 1, r, remain - 1)
            else:
                return [arr[r]] + pick(l, r - 1, remain - 1)

        return pick(0, n - 1, k)

