class Solution:
    def threeSumSmaller(self, nums: List[int], target: int) -> int:
        nums.sort()
        n = len(nums)
        res = 0
        for i in range(n - 2):
            for j in range(i + 1, n - 1):
                limit = target - nums[i] - nums[j]
                pos = bisect_left(nums, limit, j + 1, n)
                add = pos - (j + 1)
                if add > 0:
                    res += add
        return res

