from functools import lru_cache

class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        # pair[cur][neighbor], 0 empty, 1 intro, 2 extro; combined edge contribution
        pair = (
            (0, 0, 0),
            (0, -60, -10),
            (0, -10, 40),
        )

        total_cells = m * n
        pow3n = 3 ** n

        @lru_cache(None)
        def dfs(pos: int, mask: int, rem_i: int, rem_e: int) -> int:
            if pos == total_cells:
                return 0

            r = pos // n
            c = pos % n

            left_type = mask % 3  # last placed cell in row-major order
            up_type = (mask // (3 ** (n - 1))) % 3  # cell n steps behind

            best = dfs(pos + 1, (mask * 3) % pow3n, rem_i, rem_e)  # leave empty: type 0

            # place introvert
            if rem_i > 0:
                t = 1
                gain = 120
                if c > 0 and left_type != 0:
                    gain += pair[t][left_type]
                if r > 0 and up_type != 0:
                    gain += pair[t][up_type]
                best = max(best, gain + dfs(pos + 1, ((mask * 3 + t) % pow3n), rem_i - 1, rem_e))

            # place extrovert
            if rem_e > 0:
                t = 2
                gain = 40
                if c > 0 and left_type != 0:
                    gain += pair[t][left_type]
                if r > 0 and up_type != 0:
                    gain += pair[t][up_type]
                best = max(best, gain + dfs(pos + 1, ((mask * 3 + t) % pow3n), rem_i, rem_e - 1))

            return best

        return dfs(0, 0, introvertsCount, extrovertsCount)

