class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        total = 3 ** n

        adj = (
            (0, 0, 0),
            (0, -60, -10),
            (0, -10, 40),
        )

        def unpack(x: int):
            res = []
            for _ in range(n):
                res.append(x % 3)
                x //= 3
            return res

        valid_states = []
        cols = []
        num_in = []
        num_ex = []
        intra_row = []

        for s in range(total):
            arr = unpack(s)
            i_cnt = arr.count(1)
            e_cnt = arr.count(2)
            if i_cnt <= introvertsCount and e_cnt <= extrovertsCount:
                gain = 0
                for c in range(n):
                    t = arr[c]
                    if t == 1:
                        gain += 120
                    elif t == 2:
                        gain += 40
                    if c:
                        lt = arr[c - 1]
                        if t and lt:
                            gain += adj[t][lt]
                valid_states.append(s)
                cols.append(arr)
                num_in.append(i_cnt)
                num_ex.append(e_cnt)
                intra_row.append(gain)

        size = len(valid_states)
        idx_of = {s: i for i, s in enumerate(valid_states)}

        if 0 not in idx_of:
            valid_states.append(0)
            cols.append([0] * n)
            num_in.append(0)
            num_ex.append(0)
            intra_row.append(0)
            idx_of[0] = size
            size += 1

        inter = [[0] * size for _ in range(size)]
        for i in range(size):
            up = cols[i]
            for j in range(size):
                cur = cols[j]
                v = 0
                for c in range(n):
                    if up[c] and cur[c]:
                        v += adj[cur[c]][up[c]]
                inter[i][j] = v

        best = {(introvertsCount, extrovertsCount, idx_of[0]): 0}

        for _ in range(m):
            nxt = {}
            for (ri, re, prev_idx), base in best.items():
                for s_idx in range(size):
                    ci = num_in[s_idx]
                    ce = num_ex[s_idx]
                    if ci <= ri and ce <= re:
                        val = base + intra_row[s_idx] + inter[prev_idx][s_idx]
                        key = (ri - ci, re - ce, s_idx)
                        old = nxt.get(key)
                        if old is None or val > old:
                            nxt[key] = val
            best = nxt

        return max(best.values()) if best else 0

