    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        total_states = 3 ** n
        pair = [[0, 0, 0], [0, -60, -10], [0, -10, 40]]

        def decode_state(s):
            out = []
            k = 0
            while k < n:
                out.append(s % 3)
                s //= 3
                k += 1
            return out

        def compute_row_info(t):
            i_count = t.count(1)
            e_count = t.count(2)
            if i_count > introvertsCount or e_count > extrovertsCount:
                return False, 0, 0, 0
            val = 0
            c = 0
            while c < n:
                tc = t[c]
                if tc == 1:
                    val += 120
                elif tc == 2:
                    val += 40
                if c > 0:
                    tl = t[c - 1]
                    if tc != 0 and tl != 0:
                        val += pair[tc][tl]
                c += 1
            return True, i_count, e_count, val

        states = []
        types_list = []
        cntI = []
        cntE = []
        intra = []

        s = 0
        while s < total_states:
            t = decode_state(s)
            ok, i_count, e_count, val = compute_row_info(t)
            if ok:
                states.append(s)
                types_list.append(t)
                cntI.append(i_count)
                cntE.append(e_count)
                intra.append(val)
            s += 1

        num_states = len(states)
        state_to_idx = {s: idx for idx, s in enumerate(states)}

        if 0 not in state_to_idx:
            states.append(0)
            types_list.append([0] * n)
            cntI.append(0)
            cntE.append(0)
            intra.append(0)
            state_to_idx[0] = num_states
            num_states += 1

        def inter_val(i, j):
            up = types_list[i]
            cur = types_list[j]
            c = 0
            v = 0
            while c < n:
                if up[c] != 0 and cur[c] != 0:
                    v += pair[cur[c]][up[c]]
                c += 1
            return v

        inter = [[0] * num_states for _ in range(num_states)]
        i = 0
        while i < num_states:
            j = 0
            while j < num_states:
                inter[i][j] = inter_val(i, j)
                j += 1
            i += 1

        dp = {(introvertsCount, extrovertsCount, state_to_idx[0]): 0}

        row = 0
        while row < m:
            new_dp = {}
            for (rem_i, rem_e, prev_idx), base_val in dp.items():
                s_idx = 0
                while s_idx < num_states:
                    ci = cntI[s_idx]
                    ce = cntE[s_idx]
                    if ci <= rem_i and ce <= rem_e:
                        val = base_val + intra[s_idx] + inter[prev_idx][s_idx]
                        key = (rem_i - ci, rem_e - ce, s_idx)
                        cur = new_dp.get(key)
                        if cur is None or val > cur:
                            new_dp[key] = val
                    s_idx += 1
            dp = new_dp
            row += 1

        return max(dp.values()) if dp else 0

