from typing import List

class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        m = len(nums)
        if m < 3:
            return 0

        # residues
        rem = []
        for val in nums:
            rem.append(val % d)

        # left and right maps
        left = {rem[0]: 1}
        right = {}
        for idx in range(2, m):
            rv = rem[idx]
            right[rv] = right.get(rv, 0) + 1

        total = 0
        for mid in range(1, m - 1):
            rm = rem[mid]
            if len(left) <= len(right):
                total += sum(cnt_i * right.get((-(ri + rm)) % d, 0) for ri, cnt_i in left.items())
            else:
                total += sum(left.get((-(rk + rm)) % d, 0) * cnt_k for rk, cnt_k in right.items())

            # move current to left
            left[rm] = left.get(rm, 0) + 1

            # remove the next from right
            if mid + 1 < m:
                nxt = rem[mid + 1]
                c = right.get(nxt, 0)
                if c <= 1:
                    right.pop(nxt, None)
                else:
                    right[nxt] = c - 1

        return total

