from typing import List

class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        r = [x % d for x in nums]

        prefix = {r[0]: 1}
        suffix = {}
        for i in range(2, n):
            rr = r[i]
            suffix[rr] = suffix.get(rr, 0) + 1

        def add_contrib(pref: dict, suf: dict, mid_res: int, mod: int) -> int:
            acc = 0
            if len(pref) <= len(suf):
                for ri, ci in pref.items():
                    need = (-(ri + mid_res)) % mod
                    ck = suf.get(need, 0)
                    if ck:
                        acc += ci * ck
            else:
                for rk, ck in suf.items():
                    need = (-(rk + mid_res)) % mod
                    ci = pref.get(need, 0)
                    if ci:
                        acc += ci * ck
            return acc

        def dec_cnt(mp: dict, key: int) -> None:
            cnt = mp.get(key, 0)
            if cnt <= 1:
                mp.pop(key, None)
            else:
                mp[key] = cnt - 1

        ans = 0
        j = 1
        while j < n - 1:
            ans += add_contrib(prefix, suffix, r[j], d)
            prefix[r[j]] = prefix.get(r[j], 0) + 1
            if j + 1 < n:
                dec_cnt(suffix, r[j + 1])
            j += 1

        return ans

