from typing import List

class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        residues = [v % d for v in nums]

        pref = {residues[0]: 1}
        suff = {}
        for idx in range(2, n):
            rv = residues[idx]
            suff[rv] = suff.get(rv, 0) + 1

        res = 0
        for j in range(1, n - 1):
            rj = residues[j]

            # Invert branch choice: iterate over the larger map
            if len(pref) > len(suff):
                for ri, ci in pref.items():
                    want = (-(ri + rj)) % d
                    ck = suff.get(want, 0)
                    if ck:
                        res += ci * ck
            else:
                for rk, ck in suff.items():
                    need = (-(rk + rj)) % d
                    ci = pref.get(need, 0)
                    if ci:
                        res += ci * ck

            pref[rj] = pref.get(rj, 0) + 1

            if not (j + 1 >= n):
                nxt = residues[j + 1]
                cnt = suff.get(nxt, 0)
                if cnt <= 1:
                    suff.pop(nxt, None)
                else:
                    suff[nxt] = cnt - 1

        return res

