from typing import List

class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        r = [x % d for x in nums]

        # Maintain counts of single residues to the left
        left_single = {}
        # Maintain counts of pair residue sums for pairs (i, j) with i < j < current k
        pair_res_count = {}

        ans = 0
        for k in range(n):
            rk = r[k]
            need = (-rk) % d
            ans += pair_res_count.get(need, 0)

            # Update pair sums by pairing current element with all previous singles
            if left_single:
                for ra, ca in left_single.items():
                    s = (ra + rk) % d
                    pair_res_count[s] = pair_res_count.get(s, 0) + ca

            # Add current single residue
            left_single[rk] = left_single.get(rk, 0) + 1

        return ans

