class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        sys.setrecursionlimit(1 << 20)
        n = len(nums)
        if n < 3:
            return 0

        r = [x % d for x in nums]

        prefix = {r[0]: 1}
        suffix = {}
        for i in range(2, n):
            residue = r[i]
            suffix[residue] = suffix.get(residue, 0) + 1

        def dfs(j: int, acc: int) -> int:
            if j >= n - 1:
                return acc

            rj = r[j]
            if len(prefix) <= len(suffix):
                for ri, ci in prefix.items():
                    need = (-(ri + rj)) % d
                    ck = suffix.get(need, 0)
                    if ck:
                        acc += ci * ck
            else:
                for rk, ck in suffix.items():
                    need = (-(rk + rj)) % d
                    ci = prefix.get(need, 0)
                    if ci:
                        acc += ci * ck

            prefix[rj] = prefix.get(rj, 0) + 1

            if j + 1 < n:
                nxt = r[j + 1]
                cnt = suffix.get(nxt, 0)
                if cnt <= 1:
                    suffix.pop(nxt, None)
                else:
                    suffix[nxt] = cnt - 1

            return dfs(j + 1, acc)

        return dfs(1, 0)

