# Mutation 1
from typing import List
from collections import Counter

class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        c1 = Counter(basket1)
        c2 = Counter(basket2)

        keys = set(c1) | set(c2)
        for val in keys:
            if (c1[val] + c2[val]) & 1:
                return -1

        base_min = min(basket1 + basket2)

        to_move = []
        for val in keys:
            diff = abs(c1[val] - c2[val]) // 2
            if diff:
                to_move += [val] * diff

        to_move.sort()
        half = len(to_move) // 2
        return sum(min(to_move[i], 2 * base_min) for i in range(half))

