        cnt2 = Counter(basket2)

        all_keys = set(cnt1.keys()) | set(cnt2.keys())
        for v in all_keys:
            if (cnt1[v] + cnt2[v]) % 2 == 0:
                return -1

        m = min(min(basket1), min(basket2))

        moves = []
        for v in all_keys:
            d = cnt1[v] - cnt2[v]
            times = abs(d) // 2
            if times:
                moves.extend([v] * times)

        moves.sort()
        k = len(moves) // 2
        cost = 0
        for i in range(k):
            cost += min(moves[i], 2 * m)
