class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        cnt1 = Counter(basket1)
        cnt2 = Counter(basket2)

        keys = set(cnt1.keys()) | set(cnt2.keys())
        for v in keys:
            if (cnt1[v] + cnt2[v]) % 2 != 0:
                return -1

        m = min(min(basket1), min(basket2))

        moves = []
        for v in keys:
            d = abs(cnt1[v] - cnt2[v]) // 2
            if d:
                moves.extend([v] * d)

        heapq.heapify(moves)
        k = len(moves) // 2
        total = 0
        for _ in range(k):
            x = heapq.heappop(moves)
            total += min(x, 2 * m)
        return total

