from typing import List
from collections import Counter

class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        cnt1 = Counter(basket1)
        cnt2 = Counter(basket2)

        # Check feasibility: total count for each value must be even
        all_keys = set(cnt1.keys()) | set(cnt2.keys())
        for v in all_keys:
            if (cnt1[v] + cnt2[v]) % 2 != 0:
                return -1

        # Global minimum value across both baskets
        m = min(min(basket1), min(basket2))

        # Build the list of values that need to be moved (absolute half-differences)
        moves = []
        for v in all_keys:
            d = cnt1[v] - cnt2[v]
            times = abs(d) // 2
            if times:
                moves.extend([v] * times)

        # Sort and compute minimal cost
        moves.sort()
        k = len(moves) // 2
        cost = 0
        for i in range(k):
            cost += min(moves[i], 2 * m)
        return cost

