from collections import Counter

class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        def feasible(a: Counter, b: Counter) -> bool:
            keys_local = set(a.keys()) | set(b.keys())
            for x in keys_local:
                if (a[x] + b[x]) % 2 != 0:
                    return False
            return True

        def global_minimum(arr1: List[int], arr2: List[int]) -> int:
            mn = float('inf')
            for x in arr1:
                if x < mn:
                    mn = x
            for y in arr2:
                if y < mn:
                    mn = y
            return mn

        def build_moves(a: Counter, b: Counter) -> List[int]:
            moves_local: List[int] = []
            keys_local = set(a.keys()) | set(b.keys())
            for x in keys_local:
                d = abs(a[x] - b[x]) // 2
                if d:
                    moves_local.extend([x] * d)
            return moves_local

        cnt1 = Counter(basket1)
        cnt2 = Counter(basket2)

        if not feasible(cnt1, cnt2):
            return -1

        m = global_minimum(basket1, basket2)
        moves = build_moves(cnt1, cnt2)
        moves.sort()

        total = 0
        i = 0
        k = len(moves) // 2
        while i < k:
            total += min(moves[i], 2 * m)
            i += 1
        return total

