from typing import List

class Solution:
    def maxHeight(self, cuboids: List[List[int]]) -> int:
        normalized = [sorted(box) for box in cuboids]
        normalized.sort()
        n = len(normalized)
        best = [0] * n
        res = 0

        for i, box in enumerate(normalized):
            best[i] = box[2]
            for j in range(i):
                if all(normalized[j][k] <= box[k] for k in range(3)):
                    cand = best[j] + box[2]
                    if cand > best[i]:
                        best[i] = cand
            if best[i] > res:
                res = best[i]
        return res

