class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # Impossible if k has a 1 where n has a 0
        if k & ~n:
            return -1
        # Bits to turn off in n where k has 0
        flips = n ^ (n & k)
        return flips.bit_count()

