class Solution:
    def minChanges(self, n: int, k: int) -> int:
        changes = 0
        while n > 0 or k > 0:
            nb = n & 1
            kb = k & 1
            if kb and not nb:
                return -1
            if nb and not kb:
                changes += 1
            n >>= 1
            k >>= 1
        return changes

