class Solution:
    def minChanges(self, n: int, k: int) -> int:
        ns = bin(n)[2:]
        ks = bin(k)[2:]
        L = max(len(ns), len(ks))
        ns = ns.zfill(L)
        ks = ks.zfill(L)

        # Check impossibility: any position where k has '1' and n has '0'
        for a, b in zip(ns, ks):
            if b == '1' and a == '0':
                return -1

        # Count positions where n has '1' and k has '0'
        return sum(1 for a, b in zip(ns, ks) if a == '1' and b == '0')

