# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        if root is None or p is None or q is None:
            return None

        parents = {root: None}
        stack = [root]
        p_node = None
        q_node = None

        while stack:
            node = stack.pop()
            if node.val == p.val:
                p_node = node
            if node.val == q.val:
                q_node = node
            if node.left:
                parents[node.left] = node
                stack.append(node.left)
            if node.right:
                parents[node.right] = node
                stack.append(node.right)

        if p_node is None or q_node is None:
            return None

        ancestors = set()
        cur = p_node
        while cur is not None:
            ancestors.add(cur)
            cur = parents.get(cur)

        cur = q_node
        while cur is not None:
            if cur in ancestors:
                return cur
            cur = parents.get(cur)

        return None

