from typing import List

class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        left = [[0] * n for _ in range(m)]
        right = [[0] * n for _ in range(m)]

        # Forward pass: compute left-above distinct counts per diagonal key (r-c)
        diag_seen = {}
        for r in range(m):
            for c in range(n):
                key = r - c
                s = diag_seen.setdefault(key, set())
                left[r][c] = len(s)
                s.add(grid[r][c])

        # Backward pass: compute right-below distinct counts
        diag_seen = {}
        for r in range(m - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                key = r - c
                s = diag_seen.setdefault(key, set())
                right[r][c] = len(s)
                s.add(grid[r][c])

        ans = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                ans[r][c] = abs(left[r][c] - right[r][c])
        return ans

