from typing import List
from bisect import bisect_left

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_all(text: str, sub: str) -> List[int]:
            if not sub:
                return []
            res: List[int] = []
            start = 0
            while True:
                idx = text.find(sub, start)
                if idx == -1:
                    break
                res.append(idx)
                start = idx + 1
            return res

        ia = find_all(s, a)
        ib = find_all(s, b)

        res: List[int] = []
        for i in ia:
            pos = bisect_left(ib, i - k)
            if pos < len(ib) and ib[pos] <= i + k:
                res.append(i)
        return res

