class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def build_prefix(pat: str) -> List[int]:
            m = len(pat)
            lps = [0] * m
            length = 0
            for i in range(1, m):
                while length > 0 and pat[i] != pat[length]:
                    length = lps[length - 1]
                if pat[i] == pat[length]:
                    length += 1
                    lps[i] = length
            return lps

        def kmp_find(text: str, pat: str) -> List[int]:
            n, m = len(text), len(pat)
            if m == 0 or m > n:
                return []
            lps = build_prefix(pat)
            i = 0
            j = 0
            hits: List[int] = []
            while i < n:
                if text[i] == pat[j]:
                    i += 1
                    j += 1
                    if j == m:
                        hits.append(i - j)
                        j = lps[j - 1]
                else:
                    if j:
                        j = lps[j - 1]
                    else:
                        i += 1
            return hits

        pos_a = kmp_find(s, a)
        pos_b = kmp_find(s, b)

        ans: List[int] = []
        ptr = 0
        total_b = len(pos_b)
        for idx in pos_a:
            while ptr < total_b and pos_b[ptr] < idx - k:
                ptr += 1
            if not (ptr >= total_b) and pos_b[ptr] <= idx + k:
                ans.append(idx)
        return ans

