from typing import List

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def rabin_karp(text: str, pat: str) -> List[int]:
            n, m = len(text), len(pat)
            if m == 0 or m > n:
                return []
            base = 256
            mod = 10**9 + 7
            power = pow(base, m - 1, mod)

            hp = 0
            hw = 0
            for i in range(m):
                hp = (hp * base + ord(pat[i])) % mod
                hw = (hw * base + ord(text[i])) % mod

            res: List[int] = []
            for i in range(n - m + 1):
                if hp == hw and text[i:i + m] == pat:
                    res.append(i)
                if i < n - m:
                    left = ord(text[i])
                    right = ord(text[i + m])
                    hw = (hw - left * power) % mod
                    hw = (hw * base + right) % mod
            return res

        ia = rabin_karp(s, a)
        ib = rabin_karp(s, b)

        res: List[int] = []
        p = 0
        m = len(ib)
        for i in ia:
            while p < m and ib[p] < i - k:
                p += 1
            if p < m and ib[p] <= i + k:
                res.append(i)
        return res

