final_answer:
class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        bigger = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                k -= 1
                if k == 0:
                    return i
                if i != n // i:
                    bigger.append(n // i)
            i += 1
        if k > len(bigger):
            return -1
        return bigger[-k]

