class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        left = []
        right = []
        for d in range(1, int(n ** 0.5) + 1):
            if n % d == 0:
                left.append(d)
                pair = n // d
                if pair != d:
                    right.append(pair)
        total = len(left) + len(right)
        if total < k:
            return -1
        if k <= len(left):
            return left[k - 1]
        rem = k - len(left)
        return right[len(right) - rem]

