import heapq

class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        factors = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                factors.append(i)
                j = n // i
                if j != i:
                    factors.append(j)
            i += 1
        if len(factors) < k:
            return -1
        heapq.heapify(factors)
        ans = -1
        for _ in range(k):
            ans = heapq.heappop(factors)
        return ans

