class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if not k:
            return 1

        maxbit = max(max(nums).bit_length(), k.bit_length())
        bitfreq = [0] * maxbit
        window_or = 0
        lo = 0
        best = float('inf')

        for hi in range(n):
            x = nums[hi]
            for b in range(maxbit):
                if (x >> b) & 1:
                    bitfreq[b] += 1
                    window_or |= (1 << b)

            while lo <= hi and window_or >= k:
                if hi - lo + 1 < best:
                    best = hi - lo + 1
                y = nums[lo]
                for b in range(maxbit):
                    if (y >> b) & 1:
                        bitfreq[b] -= 1
                        if bitfreq[b] == 0:
                            window_or &= ~(1 << b)
                lo += 1

        return -1 if best == float('inf') else best

