from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return 1

        maxbit = max(max(nums).bit_length(), k.bit_length())
        counts = [0] * maxbit
        curr_or = 0

        def add_num(val: int):
            nonlocal curr_or
            tmp = val
            while tmp:
                lsb = tmp & -tmp
                b = lsb.bit_length() - 1
                counts[b] += 1
                curr_or |= (1 << b)
                tmp -= lsb

        def remove_num(val: int):
            nonlocal curr_or
            tmp = val
            while tmp:
                lsb = tmp & -tmp
                b = lsb.bit_length() - 1
                counts[b] -= 1
                if counts[b] == 0:
                    curr_or &= ~(1 << b)
                tmp -= lsb

        left = 0
        right = 0
        ans = float('inf')

        while right < n:
            add_num(nums[right])
            while left <= right and curr_or >= k:
                if right - left + 1 < ans:
                    ans = right - left + 1
                remove_num(nums[left])
                left += 1
            right += 1

        return -1 if ans == float('inf') else ans

