from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        if k == 0:
            return 1

        ans = float('inf')
        prev = {}  # or_value -> minimal length for subarrays ending at previous index

        for x in nums:
            cur = {}
            # start new subarray with x
            cur[x] = 1

            # extend previous subarrays by x
            for or_val, length in prev.items():
                new_or = or_val | x
                prev_len = cur.get(new_or, float('inf'))
                if length + 1 < prev_len:
                    cur[new_or] = length + 1

            # update answer from current endings
            for or_val, length in cur.items():
                if or_val >= k and length < ans:
                    ans = length

            prev = cur

        return -1 if ans == float('inf') else ans

