from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return 1  # Any non-empty subarray has OR >= 0

        maxbit = max(max(nums).bit_length(), k.bit_length())
        counts = [0] * maxbit
        curr_or = 0
        left = 0
        ans = float('inf')

        for right in range(n):
            # Add nums[right] to the window
            temp = nums[right]
            while temp:
                lsb = temp & -temp
                b = lsb.bit_length() - 1
                counts[b] += 1
                curr_or |= (1 << b)
                temp -= lsb

            # Try to shrink from the left while window is special
            while left <= right and curr_or >= k:
                ans = min(ans, right - left + 1)
                # Remove nums[left] from the window
                temp = nums[left]
                while temp:
                    lsb = temp & -temp
                    b = lsb.bit_length() - 1
                    counts[b] -= 1
                    if counts[b] == 0:
                        curr_or &= ~(1 << b)
                    temp -= lsb
                left += 1

        return -1 if ans == float('inf') else ans

