from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return 1

        maxbit = max(max(nums).bit_length(), k.bit_length())

        def exists(length: int) -> bool:
            if length <= 0 or length > n:
                return False
            counts = [0] * maxbit

            # initialize first window
            for i in range(length):
                x = nums[i]
                for b in range(maxbit):
                    if (x >> b) & 1:
                        counts[b] += 1

            curr_or = 0
            for b in range(maxbit):
                if counts[b] > 0:
                    curr_or |= (1 << b)
            if curr_or >= k:
                return True

            # slide
            for i in range(length, n):
                out = nums[i - length]
                inn = nums[i]
                for b in range(maxbit):
                    if (out >> b) & 1:
                        counts[b] -= 1
                    if (inn >> b) & 1:
                        counts[b] += 1
                curr_or = 0
                for b in range(maxbit):
                    if counts[b] > 0:
                        curr_or |= (1 << b)
                if curr_or >= k:
                    return True
            return False

        if not exists(n):
            return -1

        lo, hi = 1, n
        best = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if exists(mid):
                best = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return best

