class Solution:
    def countTriples(self, n: int) -> int:
        count = 0
        for c in range(1, n + 1):
            c2 = c * c
            a, b = 1, c - 1
            while a < b:
                s = a * a + b * b
                if s == c2:
                    count += 2
                    a += 1
                    b -= 1
                elif s < c2:
                    a += 1
                else:
                    b -= 1
        return count

