# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        self.total = 0

        def walk(cur):
            if not cur:
                return []
            if not cur.left and not cur.right:
                return [1]

            left_list = walk(cur.left)
            right_list = walk(cur.right)

            for dl in left_list:
                for dr in right_list:
                    if dl + dr <= distance:
                        self.total += 1

            inc_left = [d + 1 for d in left_list]
            inc_right = [d + 1 for d in right_list]
            merged = [x for x in inc_left + inc_right if x <= distance]
            return merged

        walk(root)
        return self.total

