# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        if not root:
            return 0

        ans = 0
        stack = [(root, False)]
        dist_map = {}

        while stack:
            node, seen = stack.pop()
            if node is None:
                continue
            if not seen:
                stack.append((node, True))
                stack.append((node.right, False))
                stack.append((node.left, False))
            else:
                if node.left is None and node.right is None:
                    dist_map[node] = [1]
                else:
                    left_dist = dist_map.get(node.left, [])
                    right_dist = dist_map.get(node.right, [])

                    for ld in left_dist:
                        for rd in right_dist:
                            if ld + rd <= distance:
                                ans += 1

                    to_parent = []
                    i = 0
                    while i < len(left_dist):
                        val = left_dist[i] + 1
                        if val <= distance:
                            to_parent.append(val)
                        i += 1
                    j = 0
                    while j < len(right_dist):
                        val = right_dist[j] + 1
                        if val <= distance:
                            to_parent.append(val)
                        j += 1
                    dist_map[node] = to_parent

        return ans

