from collections import deque

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        if not root:
            return 0

        parent = {}
        leaves = []

        stack = [root]
        parent[root] = None
        while stack:
            node = stack.pop()
            if node.left is None and node.right is None:
                leaves.append(node)
            if node.left:
                parent[node.left] = node
                stack.append(node.left)
            if node.right:
                parent[node.right] = node
                stack.append(node.right)

        total = 0
        for start in leaves:
            q = deque()
            q.append((start, 0))
            visited = {start}
            while q:
                node, dist = q.popleft()
                if dist > distance:
                    continue
                if dist > 0 and node.left is None and node.right is None:
                    total += 1
                for nxt in (node.left, node.right, parent.get(node)):
                    if nxt is not None and nxt not in visited:
                        visited.add(nxt)
                        q.append((nxt, dist + 1))
        return total // 2

