# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        self.ans = 0

        def dfs(node):
            if not node:
                return []
            if not node.left and not node.right:
                # Leaf node: distance 1 to its parent
                return [1]

            left_distances = dfs(node.left)
            right_distances = dfs(node.right)

            # Count good pairs where leaves are in left and right subtrees
            for ld in left_distances:
                for rd in right_distances:
                    if ld + rd <= distance:
                        self.ans += 1

            # Return distances from this node to leaves in its subtrees, incremented by 1
            res = []
            for d in left_distances:
                if d + 1 <= distance:
                    res.append(d + 1)
            for d in right_distances:
                if d + 1 <= distance:
                    res.append(d + 1)
            return res

        dfs(root)
        return self.ans

