class Solution:
    def minDayskVariants(self, points: List[List[int]], k: int) -> int:
        n = len(points)
        U = [a + b for a, b in points]
        V = [a - b for a, b in points]

        def build_candidates(d: int):
            Uc, Vc = set(), set()
            i = 0
            while i < n:
                ui, vi = U[i], V[i]
                Uc.add(ui - d); Uc.add(ui + d); Uc.add(ui - d + 1); Uc.add(ui + d - 1)
                Vc.add(vi - d); Vc.add(vi + d); Vc.add(vi - d + 1); Vc.add(vi + d - 1)
                i += 1
            return Uc, Vc

        def count_k_at(u0: int, v0: int, active: List[int], d: int) -> bool:
            # Parity must match
            if ((u0 + v0) & 1) != 0:
                return False
            cnt = 0
            j = 0
            while j < len(active):
                i = active[j]
                if abs(V[i] - v0) <= d:
                    cnt += 1
                    if cnt >= k:
                        return True
                j += 1
            return False

        def possible(d: int) -> bool:
            Uc, Vc = build_candidates(d)
            for u0 in Uc:
                # Build active indices with while loop
                active = []
                idx = 0
                while idx < n:
                    if abs(U[idx] - u0) <= d:
                        active.append(idx)
                    idx += 1
                if len(active) < k:
                    continue
                for v0 in Vc:
                    if count_k_at(u0, v0, active, d):
                        return True
            return False

        lo, hi = 0, 1
        while not possible(hi):
            hi <<= 1

        while lo < hi:
            mid = (lo + hi) // 2
            if possible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

