                    for idx in active:
                        if abs(V[idx] - v0) <= d:
                            cnt += 1
                            if cnt >= k:
                                return True
            return False

        lo, hi = 0, 1
        while not possible(hi):
            hi *= 2

        while lo < hi:
            mid = (lo + hi) // 2
            if possible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

