from typing import List
from collections import deque

class Solution:
    def minimumDiameterAfterMerge(self, edges1: List[List[int]], edges2: List[List[int]]) -> int:
        n = len(edges1) + 1
        m = len(edges2) + 1

        g1 = [[] for _ in range(n)]
        for a, b in edges1:
            g1[a].append(b)
            g1[b].append(a)

        g2 = [[] for _ in range(m)]
        for u, v in edges2:
            g2[u].append(v)
            g2[v].append(u)

        def bfs(adj, s):
            d = [-1] * len(adj)
            q = deque([s])
            d[s] = 0
            far = s
            while q:
                u = q.popleft()
                for w in adj[u]:
                    if d[w] == -1:
                        d[w] = d[u] + 1
                        q.append(w)
                        if d[w] >= d[far]:
                            far = w
            return far, d

        def diam(adj):
            a, _ = bfs(adj, 0)
            _, dist = bfs(adj, a)
            return max(dist)

        d1 = diam(g1)
        d2 = diam(g2)
        r1 = (d1 + 1) // 2
        r2 = (d2 + 1) // 2
        return max(d1, d2, r1 + r2 + 1)

from typing import List
from collections import deque

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        weekly = deque()   # (expiry_day, total_cost)
        monthly = deque()  # (expiry_day, total_cost)
        total = 0

        for day in days:
            while weekly and weekly[0][0] < day:
                weekly.popleft()
            while monthly and monthly[0][0] < day:
                monthly.popleft()

            weekly.append((day + 7 - 1, total + costs[1]))
            monthly.append((day + 30 - 1, total + costs[2]))

            candidates = [total + costs[0]]
            if weekly:
                candidates.append(weekly[0][1])
            if monthly:
                candidates.append(monthly[0][1])
            total = min(candidates)

        return total

