        # Track cumulative length at each nesting level
        prefix_len = {0: 0}
        for segment in input.split('\n'):
            label = segment.lstrip('\t')
            level = len(segment) - len(label)
            if '.' in label:
                # File: compute full path length without adding extra '/'
                cand = prefix_len[level] + len(label)
                if cand > best:
                    best = cand
            else:
                # Directory: store cumulative length for child level (+1 for '/')
                prefix_len[level + 1] = prefix_len[level] + len(label) + 1
        return best

