class Solution:
    def lengthLongestPath(self, input: str) -> int:
        maxlen = 0
        stack = [0]  # stack[i] is total length up to depth i (including trailing '/')
        for line in input.split('\n'):
            level = 0
            while level < len(line) and line[level] == '\t':
                level += 1
            # adjust stack to current level
            while len(stack) > level + 1:
                stack.pop()
            name_len = len(line) - level
            curr_len = stack[-1] + name_len + 1  # +1 for '/'
            if '.' in line:
                # subtract the extra '/' added above for files
                if curr_len - 1 > maxlen:
                    maxlen = curr_len - 1
            else:
                stack.append(curr_len)
        return maxlen

