class Solution:
    def lengthLongestPath(self, input: str) -> int:
        parts = input.split('\n')
        n = len(parts)
        # Use a list to store cumulative lengths by depth
        cum = [0] * (n + 1)
        res = 0
        for line in parts:
            # compute depth
            idx = 0
            while idx < len(line) and line[idx] == '\t':
                idx += 1
            depth = idx
            name_len = len(line) - depth
            if '.' in line[idx:]:
                # file: no trailing '/'
                path_len = cum[depth] + name_len
                if path_len > res:
                    res = path_len
            else:
                # directory: include '/'
                cum[depth + 1] = cum[depth] + name_len + 1
        return res

