from typing import List
from collections import deque

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        RED, BLUE = 0, 1

        adj = [[[] for _ in range(n)] for _ in range(2)]  # adj[color][u] -> list of v
        for u, v in redEdges:
            adj[RED][u].append(v)
        for u, v in blueEdges:
            adj[BLUE][u].append(v)

        dist = [[-1] * n for _ in range(2)]
        dist[RED][0] = 0
        dist[BLUE][0] = 0

        q = deque()
        q.append((0, RED))
        q.append((0, BLUE))

        while q:
            u, last_color = q.popleft()
            next_color = BLUE if last_color == RED else RED
            for v in adj[next_color][u]:
                if dist[next_color][v] == -1:
                    dist[next_color][v] = dist[last_color][u] + 1
                    q.append((v, next_color))

        ans = [-1] * n
        for i in range(n):
            a = dist[RED][i]
            b = dist[BLUE][i]
            if a == -1 and b == -1:
                ans[i] = -1
            elif a == -1:
                ans[i] = b
            elif b == -1:
                ans[i] = a
            else:
                ans[i] = a if a < b else b

        return ans

