    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        R, B = 0, 1

        red_adj = [[] for _ in range(n)]
        blue_adj = [[] for _ in range(n)]
        for a, b in redEdges:
            red_adj[a].append(b)
        for u, v in blueEdges:
            blue_adj[u].append(v)

        res = [-1] * n
        seen = [[False, False] for _ in range(n)]

        q = deque()
        q.append((0, R, 0))
        q.append((0, B, 0))
        seen[0][R] = True
        seen[0][B] = True

        while q:
            cur, last_col, dist = q.popleft()
            if res[cur] == -1 or dist < res[cur]:
                res[cur] = dist

            nxt_col = B if last_col == R else R
            neighbors = blue_adj[cur] if last_col == R else red_adj[cur]
            for nxt in neighbors:
                if not seen[nxt][nxt_col]:
                    seen[nxt][nxt_col] = True
                    q.append((nxt, nxt_col, dist + 1))

        return res

