        dq.append((0, BLUE, 0))
        seen[0][RED] = True
        seen[0][BLUE] = True

        while dq:
            node, last_color, dist = dq.popleft()

            if not (result[node] != -1 and dist >= result[node]):
                result[node] = dist

            if last_color != RED:
                for nxt in red_adj[node]:
                    if seen[nxt][RED]:
