                    seen[nxt][RED] = True
                    dq.append((nxt, RED, dist + 1))
            else:
                for nxt in blue_adj[node]:
                    if seen[nxt][BLUE]:
                        continue
                    seen[nxt][BLUE] = True
                    dq.append((nxt, BLUE, dist + 1))

        return result

