from typing import List
from collections import deque

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        RED, BLUE = 0, 1

        red_adj = [[] for _ in range(n)]
        blue_adj = [[] for _ in range(n)]
        for u, v in redEdges:
            red_adj[u].append(v)
        for u, v in blueEdges:
            blue_adj[u].append(v)

        ans = [-1] * n
        visited = [[False, False] for _ in range(n)]
        q = deque()

        q.append((0, RED, 0))
        q.append((0, BLUE, 0))
        visited[0][RED] = True
        visited[0][BLUE] = True

        def push_neighbors(u: int, last_color: int, d: int) -> None:
            if last_color == RED:
                i = 0
                while i < len(blue_adj[u]):
                    v = blue_adj[u][i]
                    if not visited[v][BLUE]:
                        visited[v][BLUE] = True
                        q.append((v, BLUE, d + 1))
                    i += 1
            else:
                j = 0
                while j < len(red_adj[u]):
                    v = red_adj[u][j]
                    if not visited[v][RED]:
                        visited[v][RED] = True
                        q.append((v, RED, d + 1))
                    j += 1

        while q:
            node, last_color, dist = q.popleft()
            if ans[node] == -1 or dist < ans[node]:
                ans[node] = dist
            push_neighbors(node, last_color, dist)

        return ans

