import math

class Solution:
    def idealArrays(self, n: int, maxValue: int) -> int:
        MOD = 10**9 + 7

        # Smallest prime factor sieve
        def spf_sieve(limit: int):
            spf = list(range(limit + 1))
            for i in range(2, int(limit ** 0.5) + 1):
                if spf[i] == i:
                    step = i
                    start = i * i
                    for j in range(start, limit + 1, step):
                        if spf[j] == j:
                            spf[j] = i
            return spf

        spf = spf_sieve(maxValue)

        def factorize_with_spf(x: int):
            exps = []
            while x > 1:
                p = spf[x]
                cnt = 0
                while x % p == 0:
                    x //= p
                    cnt += 1
                exps.append(cnt)
            return exps

        # Compute emax
        emax = 0
        t = 1
        while t * 2 <= maxValue:
            t *= 2
            emax += 1

        # Precompute factorials/inverses
        max_comb_n = (n - 1) + emax
        if max_comb_n < 0:
            max_comb_n = 0
        fac = [1] * (max_comb_n + 1)
        for i in range(1, max_comb_n + 1):
            fac[i] = fac[i - 1] * i % MOD
        invfac = [1] * (max_comb_n + 1)
        invfac[max_comb_n] = pow(fac[max_comb_n], MOD - 2, MOD)
        for i in range(max_comb_n - 1, -1, -1):
            invfac[i] = invfac[i + 1] * (i + 1) % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fac[a] * invfac[b] % MOD * invfac[a - b] % MOD

        ans = 0
        for v in range(1, maxValue + 1):
            total = 1
            exps = factorize_with_spf(v)
            for e in exps:
                total = (total * comb((n - 1) + e, e)) % MOD
            ans += total
            if ans >= MOD:
                ans -= MOD
        return ans % MOD

