from typing import List

class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        last = 0
        best_span = -1
        best_emp = 0
        for eid, t in logs:
            span = t - last
            if span > best_span:
                best_span = span
                best_emp = eid
            elif span == best_span and eid < best_emp:
                best_emp = eid
            last = t
        return best_emp

