from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Suffix sum of apples: suf[i][j] = number of apples in submatrix (i..rows-1, j..cols-1)
        suf = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in range(rows - 1, -1, -1):
            for c in range(cols - 1, -1, -1):
                suf[r][c] = (1 if pizza[r][c] == 'A' else 0) + suf[r + 1][c] + suf[r][c + 1] - suf[r + 1][c + 1]

        @lru_cache(maxsize=None)
        def cutways(r: int, c: int, parts: int) -> int:
            if not suf[r][c]:
                return 0
            if parts == 1:
                return 1

            total = 0
            # Horizontal cuts
            for nr in range(r + 1, rows):
                # Top part has apples if suf[r][c] - suf[nr][c] > 0; equivalently not equal
                if suf[r][c] != suf[nr][c]:
                    total += cutways(nr, c, parts - 1)
                    if total >= MOD:
                        total -= MOD
            # Vertical cuts
            for nc in range(c + 1, cols):
                if suf[r][c] != suf[r][nc]:
                    total += cutways(r, nc, parts - 1)
                    if total >= MOD:
                        total -= MOD
            return total % MOD

        return cutways(0, 0, k) % MOD

