from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        R, C = len(pizza), len(pizza[0])

        # Build suffix sums using while loops
        suf = [[0] * (C + 1) for _ in range(R + 1)]
        i = R - 1
        while i >= 0:
            j = C - 1
            while j >= 0:
                add = 1 if pizza[i][j] == 'A' else 0
                suf[i][j] = add + suf[i + 1][j] + suf[i][j + 1] - suf[i + 1][j + 1]
                j -= 1
            i -= 1

        def has_top_apples(i0: int, j0: int, r: int) -> bool:
            return (suf[i0][j0] - suf[r][j0]) > 0

        def has_left_apples(i0: int, j0: int, c: int) -> bool:
            return (suf[i0][j0] - suf[i0][c]) > 0

        @lru_cache(maxsize=None)
        def dfs(i0: int, j0: int, parts: int) -> int:
            if suf[i0][j0] == 0:
                return 0
            if parts == 1:
                return 1

            res = 0
            # Horizontal cuts using while loop
            r = i0 + 1
            while r < R:
                if has_top_apples(i0, j0, r):
                    res += dfs(r, j0, parts - 1)
                    if res >= MOD:
                        res -= MOD
                r += 1

            # Vertical cuts using while loop
            c = j0 + 1
            while c < C:
                if has_left_apples(i0, j0, c):
                    res += dfs(i0, c, parts - 1)
                    if res >= MOD:
                        res -= MOD
                c += 1

            return res % MOD

        return dfs(0, 0, k) % MOD

