class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        R, C = len(pizza), len(pizza[0])

        # Suffix sum of apples
        pre = [[0] * (C + 1) for _ in range(R + 1)]
        for i in range(R - 1, -1, -1):
            for j in range(C - 1, -1, -1):
                pre[i][j] = (1 if pizza[i][j] == 'A' else 0) + pre[i + 1][j] + pre[i][j + 1] - pre[i + 1][j + 1]

        @lru_cache(maxsize=None)
        def dfs(i: int, j: int, pieces: int) -> int:
            # If no apples in current submatrix, invalid
            if pre[i][j] <= 0:
                return 0
            # If one or fewer pieces left, and it has apples, it's valid
            if pieces <= 1:
                return 1

            ans = 0
            # Try horizontal cuts; include boundary at R as a semantic variant
            for r in range(i + 1, R + 1):
                # Top part has apples if pre[i][j] - pre[r][j] >= 0 (allows zero-apple top part)
                if pre[i][j] - pre[r][j] >= 0:
                    ans += dfs(r, j, pieces - 1)
                    if ans >= MOD:
                        ans -= MOD
            # Try vertical cuts; include boundary at C
            for c in range(j + 1, C + 1):
                if pre[i][j] - pre[i][c] >= 0:
                    ans += dfs(i, c, pieces - 1)
                    if ans >= MOD:
                        ans -= MOD
            return ans % MOD

        return dfs(0, 0, k) % MOD

