from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        R, C = len(pizza), len(pizza[0])

        # Prefix sum of apples: ps[i+1][j+1] = apples in rectangle (0..i, 0..j)
        ps = [[0] * (C + 1) for _ in range(R + 1)]
        for i in range(R):
            row_sum = 0
            for j in range(C):
                row_sum += 1 if pizza[i][j] == 'A' else 0
                ps[i + 1][j + 1] = ps[i][j + 1] + row_sum

        def apples(r1: int, c1: int, r2: int, c2: int) -> int:
            # Count apples in [r1, r2) x [c1, c2)
            return ps[r2][c2] - ps[r1][c2] - ps[r2][c1] + ps[r1][c1]

        @lru_cache(maxsize=None)
        def dfs(i: int, j: int, pieces: int) -> int:
            if apples(i, j, R, C) == 0:
                return 0
            if pieces == 1:
                return 1

            res = 0
            # Horizontal cuts: cut at r, giving top [i, r)
            for r in range(i + 1, R):
                if apples(i, j, r, C) > 0:
                    res += dfs(r, j, pieces - 1)
                    if res >= MOD:
                        res -= MOD
            # Vertical cuts: cut at c, giving left [j, c)
            for c in range(j + 1, C):
                if apples(i, j, R, c) > 0:
                    res += dfs(i, c, pieces - 1)
                    if res >= MOD:
                        res -= MOD
            return res % MOD

        return dfs(0, 0, k) % MOD

