from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        R, C = len(pizza), len(pizza[0])

        # Suffix sum of apples
        pre = [[0] * (C + 1) for _ in range(R + 1)]
        for i in range(R - 1, -1, -1):
            for j in range(C - 1, -1, -1):
                pre[i][j] = (1 if pizza[i][j] == 'A' else 0) + pre[i + 1][j] + pre[i][j + 1] - pre[i + 1][j + 1]

        # dp[p][i][j]: number of ways to cut submatrix (i..R-1, j..C-1) into p pieces, each with at least one apple
        dp = [[[0] * C for _ in range(R)] for _ in range(k + 1)]

        # Base case: 1 piece valid iff there is at least one apple
        for i in range(R):
            for j in range(C):
                dp[1][i][j] = 1 if pre[i][j] > 0 else 0

        for p in range(2, k + 1):
            for i in range(R):
                for j in range(C):
                    if pre[i][j] == 0:
                        dp[p][i][j] = 0
                        continue
                    total = 0
                    # Horizontal cuts
                    for r in range(i + 1, R):
                        if pre[i][j] - pre[r][j] > 0:
                            total += dp[p - 1][r][j]
                            if total >= MOD:
                                total -= MOD
                    # Vertical cuts
                    for c in range(j + 1, C):
                        if pre[i][j] - pre[i][c] > 0:
                            total += dp[p - 1][i][c]
                            if total >= MOD:
                                total -= MOD
                    dp[p][i][j] = total % MOD

        return dp[k][0][0] % MOD

