class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        neighbors = defaultdict(set)
        for a, b in pairs:
            neighbors[a].add(b)
            neighbors[b].add(a)
        verts = list(neighbors.keys())
        total = len(verts)
        root = next((node for node in verts if len(neighbors[node]) == total - 1), -1)
        if root == -1:
            return 0

        has_multiple = False

        for node in verts:
            if node == root:
                continue
            chosen_parent = None
            best_deg = float('inf')
            deg_node = len(neighbors[node])

            for nb in neighbors[node]:
                nb_deg = len(neighbors[nb])
                if nb_deg >= deg_node and nb_deg < best_deg:
                    chosen_parent = nb
                    best_deg = nb_deg
            if chosen_parent is None:
                return 0

            if not all(x == chosen_parent or x in neighbors[chosen_parent] for x in neighbors[node]):
                return 0

            if best_deg == deg_node:
                has_multiple = True

        return 2 if has_multiple else 1

