from typing import List
from collections import defaultdict
import heapq

class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        adj = defaultdict(set)
        for a, b in pairs:
            adj[a].add(b)
            adj[b].add(a)

        nodes = list(adj.keys())
        n = len(nodes)

        root = -1
        for u in nodes:
            if len(adj[u]) == n - 1:
                root = u
                break
        if root == -1:
            return 0

        multiple = False

        degrees = {u: len(adj[u]) for u in nodes}

        for u in nodes:
            if u == root:
                continue
            deg_u = degrees[u]
            heap = []
            for v in adj[u]:
                deg_v = degrees[v]
                if deg_v >= deg_u:
                    heapq.heappush(heap, (deg_v, v))
            if not heap:
                return 0
            parent_deg, parent = heapq.heappop(heap)

            for v in adj[u]:
                if v == parent:
                    continue
                if v not in adj[parent]:
                    return 0

            if parent_deg == deg_u:
                multiple = True

        return 2 if multiple else 1

