from typing import List
import heapq

class Solution:
    def minAvailableDuration(self, slots1: List[List[int]], slots2: List[List[int]], duration: int) -> List[int]:
        # Filter out slots that are individually too short
        a = [s for s in slots1 if s[1] - s[0] >= duration]
        b = [t for t in slots2 if t[1] - t[0] >= duration]

        # Build a min-heap by start times across both people's slots
        h: List[List[int]] = []
        for s in a:
            heapq.heappush(h, (s[0], s[1]))
        for t in b:
            heapq.heappush(h, (t[0], t[1]))

        while len(h) > 1:
            s1, e1 = heapq.heappop(h)
            s2, e2 = h[0]  # earliest next start
            if e1 >= s2 + duration:
                return [s2, s2 + duration]
            # otherwise, discard current and continue

        return []

