class Solution:
    def minAvailableDuration(self, slots1: List[List[int]], slots2: List[List[int]], duration: int) -> List[int]:
        # Sort by start times without pre-filtering (equivalent outcome)
        slots1.sort(key=lambda x: x[0])
        slots2.sort(key=lambda x: x[0])

        i = 0
        j = 0
        while True:
            if i >= len(slots1) or j >= len(slots2):
                break

            left = max(slots1[i][0], slots2[j][0])
            right = min(slots1[i][1], slots2[j][1])

            if not (right - left < duration):
                return [left, left + duration]

            # Move the pointer that has the earlier end time (tie goes to slots2)
            if slots2[j][1] <= slots1[i][1]:
                j += 1
            else:
                i += 1

        return []

