from typing import List

class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        def soldier_count(arr: List[int]) -> int:
            lo, hi = 0, len(arr)
            while lo < hi:
                mid = (lo + hi) // 2
                if arr[mid]:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        pairs = [(soldier_count(r), idx) for idx, r in enumerate(mat)]
        ordered = sorted(pairs)
        return [j for _, j in ordered[:k]]

