from typing import List

class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        def count_rec(row: List[int], lo: int, hi: int) -> int:
            if lo >= hi:
                return lo
            mid = (lo + hi) // 2
            if row[mid] == 1:
                return count_rec(row, mid + 1, hi)
            else:
                return count_rec(row, lo, mid)

        res: List[tuple] = []
        i = 0
        m = len(mat)
        while i < m:
            res.append((count_rec(mat[i], 0, len(mat[i])), i))
            i += 1

        res.sort()
        out: List[int] = []
        t = 0
        while t < k:
            out.append(res[t][1])
            t += 1
        return out

