class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        def count_s(row: List[int]) -> int:
            left, right = 0, len(row)
            while left < right:
                mid = (left + right) // 2
                if not row[mid]:
                    right = mid
                else:
                    left = mid + 1
            return left

        pairs: List[tuple] = []
        for idx, r in enumerate(mat):
            pairs.append((count_s(r), idx))

        pairs.sort(reverse=True)
        tail = pairs[-k:][::-1]
        return [idx for _, idx in tail]

