from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        N = len(nums)
        P = len(pattern)

        # Build prefix function (LPS)
        pi = [0] * P
        ln = 0
        pos = 1
        while pos < P:
            if pattern[pos] == pattern[ln]:
                ln += 1
                pi[pos] = ln
                pos += 1
            else:
                if ln:
                    ln = pi[ln - 1]
                else:
                    pi[pos] = 0
                    pos += 1

        # KMP over on-the-fly sign stream
        ans = 0
        j = 0
        for t in range(N - 1):
            sgn = (nums[t + 1] > nums[t]) - (nums[t + 1] < nums[t])

            while j > 0 and sgn != pattern[j]:
                j = pi[j - 1]

            if sgn == pattern[j]:
                j += 1
                if j == P:
                    ans += 1
                    j = pi[j - 1]

        return ans

