class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        def z_algorithm(arr: List[int]) -> List[int]:
            n = len(arr)
            Z = [0] * n
            l = r = 0
            for i in range(1, n):
                if i <= r:
                    Z[i] = min(r - i + 1, Z[i - l])
                while i + Z[i] < n and arr[Z[i]] == arr[i + Z[i]]:
                    Z[i] += 1
                if i + Z[i] - 1 > r:
                    l = i
                    r = i + Z[i] - 1
            return Z

