from typing import *
from functools import lru_cache

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        n, m = len(s), len(p)

        @lru_cache(maxsize=None)
        def dfs(i: int, j: int) -> bool:
            if j == m:
                return i == n
            if i == n:
                for k in range(j, m):
                    if p[k] != '*':
                        return False
                return True
            if p[j] == '*':
                if dfs(i, j + 1):
                    return True
                if dfs(i + 1, j):
                    return True
                return False
            if p[j] == '?' or p[j] == s[i]:
                return dfs(i + 1, j + 1)
            return False

        return dfs(0, 0)

