class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        sx = sy = -1
        need = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == -1:
                    continue
                need += 1
                if grid[r][c] == 1:
                    sx, sy = r, c

        moves = ((1, 0), (-1, 0), (0, 1), (0, -1))

        def search(i: int, j: int, remaining: int) -> int:
            if grid[i][j] == 2:
                if remaining == 1:
                    return 1
                return 0

            prev = grid[i][j]
            grid[i][j] = -1
            total_paths = 0

            for di, dj in moves:
                ni, nj = i + di, j + dj
                if 0 <= ni and ni < rows and 0 <= nj and nj < cols and grid[ni][nj] != -1:
                    total_paths += search(ni, nj, remaining - 1)

            grid[i][j] = prev
            return total_paths

        return search(sx, sy, need)

