class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])

        def scan():
            r = 0
            needed = 0
            sx = sy = -1
            while r < rows:
                c = 0
                while c < cols:
                    if grid[r][c] != -1:
                        needed += 1
                        if grid[r][c] == 1:
                            sx, sy = r, c
                    c += 1
                r += 1
            return sx, sy, needed

        start_x, start_y, total = scan()
        dx = (1, -1, 0, 0)
        dy = (0, 0, 1, -1)

        def dfs(x: int, y: int, remain: int) -> int:
            if grid[x][y] == 2:
                return 1 if remain == 1 else 0

            original = grid[x][y]
            grid[x][y] = -1
            count = 0

            k = 0
            while k < 4:
                nx = x + dx[k]
                ny = y + dy[k]
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != -1:
                    count += dfs(nx, ny, remain - 1)
                k += 1

            grid[x][y] = original
            return count

        return dfs(start_x, start_y, total)

