from typing import List

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        # Map each non-obstacle cell to an index
        idx_map = {}
        cells = []
        start_idx = end_idx = -1
        for i in range(m):
            for j in range(n):
                if grid[i][j] != -1:
                    idx_map[(i, j)] = len(cells)
                    cells.append((i, j))
                    if grid[i][j] == 1:
                        start_idx = idx_map[(i, j)]
                    elif grid[i][j] == 2:
                        end_idx = idx_map[(i, j)]

        k = len(cells)
        full_mask = (1 << k) - 1

        # Build adjacency among non-obstacle cells
        adj = [[] for _ in range(k)]
        dirs = [(1,0), (-1,0), (0,1), (0,-1)]
        for (i, j), u in idx_map.items():
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if (ni, nj) in idx_map:
                    v = idx_map[(ni, nj)]
                    adj[u].append(v)

        def dfs(pos: int, mask: int) -> int:
            if pos == end_idx:
                return 1 if mask == full_mask else 0
            res = 0
            for v in adj[pos]:
                if (mask >> v) & 1 == 0:
                    res += dfs(v, mask | (1 << v))
            return res

        return dfs(start_idx, 1 << start_idx)

