from functools import lru_cache

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        idx_of = {}
        start = end = -1
        count = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] != -1:
                    idx_of[(i, j)] = count
                    if grid[i][j] == 1:
                        start = count
                    elif grid[i][j] == 2:
                        end = count
                    count += 1

        full_mask = (1 << count) - 1
        dirs = [(1,0), (-1,0), (0,1), (0,-1)]

        # adjacency using indices
        adj = [[] for _ in range(count)]
        for (i, j), u in idx_of.items():
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if (ni, nj) in idx_of:
                    adj[u].append(idx_of[(ni, nj)])

        @lru_cache(maxsize=None)
        def solve(pos: int, mask: int) -> int:
            if pos == end:
                return 1 if mask == full_mask else 0
            total = 0
            for v in adj[pos]:
                if (mask & (1 << v)) == 0:
                    total += solve(v, mask | (1 << v))
            return total

        return solve(start, 1 << start)

