from typing import List

class Solution:
    def calculate(self, s: str) -> int:
        def trunc_div(a: int, b: int) -> int:
            q = abs(a) // abs(b)
            return q if a * b >= 0 else -q

        res = 0
        last_num = 0
        num = 0
        prev_sign = '+'
        n = len(s)

        for i, ch in enumerate(s):
            if ch.isdigit():
                num = num * 10 + (ord(ch) - ord('0'))

            if ch in '+-*/' or i == n - 1:
                if prev_sign == '+':
                    res += last_num
                    last_num = num
                elif prev_sign == '-':
                    res += last_num
                    last_num = -num
                elif prev_sign == '*':
                    last_num = last_num * num
                elif prev_sign == '/':
                    last_num = trunc_div(last_num, num)
                num = 0
                if ch in '+-*/':
                    prev_sign = ch

        return res + last_num

