from typing import List

class Solution:
    def calculate(self, s: str) -> int:
        def trunc_div(a: int, b: int) -> int:
            q = abs(a) // abs(b)
            return q if a * b >= 0 else -q

        def apply_op(nums: List[int], ops: List[str]) -> None:
            op = ops.pop()
            b = nums.pop()
            a = nums.pop()
            if op == '+':
                nums.append(a + b)
            elif op == '-':
                nums.append(a - b)
            elif op == '*':
                nums.append(a * b)
            elif op == '/':
                nums.append(trunc_div(a, b))

        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        nums: List[int] = []
        ops: List[str] = []
        i = 0
        n = len(s)

        while i < n:
            ch = s[i]
            if ch == ' ':
                i += 1
                continue
            if ch.isdigit():
                val = 0
                while i < n and s[i].isdigit():
                    val = val * 10 + (ord(s[i]) - ord('0'))
                    i += 1
                nums.append(val)
                continue
            if ch in '+-*/':
                while ops and precedence[ops[-1]] >= precedence[ch]:
                    apply_op(nums, ops)
                ops.append(ch)
            i += 1

        while ops:
            apply_op(nums, ops)

        return nums[-1] if nums else 0

