from typing import *

class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        def put_or_check(fwd: dict, rev: dict, a: str, b: str) -> bool:
            if a in fwd:
                return fwd[a] == b
            else:
                if b in rev and rev[b] != a:
                    return False
                fwd[a] = b
                rev[b] = a
                return True

        if len(s) != len(t):
            return False

        fwd_map: dict = {}
        rev_map: dict = {}
        i = 0
        n = len(s)
        while i < n:
            if not put_or_check(fwd_map, rev_map, s[i], t[i]):
                return False
            i += 1
        return True

