from typing import List

class Solution:
    def maxIncreaseKeepingSkyline(self, grid: List[List[int]]) -> int:
        size = len(grid)
        # Maximums seen from west/east (rows)
        row_peaks = [max(r) for r in grid]
        # Maximums seen from north/south (columns), computed via loops
        col_peaks = [0] * size
        for col in range(size):
            highest = grid[0][col]
            for row in range(1, size):
                val = grid[row][col]
                if val > highest:
                    highest = val
            col_peaks[col] = highest

        gain = 0
        for r in range(size):
            for c in range(size):
                limit = row_peaks[r] if row_peaks[r] < col_peaks[c] else col_peaks[c]
                diff = limit - grid[r][c]
                if diff > 0:
                    gain += diff
        return gain

