from typing import List

class Solution:
    def platesBetweenCandles(self, s: str, queries: List[List[int]]) -> List[int]:
        n = len(s)
        prefix = [0] * n
        left_candle = [-1] * n
        right_candle = [-1] * n

        star_count = 0
        last_left = -1
        for i, ch in enumerate(s):
            if ch == '*':
                star_count += 1
            else:
                last_left = i
            prefix[i] = star_count
            left_candle[i] = last_left

        last_right = -1
        for i in range(n - 1, -1, -1):
            if s[i] == '|':
                last_right = i
            right_candle[i] = last_right

        out = []
        for l, r in queries:
            L = right_candle[l]
            R = left_candle[r]
            if L != -1 and R != -1 and L < R:
                out.append(prefix[R] - prefix[L])
            else:
                out.append(0)
        return out

