from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        NEG_INF = -10**9
        dp = [NEG_INF] * (target + 1)
        dp[0] = 0

        for x in nums:
            for s in reversed(range(x, target + 1)):
                if dp[s - x] == NEG_INF:
                    continue
                candidate = dp[s - x] + 1
                if candidate > dp[s]:
                    dp[s] = candidate

        if dp[target] == NEG_INF:
            return -1
        return dp[target]

