from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        NEG = float("-inf")
        table = [NEG] * (target + 1)
        table[0] = 0

        for val in nums:
            for sum_so_far in range(target, val - 1, -1):
                prev = table[sum_so_far - val]
                if prev != NEG:
                    cand = prev + 1
                    if cand > table[sum_so_far]:
                        table[sum_so_far] = cand

        ans = table[target]
        return ans if ans != NEG else -1

