from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        NEG_INF = -10**9
        dp = [NEG_INF] * (target + 1)
        dp[0] = 0

        def apply_value(dp_arr: List[int], value: int) -> None:
            s = target
            while s >= value:
                prev = dp_arr[s - value]
                if prev != NEG_INF:
                    if prev + 1 > dp_arr[s]:
                        dp_arr[s] = prev + 1
                s -= 1

        for v in nums:
            apply_value(dp, v)

        return dp[target] if dp[target] != NEG_INF else -1

