from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        best = {0: 0}
        for a in nums:
            nxt = dict(best)
            for s, ln in best.items():
                ns = s + a
                if ns <= target:
                    nl = ln + 1
                    prev = nxt.get(ns)
                    if prev is None or nl > prev:
                        nxt[ns] = nl
            best = nxt

        ans = best.get(target)
        return -1 if ans is None else ans

