from typing import Optional

# Definition for a category handler.
# class CategoryHandler:
#     def haveSameCategory(self, a: int, b: int) -> bool:
#         pass
class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        if n <= 0:
            return 0
        if categoryHandler is None:
            return n

        def matches_any(index: int, reps: list) -> bool:
            j = 0
            while j < len(reps):
                if categoryHandler.haveSameCategory(index, reps[j]):
                    return True
                j += 1
            return False

        reps = []
        i = 0
        while i < n:
            if not matches_any(i, reps):
                reps.append(i)
            i += 1
        return len(reps)

