class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        if n <= 0:
            return 0
        if categoryHandler is None:
            return n

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        for i in range(n):
            for j in range(i):
                if categoryHandler.haveSameCategory(i, j):
                    union(i, j)
                    break

        roots = set(find(i) for i in range(n))
        return len(roots)

