# Definition for a category handler.
# class CategoryHandler:
#     def haveSameCategory(self, a: int, b: int) -> bool:
#         pass
class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        if n <= 0:
            return 0
        if categoryHandler is None:
            return n

        visited = [False] * n
        groups = 0

        for i in range(n):
            if not visited[i]:
                groups += 1
                visited[i] = True
                q = deque([i])
                while q:
                    cur = q.popleft()
                    for j in range(n):
                        if not visited[j] and categoryHandler.haveSameCategory(cur, j):
                            visited[j] = True
                            q.append(j)
        return groups

