class Solution:
    def capitalizeTitle(self, title: str) -> str:
        def transform(word: str) -> str:
            if len(word) <= 2:
                return word.lower()
            return word[0].upper() + word[1:].lower()

        parts = title.split(" ")
        out = []
        idx = 0
        while idx < len(parts):
            out.append(transform(parts[idx]))
            idx += 1
        return " ".join(out)

