import re

class Solution:
    def capitalizeTitle(self, title: str) -> str:
        def repl(match: re.Match) -> str:
            s = match.group(0)
            if len(s) <= 2:
                return s.lower()
            return s[:1].upper() + s[1:].lower()
        return re.sub(r"[A-Za-z]+", repl, title)

