from typing import List

class Solution:
    def filterRestaurants(self, restaurants: List[List[int]], veganFriendly: int, maxPrice: int, maxDistance: int) -> List[int]:
        options = [
            (rating, rid)
            for rid, rating, vegan_flag, price_val, dist_val in restaurants
            if (veganFriendly != 1 or vegan_flag == 1) and price_val <= maxPrice and dist_val <= maxDistance
        ]
        options.sort(key=lambda pair: (-pair[0], -pair[1]))
        return [rid for _, rid in options]

