        # Sort all restaurants first by rating desc, id desc, then filter while scanning
        sorted_rests = sorted(restaurants, key=lambda x: (-x[1], -x[0]))
        result_ids = []
        for rid, rating, vegan, price, dist in sorted_rests:
            if veganFriendly == 1 and vegan != 1:
                continue
            if price <= maxPrice and dist <= maxDistance:
                result_ids.append(rid)
        return result_ids

