from typing import List

class Solution:
    def filterRestaurants(self, restaurants: List[List[int]], veganFriendly: int, maxPrice: int, maxDistance: int) -> List[int]:
        def passes(vegan: int, price: int, dist: int) -> bool:
            if veganFriendly == 1 and vegan != 1:
                return False
            if price <= maxPrice and dist <= maxDistance:
                return True
            return False

        acc = []
        i = 0
        n = len(restaurants)
        while i < n:
            rid, rating, vegan, price, dist = restaurants[i]
            if passes(vegan, price, dist):
                acc.append((rating, rid))
            i += 1
        acc.sort(key=lambda x: (-x[0], -x[1]))
        return [rid for _, rid in acc]

