import heapq

class Solution:
    def filterRestaurants(self, restaurants: List[List[int]], veganFriendly: int, maxPrice: int, maxDistance: int) -> List[int]:
        heap = []
        for rid, rating, vegan, price, dist in restaurants:
            if veganFriendly == 1 and vegan != 1:
                continue
            if price <= maxPrice and dist <= maxDistance:
                heapq.heappush(heap, (-rating, -rid))
        res = []
        while heap:
            neg_rating, neg_rid = heapq.heappop(heap)
            res.append(-neg_rid)
        return res

