from typing import List

class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        base_total = sum(nums)
        gains = [(val ^ k) - val for val in nums]

        positives = [g for g in gains if g > 0]
        best_le_nonpos = None
        for g in gains:
            if g <= 0:
                if best_le_nonpos is None or g > best_le_nonpos:
                    best_le_nonpos = g

        ans = base_total + sum(positives)

        if len(positives) & 1:
            drop_smallest_pos = min(positives)
            add_least_harm = float('inf') if best_le_nonpos is None else -best_le_nonpos
            ans -= min(drop_smallest_pos, add_least_harm)

        return ans

