class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        def adjust(res: int, pos_list: List[int], best_nonpos: int) -> int:
            if len(pos_list) % 2 == 1:
                loss_drop = min(pos_list)
                loss_add = float('inf')
                if best_nonpos is not None:
                    loss_add = -best_nonpos
                return res - min(loss_drop, loss_add)
            return res

        pos_gains = []
        best_nonpos_gain = None

        i = 0
        n = len(nums)
        while i < n:
            g = (nums[i] ^ k) - nums[i]
            if g > 0:
                pos_gains.append(g)
            else:
                if best_nonpos_gain is None or g > best_nonpos_gain:
                    best_nonpos_gain = g
            i += 1

        total = sum(nums) + sum(pos_gains)
        return adjust(total, pos_gains, best_nonpos_gain)

