from typing import List

class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        # DP over parity of number of toggles (even/odd)
        # dp_even: max total gain with even toggles so far
        # dp_odd:  max total gain with odd toggles so far
        dp_even = 0
        dp_odd = float('-inf')
        for x in nums:
            g = (x ^ k) - x
            new_even = max(dp_even, dp_odd + g)
            new_odd = max(dp_odd, dp_even + g)
            dp_even, dp_odd = new_even, new_odd
        return sum(nums) + dp_even

