from typing import List

class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        # In a tree, by choosing edges, we can toggle any even-sized subset of nodes.
        # So we choose to toggle nodes to maximize sum, with the constraint that
        # the number of toggled nodes must be even.

        base_sum = sum(nums)
        pos_gains = []
        best_nonpos_gain = None  # maximum among gains <= 0 (closest to zero)

        for x in nums:
            g = (x ^ k) - x
            if g > 0:
                pos_gains.append(g)
            else:
                if best_nonpos_gain is None or g > best_nonpos_gain:
                    best_nonpos_gain = g

        result = base_sum + sum(pos_gains)

        # If we chose an odd number of positive gains, adjust parity by either:
        # - dropping the smallest positive gain, or
        # - adding the least harmful non-positive gain (closest to zero).
        if len(pos_gains) % 2 == 1:
            loss_drop_pos = min(pos_gains)
            loss_add_nonpos = float('inf')
            if best_nonpos_gain is not None:
                loss_add_nonpos = -best_nonpos_gain  # since best_nonpos_gain <= 0
            result -= min(loss_drop_pos, loss_add_nonpos)

        return result

