from typing import List

class Solution:
    def _bounds(self, arr: List[int]):
        it = iter(arr)
        try:
            first = next(it)
        except StopIteration:
            return None
        lo = first
        hi = first
        for v in it:
            if v < lo:
                lo = v
            if v > hi:
                hi = v
        return lo, hi

    def smallestRangeI(self, nums: List[int], k: int) -> int:
        if not nums:
            return 0
        bounds = self._bounds(nums)
        if bounds is None:
            return 0
        mn, mx = bounds
        diff = (mx - mn) - 2 * k
        return diff if diff > 0 else 0

