from typing import List

class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        up = {child: group[0] for group in regions for child in group[1:]}
        seen = set()
        node = region1
        while True:
            seen.add(node)
            if node not in up:
                break
            node = up[node]
        node = region2
        while node not in seen:
            node = up[node]
        return node

