from typing import List

class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        def build_parent(regs: List[List[str]]) -> dict:
            par = {}
            for lst in regs:
                head = lst[0]
                for ch in lst[1:]:
                    par[ch] = head
            return par

        def collect_ancestors(x: str) -> set:
            # recursive collection of ancestors including itself
            if x not in parent:
                return {x}
            return {x} | collect_ancestors(parent[x])

        parent = build_parent(regions)
        ancestors1 = collect_ancestors(region1)

        curr = region2
        while curr not in ancestors1:
            curr = parent[curr]
        return curr

