from typing import List

class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        # Build adjacency list (parent -> children)
        children = {}
        all_children = set()
        all_parents = set()
        for group in regions:
            head = group[0]
            all_parents.add(head)
            for ch in group[1:]:
                all_children.add(ch)
                children.setdefault(head, []).append(ch)

        # Find root (a parent that never appears as a child)
        roots = [p for p in all_parents if p not in all_children]
        root = roots[0] if roots else regions[0][0]

        # DFS to find path from root to target
