from typing import Optional

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:
        if root1 is None:
            return root2
        stack = [(root1, root2)]
        while stack:
            n1, n2 = stack.pop()
            if n2 is None:
                continue
            n1.val += n2.val

            if n1.left is None:
                n1.left = n2.left
            else:
                stack.append((n1.left, n2.left))

            if n1.right is None:
                n1.right = n2.right
            else:
                stack.append((n1.right, n2.right))
        return root1

