from typing import List

class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        def count_zo(s: str):
            z = s.count('0')
            return z, len(s) - z

        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for s in strs:
            zeros, ones = count_zo(s)
            i = m
            while i >= zeros:
                j = n
                while j >= ones:
                    current = dp[i][j]
                    next_val = dp[i - zeros][j - ones] + 1
                    if next_val > current:
                        dp[i][j] = next_val
                    j -= 1
                i -= 1
        return dp[m][n]

