from typing import List
from functools import lru_cache

class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        counts = []
        for s in strs:
            z = s.count('0')
            counts.append((z, len(s) - z))

        @lru_cache(maxsize=None)
        def dfs(idx: int, rem0: int, rem1: int) -> int:
            if idx == len(counts):
                return 0
            z, o = counts[idx]
            best = dfs(idx + 1, rem0, rem1)
            if z <= rem0 and o <= rem1:
                take = 1 + dfs(idx + 1, rem0 - z, rem1 - o)
                if take > best:
                    best = take
            return best

        return dfs(0, m, n)

