from typing import List

class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        dp = {(0, 0): 0}
        for s in strs:
            z = s.count('0')
            o = len(s) - z
            snapshot = list(dp.items())
            for (cz, co), val in snapshot:
                nz, no = cz + z, co + o
                if nz <= m and no <= n:
                    new_val = val + 1
                    if dp.get((nz, no), 0) < new_val:
                        dp[(nz, no)] = new_val
        return max(dp.values()) if dp else 0

