class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(nums)
        # Build children adjacency list
        heirs = [[] for _ in range(n)]
        for i in range(1, n):
            heirs[parents[i]].append(i)

        # If 1 is not present anywhere, all answers are 1
        if 1 not in nums:
            return [1] * n

        start = nums.index(1)
        res = [1] * n
        limit = max(nums)
        present = [False] * (limit + 2)
        tagged = [False] * n

        def fill_subtree(node: int):
            stack = [node]
            while stack:
                cur = stack.pop()
                if tagged[cur]:
                    continue
                tagged[cur] = True
                val = nums[cur]
                if val <= limit + 1:
                    present[val] = True
                for nxt in heirs[cur]:
                    if not tagged[nxt]:
                        stack.append(nxt)

        mex_val = 1
        cur = start
        while cur != -1:
            fill_subtree(cur)
            while mex_val <= limit + 1 and present[mex_val]:
                mex_val += 1
            res[cur] = mex_val
            cur = parents[cur]

        return res

