from typing import List

class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(nums)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            p = parents[i]
            children[p].append(i)

        # Find index of value 1 using a loop
        pos1 = -1
        for i, v in enumerate(nums):
            if v == 1:
                pos1 = i
                break
        if pos1 == -1:
            return [1] * n

        ans = [1] * n
        max_val = max(nums)
        seen = [False] * (max_val + 2)
        visited_node = [False] * n

        def dfs_iter(u: int):
            stack = [u]
            while stack:
                node = stack.pop()
                if visited_node[node]:
                    continue
                visited_node[node] = True
                val = nums[node]
                if val <= max_val + 1:
                    seen[val] = True
                for w in children[node]:
                    if not visited_node[w]:
                        stack.append(w)

        def advance_mex(m: int) -> int:
            while m <= max_val + 1 and seen[m]:
                m += 1
            return m

        mex = 1
        u = pos1
        while u != -1:
            dfs_iter(u)
            mex = advance_mex(mex)
            ans[u] = mex
            u = parents[u]

        return ans

