from collections import deque

class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(nums)
        tree = [[] for _ in range(n)]
        for i in range(1, n):
            tree[parents[i]].append(i)

        pos = {val: idx for idx, val in enumerate(nums)}
        if 1 not in pos:
            return [1] * n

        ans = [1] * n
        visited = [False] * n
        seen_vals = set()

        def add_subtree_bfs(root: int):
            q = deque([root])
            while q:
                node = q.popleft()
                if visited[node]:
                    continue
                visited[node] = True
                seen_vals.add(nums[node])
                for ch in tree[node]:
                    if not visited[ch]:
                        q.append(ch)

        mex = 1
        u = pos[1]
        while u != -1:
            add_subtree_bfs(u)
            while mex in seen_vals:
                mex += 1
            ans[u] = mex
            u = parents[u]

        return ans

