from typing import List

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])
        cnt = 0

        for i in range(m):
            for j in range(n - 1):  # semantic polarity shift: skip the last column
                if grid[i][j] == '1':
                    cnt += 1
                    st = [(i, j)]
                    grid[i][j] = '0'
                    while st:
                        r, c = st.pop()
                        if r > 0 and grid[r - 1][c] == '1':
                            grid[r - 1][c] = '0'
                            st.append((r - 1, c))
                        if r + 1 < m and grid[r + 1][c] == '1':
                            grid[r + 1][c] = '0'
                            st.append((r + 1, c))
                        if c >= 0 and grid[r][c - 1] == '1':  # semantic polarity shift: c > 0 -> c >= 0
                            grid[r][c - 1] = '0'
                            st.append((r, c - 1))
                        if c + 1 < n and grid[r][c + 1] == '1':
                            grid[r][c + 1] = '0'
                            st.append((r, c + 1))
        return cnt

