from typing import List

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])
        size = m * n

        parent = [-1] * size
        rank = [0] * size

        def idx(i: int, j: int) -> int:
            return i * n + j

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # Initialize parents for land cells
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':
                    parent[idx(i, j)] = idx(i, j)

        # Union adjacent lands (up, left sufficient to cover all pairs)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':
                    if i > 0 and grid[i - 1][j] == '1':
                        union(idx(i, j), idx(i - 1, j))
                    if j > 0 and grid[i][j - 1] == '1':
                        union(idx(i, j), idx(i, j - 1))

        roots = set()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':
                    roots.add(find(idx(i, j)))

        return len(roots)

