from typing import List

class Solution:
    def findPermutation(self, s: str) -> List[int]:
        n = len(s)
        ans: List[int] = []
        stack: List[int] = []
        for i in range(n + 1):
            stack.append(i + 1)
            if i == n or s[i] == 'I':
                while stack:
                    ans.append(stack.pop())
        return ans

