from typing import List

class Solution:
    def findPermutation(self, s: str) -> List[int]:
        total = len(s) + 1
        ans = [x for x in range(1, total + 1)]
        i = 0
        m = len(s)
        while i < m:
            if s[i] == 'D':
                j = i
                while j < m and s[j] == 'D':
                    j += 1
                ans[i:j+1] = ans[i:j+1][::-1]
                i = j
            else:
                i += 1
