from typing import List
from collections import deque

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        rows, cols = len(grid), len(grid[0])
        if rows == 1 and cols == 1:
            return 0
        if k >= rows + cols - 2:
            return rows + cols - 2

        # best[r][c] = maximum remaining eliminations upon reaching (r, c)
        best = [[-1] * cols for _ in range(rows)]
        best[0][0] = k

        q = deque()
        q.append((0, 0, 0, k))  # r, c, dist, remain

        moves = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while q:
            r, c, dist, remain = q.popleft()
            for dr, dc in moves:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    cell = grid[nr][nc]
                    nxt_rem = remain - cell
                    if nxt_rem < 0:
                        continue
                    if nr == rows - 1 and nc == cols - 1:
                        return dist + 1
                    if nxt_rem > best[nr][nc]:
                        best[nr][nc] = nxt_rem
                        q.append((nr, nc, dist + 1, nxt_rem))
        return -1

