from typing import List
from collections import deque

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return 0
        if k >= m + n - 2:
            return m + n - 2

        # Track maximum remaining eliminations for each cell
        seen = [[-1] * n for _ in range(m)]
        seen[0][0] = k

        dq = deque()
        dq.append((0, 0, k))  # r, c, rem

        steps = 0
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

        while dq:
            for _ in range(len(dq)):
                r, c, rem = dq.popleft()
                if r == m - 1 and c == n - 1:
                    return steps
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n:
                        new_rem = rem - grid[nr][nc]
                        if new_rem < 0:
                            continue
                        if seen[nr][nc] < new_rem:
                            seen[nr][nc] = new_rem
                            dq.append((nr, nc, new_rem))
            steps += 1

        return -1

