from typing import List
import heapq

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return 0
        if k >= m + n - 2:
            return m + n - 2

        def heuristic(r: int, c: int) -> int:
            return (m - 1 - r) + (n - 1 - c)

        # best[r][c] = maximum remaining eliminations upon reaching (r, c)
        best = [[-1] * n for _ in range(m)]
        best[0][0] = k

        # A* priority queue: (f = steps + heuristic, steps, r, c, rem)
        pq = []
        heapq.heappush(pq, (heuristic(0, 0), 0, 0, 0, k))

        while pq:
            f, steps, r, c, rem = heapq.heappop(pq)
            if r == m - 1 and c == n - 1:
                return steps
            # Explore neighbors
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    new_rem = rem - grid[nr][nc]
                    if new_rem < 0:
                        continue
                    if new_rem > best[nr][nc]:
                        best[nr][nc] = new_rem
                        g = steps + 1
                        h = heuristic(nr, nc)
                        heapq.heappush(pq, (g + h, g, nr, nc, new_rem))
        return -1

