from collections import deque

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return 0
        if k >= m + n - 2:
            return m + n - 2

        q = deque()
        q.append((0, 0, 0, k))  # r, c, steps, remaining

        # Use a visited set of full states (r, c, rem) instead of 2D best-remaining
        visited = {(0, 0, k)}

        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while q:
            r, c, steps, rem = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    new_rem = rem - grid[nr][nc]
                    if new_rem < 0:
                        continue
                    if nr == m - 1 and nc == n - 1:
                        return steps + 1
                    state = (nr, nc, new_rem)
                    if state not in visited:
                        visited.add(state)
                        q.append((nr, nc, steps + 1, new_rem))

        return -1

