from typing import List
from collections import deque  # imported though not used for the stack variant

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        moves_dirs = [(-1,0), (1,0), (0,-1), (0,1)]

        pos_to_idx = {}
        idx_to_pos = []
        m0 = c0 = f0 = -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != '#':
                    k = len(idx_to_pos)
                    pos_to_idx[(r, c)] = k
                    idx_to_pos.append((r, c))
                    ch = grid[r][c]
                    if ch == 'M':
                        m0 = k
                    elif ch == 'C':
                        c0 = k
                    elif ch == 'F':
                        f0 = k

        n = len(idx_to_pos)

        def enum_moves(jump):
            outs = [[] for _ in range(n)]
            for i in range(n):
                r, c = idx_to_pos[i]
                outs[i].append(i)
                for dr, dc in moves_dirs:
                    rr, cc = r, c
                    for _ in range(1, jump + 1):
                        rr += dr
                        cc += dc
                        if rr < 0 or rr >= rows or cc < 0 or cc >= cols:
                            break
                        if grid[rr][cc] == '#':
                            break
                        outs[i].append(pos_to_idx[(rr, cc)])
            return outs

        mm = enum_moves(mouseJump)
        cm = enum_moves(catJump)

        mpar = [[] for _ in range(n)]
        cpar = [[] for _ in range(n)]
        for i in range(n):
            for j in mm[i]:
                mpar[j].append(i)
            for j in cm[i]:
                cpar[j].append(i)

        MOUSE_WIN, CAT_WIN = 1, 2
        color = [[[0, 0] for _ in range(n)] for __ in range(n)]
        degree = [[[0, 0] for _ in range(n)] for __ in range(n)]
        for i in range(n):
            for j in range(n):
                degree[i][j][0] = len(mm[i])
                degree[i][j][1] = len(cm[j])

        stack = []
        for i in range(n):
            for j in range(n):
                if i == f0:
                    if color[i][j][0] == 0:
                        color[i][j][0] = MOUSE_WIN
                        stack.append((i, j, 0))
                    if color[i][j][1] == 0:
                        color[i][j][1] = MOUSE_WIN
                        stack.append((i, j, 1))
                elif j == f0 or j == i:
                    if color[i][j][0] == 0:
                        color[i][j][0] = CAT_WIN
                        stack.append((i, j, 0))
                    if color[i][j][1] == 0:
                        color[i][j][1] = CAT_WIN
                        stack.append((i, j, 1))

        while stack:
            m, c, t = stack.pop()
            res = color[m][c][t]
            if t == 0:
                for prev_c in cpar[c]:
                    if color[m][prev_c][1] != 0:
                        continue
                    if res == CAT_WIN:
                        color[m][prev_c][1] = CAT_WIN
                        stack.append((m, prev_c, 1))
                    else:
                        degree[m][prev_c][1] -= 1
                        if degree[m][prev_c][1] == 0:
                            color[m][prev_c][1] = res
                            stack.append((m, prev_c, 1))
            else:
                for prev_m in mpar[m]:
                    if color[prev_m][c][0] != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[prev_m][c][0] = MOUSE_WIN
                        stack.append((prev_m, c, 0))
                    else:
                        degree[prev_m][c][0] -= 1
                        if degree[prev_m][c][0] == 0:
                            color[prev_m][c][0] = res
                            stack.append((prev_m, c, 0))

        return color[m0][c0][0] == MOUSE_WIN

