from typing import List
from collections import deque

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        dirs = [(-1,0), (1,0), (0,-1), (0,1)]

        pos_to_idx = {}
        idx_to_pos = []
        m_start = c_start = f_idx = -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                idx = len(idx_to_pos)
                pos_to_idx[(r, c)] = idx
                idx_to_pos.append((r, c))
                if grid[r][c] == 'M':
                    m_start = idx
                elif grid[r][c] == 'C':
                    c_start = idx
                elif grid[r][c] == 'F':
                    f_idx = idx

        n = len(idx_to_pos)

        def moves_from(jump: int):
            mv = [[] for _ in range(n)]
            for i in range(n):
                r, c = idx_to_pos[i]
                mv[i].append(i)
                for dr, dc in dirs:
                    nr, nc = r, c
                    for _ in range(1, jump + 1):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if grid[nr][nc] == '#':
                            break
                        mv[i].append(pos_to_idx[(nr, nc)])
            return mv

        m_moves = moves_from(mouseJump)
        c_moves = moves_from(catJump)

        m_par = [[] for _ in range(n)]
        c_par = [[] for _ in range(n)]
        for i in range(n):
            for j in m_moves[i]:
                m_par[j].append(i)
            for j in c_moves[i]:
                c_par[j].append(i)

        MOUSE_WIN, CAT_WIN = 1, 2

        # Use dictionaries for color and degree keyed by (m, c, t)
        color = {}
        degree = {}

        for m in range(n):
            for c in range(n):
                degree[(m, c, 0)] = len(m_moves[m])
                degree[(m, c, 1)] = len(c_moves[c])

        q = deque()
        for m in range(n):
            for c in range(n):
                if m == f_idx:
                    if color.get((m, c, 0), 0) == 0:
                        color[(m, c, 0)] = MOUSE_WIN
                        q.append((m, c, 0))
                    if color.get((m, c, 1), 0) == 0:
                        color[(m, c, 1)] = MOUSE_WIN
                        q.append((m, c, 1))
                elif c == f_idx or c == m:
                    if color.get((m, c, 0), 0) == 0:
                        color[(m, c, 0)] = CAT_WIN
                        q.append((m, c, 0))
                    if color.get((m, c, 1), 0) == 0:
                        color[(m, c, 1)] = CAT_WIN
                        q.append((m, c, 1))

        while q:
            m, c, t = q.popleft()
            res = color[(m, c, t)]
            if t == 0:
                for pc in c_par[c]:
                    if color.get((m, pc, 1), 0) != 0:
                        continue
                    if res == CAT_WIN:
                        color[(m, pc, 1)] = CAT_WIN
                        q.append((m, pc, 1))
                    else:
                        degree[(m, pc, 1)] -= 1
                        if degree[(m, pc, 1)] == 0:
                            color[(m, pc, 1)] = res
                            q.append((m, pc, 1))
            else:
                for pm in m_par[m]:
                    if color.get((pm, c, 0), 0) != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[(pm, c, 0)] = MOUSE_WIN
                        q.append((pm, c, 0))
                    else:
                        degree[(pm, c, 0)] -= 1
                        if degree[(pm, c, 0)] == 0:
                            color[(pm, c, 0)] = res
                            q.append((pm, c, 0))

        return color.get((m_start, c_start, 0), 0) == MOUSE_WIN

