from typing import List
from collections import deque

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        coord_to_id = {}
        id_to_coord = []
        m_start = c_start = f_pos = -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                idx = len(id_to_coord)
                coord_to_id[(r, c)] = idx
                id_to_coord.append((r, c))
                ch = grid[r][c]
                if ch == 'M':
                    m_start = idx
                elif ch == 'C':
                    c_start = idx
                elif ch == 'F':
                    f_pos = idx

        n = len(id_to_coord)

        def build_transitions(max_jump: int):
            trans = [[] for _ in range(n)]
            for i in range(n):
                r, c = id_to_coord[i]
                trans[i].append(i)  # stay put
                for dr, dc in directions:
                    nr, nc = r, c
                    for _ in range(1, max_jump + 1):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if grid[nr][nc] == '#':
                            break
                        trans[i].append(coord_to_id[(nr, nc)])
            return trans

        mouse_next = build_transitions(mouseJump)
        cat_next = build_transitions(catJump)

        mouse_prev = [[] for _ in range(n)]
        cat_prev = [[] for _ in range(n)]
        for i in range(n):
            for j in mouse_next[i]:
                mouse_prev[j].append(i)
            for j in cat_next[i]:
                cat_prev[j].append(i)

        MOUSE_WIN, CAT_WIN = 1, 2

        color = [[[0, 0] for _ in range(n)] for __ in range(n)]
        degree = [[[0, 0] for _ in range(n)] for __ in range(n)]
        steps = [[[0, 0] for _ in range(n)] for __ in range(n)]
        max_acc = [[[0, 0] for _ in range(n)] for __ in range(n)]

        for mi in range(n):
            for ci in range(n):
                degree[mi][ci][0] = len(mouse_next[mi])
                degree[mi][ci][1] = len(cat_next[ci])

        q = deque()
        for mi in range(n):
            for ci in range(n):
                # Priority: cat catches mouse > cat at food > mouse at food
                if ci == mi:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = CAT_WIN
                        steps[mi][ci][0] = 0
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = CAT_WIN
                        steps[mi][ci][1] = 0
                        q.append((mi, ci, 1))
                elif ci == f_pos:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = CAT_WIN
                        steps[mi][ci][0] = 0
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = CAT_WIN
                        steps[mi][ci][1] = 0
                        q.append((mi, ci, 1))
                elif mi == f_pos:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = MOUSE_WIN
                        steps[mi][ci][0] = 0
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = MOUSE_WIN
                        steps[mi][ci][1] = 0
                        q.append((mi, ci, 1))

        while q:
            m, c, t = q.popleft()
            res = color[m][c][t]
            sp = steps[m][c][t]
            if t == 0:
                # Prev states are (m, prev_c, 1)
                for prev_c in cat_prev[c]:
                    if color[m][prev_c][1] != 0:
                        continue
                    if res == CAT_WIN:
                        color[m][prev_c][1] = CAT_WIN
                        steps[m][prev_c][1] = sp + 1
                        q.append((m, prev_c, 1))
                    else:
                        degree[m][prev_c][1] -= 1
                        max_acc[m][prev_c][1] = max(max_acc[m][prev_c][1], sp + 1)
                        if degree[m][prev_c][1] == 0:
                            color[m][prev_c][1] = MOUSE_WIN
                            steps[m][prev_c][1] = max_acc[m][prev_c][1]
                            q.append((m, prev_c, 1))
            else:
                # t == 1; Prev states are (prev_m, c, 0)
                for prev_m in mouse_prev[m]:
                    if color[prev_m][c][0] != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[prev_m][c][0] = MOUSE_WIN
                        steps[prev_m][c][0] = sp + 1
                        q.append((prev_m, c, 0))
                    else:
                        degree[prev_m][c][0] -= 1
                        max_acc[prev_m][c][0] = max(max_acc[prev_m][c][0], sp + 1)
                        if degree[prev_m][c][0] == 0:
                            color[prev_m][c][0] = CAT_WIN
                            steps[prev_m][c][0] = max_acc[prev_m][c][0]
                            q.append((prev_m, c, 0))

        return color[m_start][c_start][0] == MOUSE_WIN and steps[m_start][c_start][0] <= 1000

