                if grid[r][c] == '#':
                    continue
                idx = len(idx_to_pos)
                pos_to_idx[(r, c)] = idx
                idx_to_pos.append((r, c))
                if grid[r][c] == 'M':
                    mouse_start = idx
                elif grid[r][c] == 'C':
                    cat_start = idx
                elif grid[r][c] == 'F':
                    food_pos = idx

        n = len(idx_to_pos)

        def compute_moves(jump: int):
            moves = [[] for _ in range(n)]
            i = 0
            while i < n:
                r, c = idx_to_pos[i]
                moves[i].append(i)
                d = 0
                while d < 4:
                    dr, dc = dirs[d]
                    nr, nc = r, c
                    step = 1
                    while step <= jump:
                        nr += dr
                        nc += dc
                        if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                            break
                        if grid[nr][nc] == '#':
                            break
                        moves[i].append(pos_to_idx[(nr, nc)])
                        step += 1
                    d += 1
                i += 1
            return moves

        mouse_moves = compute_moves(mouseJump)
        cat_moves = compute_moves(catJump)

        mouse_parents = [[] for _ in range(n)]
        cat_parents = [[] for _ in range(n)]
        s = 0
        while s < n:
            for dst in mouse_moves[s]:
                mouse_parents[dst].append(s)
            for dst in cat_moves[s]:
                cat_parents[dst].append(s)
            s += 1

        MOUSE_WIN, CAT_WIN = 1, 2

        color = [[[0, 0] for _ in range(n)] for __ in range(n)]
        degree = [[[0, 0] for _ in range(n)] for __ in range(n)]
        mi = 0
        while mi < n:
            ci = 0
            while ci < n:
                degree[mi][ci][0] = len(mouse_moves[mi])
                degree[mi][ci][1] = len(cat_moves[ci])
                ci += 1
            mi += 1

        q = deque()
        mi = 0
        while mi < n:
            ci = 0
            while ci < n:
                if ci == mi:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = CAT_WIN
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = CAT_WIN
                        q.append((mi, ci, 1))
                elif ci == food_pos:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = CAT_WIN
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = CAT_WIN
                        q.append((mi, ci, 1))
                elif mi == food_pos:
                    if color[mi][ci][0] == 0:
                        color[mi][ci][0] = MOUSE_WIN
                        q.append((mi, ci, 0))
                    if color[mi][ci][1] == 0:
                        color[mi][ci][1] = MOUSE_WIN
                        q.append((mi, ci, 1))
                ci += 1
            mi += 1

        def process_cat_parents(m, c, res):
            idx = 0
            plist = cat_parents[c]
            while idx < len(plist):
                pc = plist[idx]
                if color[m][pc][1] == 0:
                    if res == 2:
                        color[m][pc][1] = 2
                        q.append((m, pc, 1))
                    else:
                        degree[m][pc][1] -= 1
                        if degree[m][pc][1] == 0:
                            color[m][pc][1] = res
                            q.append((m, pc, 1))
                idx += 1

        def process_mouse_parents(m, c, res):
            idx = 0
            plist = mouse_parents[m]
            while idx < len(plist):
                pm = plist[idx]
                if color[pm][c][0] == 0:
                    if res == 1:
                        color[pm][c][0] = 1
                        q.append((pm, c, 0))
                    else:
                        degree[pm][c][0] -= 1
                        if degree[pm][c][0] == 0:
                            color[pm][c][0] = res
                            q.append((pm, c, 0))
                idx += 1

        while len(q) > 0:
            m, c, t = q.popleft()
            res = color[m][c][t]
            if t == 0:
                process_cat_parents(m, c, res)
            else:
                process_mouse_parents(m, c, res)

        return color[mouse_start][cat_start][0] == MOUSE_WIN

