                if grid[r][c] != '#':
                    k = len(idx_to_pos)
                    pos_to_idx[(r, c)] = k
                    idx_to_pos.append((r, c))
                    ch = grid[r][c]
                    if ch == 'M':
                        m0 = k
                    elif ch == 'C':
                        c0 = k
                    elif ch == 'F':
                        f0 = k

        n = len(idx_to_pos)

        def enum_mouse_moves(jump):
            outs = [[] for _ in range(n)]
            for i in range(n):
                r, c = idx_to_pos[i]
                outs[i].append(i)
                for dr, dc in moves_dirs:
                    rr, cc = r, c
                    for _ in range(1, jump + 1):
                        rr += dr
                        cc += dc
                        if rr < 0 or rr >= rows or cc < 0 or cc >= cols:
                            break
                        if grid[rr][cc] == '#':
                            break
                        outs[i].append(pos_to_idx[(rr, cc)])
            return outs

        mm = enum_mouse_moves(mouseJump)

        # Mouse parent mapping (independent of cat position)
        mpar = [[] for _ in range(n)]
        for i in range(n):
            for j in mm[i]:
                mpar[j].append(i)

        # Cat parent mapping depends on mouse position (cat cannot jump over mouse)
        cpar = [[[] for _ in range(n)] for __ in range(n)]  # cpar[mouse][cat_next] -> list of cat_prev
        cat_deg = [[0 for _ in range(n)] for __ in range(n)]  # cat_deg[mouse][cat_pos]
        for m in range(n):
            mr, mc = idx_to_pos[m]
            for c in range(n):
                cr, cc = idx_to_pos[c]
                # Staying in place
                cat_moves = [c]
                # Explore directions up to catJump, but stop if encounter mouse (include that square then stop)
                for dr, dc in moves_dirs:
                    rr, cc2 = cr, cc
                    for _ in range(1, catJump + 1):
                        rr += dr
                        cc2 += dc
                        if rr < 0 or rr >= rows or cc2 < 0 or cc2 >= cols:
                            break
                        if grid[rr][cc2] == '#':
                            break
                        idx = pos_to_idx[(rr, cc2)]
                        cat_moves.append(idx)
                        if idx == m:
                            break  # cannot jump over mouse
                cat_deg[m][c] = len(cat_moves)
                for cn in cat_moves:
                    cpar[m][cn].append(c)

        MOUSE_WIN, CAT_WIN = 1, 2
        color = [[[0, 0] for _ in range(n)] for __ in range(n)]  # [mouse][cat][turn]
        degree = [[[0, 0] for _ in range(n)] for __ in range(n)]
        for i in range(n):
            for j in range(n):
                degree[i][j][0] = len(mm[i])
                degree[i][j][1] = cat_deg[i][j]

        stack = []
        for i in range(n):
            for j in range(n):
                if i == f0:
                    if color[i][j][0] == 0:
                        color[i][j][0] = MOUSE_WIN
                        stack.append((i, j, 0))
                    if color[i][j][1] == 0:
                        color[i][j][1] = MOUSE_WIN
                        stack.append((i, j, 1))
                elif j == f0 or j == i:
                    if color[i][j][0] == 0:
                        color[i][j][0] = CAT_WIN
                        stack.append((i, j, 0))
                    if color[i][j][1] == 0:
                        color[i][j][1] = CAT_WIN
                        stack.append((i, j, 1))

        while stack:
            m, c, t = stack.pop()
            res = color[m][c][t]
            if t == 0:
                # Mouse to move; predecessors are cat-turn states with same mouse m and cat prev that can move to c without jumping over m
                for prev_c in cpar[m][c]:
                    if color[m][prev_c][1] != 0:
                        continue
                    if res == CAT_WIN:
                        color[m][prev_c][1] = CAT_WIN
                        stack.append((m, prev_c, 1))
                    else:
                        degree[m][prev_c][1] -= 1
                        if degree[m][prev_c][1] == 0:
                            color[m][prev_c][1] = res
                            stack.append((m, prev_c, 1))
            else:
                # Cat to move; predecessors are mouse-turn states with same cat c and mouse prev that can move to m
                for prev_m in mpar[m]:
                    if color[prev_m][c][0] != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[prev_m][c][0] = MOUSE_WIN
                        stack.append((prev_m, c, 0))
                    else:
                        degree[prev_m][c][0] -= 1
                        if degree[prev_m][c][0] == 0:
                            color[prev_m][c][0] = res
                            stack.append((prev_m, c, 0))

        return color[m0][c0][0] == MOUSE_WIN

