                elif grid[r][c] == 'C':
                    c_start = idx
                elif grid[r][c] == 'F':
                    f_idx = idx

        n = len(idx_to_pos)

        def moves_from(jump: int):
            mv = [[] for _ in range(n)]
            for i in range(n):
                r, c = idx_to_pos[i]
                mv[i].append(i)  # staying is allowed
                for dr, dc in dirs:
                    nr, nc = r, c
                    for _ in range(1, jump + 1):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if grid[nr][nc] == '#':
                            break
                        mv[i].append(pos_to_idx[(nr, nc)])
            return mv

        m_moves = moves_from(mouseJump)
        c_moves = moves_from(catJump)

        m_par = [[] for _ in range(n)]
        c_par = [[] for _ in range(n)]
        for i in range(n):
            for j in m_moves[i]:
                m_par[j].append(i)
            for j in c_moves[i]:
                c_par[j].append(i)

        MOUSE_WIN, CAT_WIN = 1, 2

        def cat_path_blocked_by_mouse(start_idx: int, end_idx: int, mouse_idx: int) -> bool:
            if start_idx == end_idx:
                return False
            sr, sc = idx_to_pos[start_idx]
            er, ec = idx_to_pos[end_idx]
            mr, mc = idx_to_pos[mouse_idx]
            if sr == er:
                if mr != sr:
                    return False
                # blocked if mouse strictly between start and end columns
                return (sc < mc < ec) or (ec < mc < sc)
            if sc == ec:
                if mc != sc:
                    return False
                # blocked if mouse strictly between start and end rows
                return (sr < mr < er) or (er < mr < sr)
            # not a straight line move (shouldn't happen given precomputed moves), not blocked
            return False

        def valid_cat_moves_from(c_idx: int, m_idx: int):
            res = []
            for d in c_moves[c_idx]:
                if d == c_idx or d == m_idx:
