        degree = {}

        for m in range(n):
            for c in range(n):
                degree[(m, c, 0)] = len(m_moves[m])
                degree[(m, c, 1)] = len(valid_cat_moves_from(c, m))

        q = deque()
        for m in range(n):
            for c in range(n):
                if m == f_idx:
                    if color.get((m, c, 0), 0) == 0:
                        color[(m, c, 0)] = MOUSE_WIN
                        q.append((m, c, 0))
                    if color.get((m, c, 1), 0) == 0:
                        color[(m, c, 1)] = MOUSE_WIN
                        q.append((m, c, 1))
                elif c == f_idx or c == m:
                    if color.get((m, c, 0), 0) == 0:
                        color[(m, c, 0)] = CAT_WIN
                        q.append((m, c, 0))
                    if color.get((m, c, 1), 0) == 0:
                        color[(m, c, 1)] = CAT_WIN
                        q.append((m, c, 1))

        while q:
            m, c, t = q.popleft()
            res = color[(m, c, t)]
            if t == 0:
                # previous was cat's turn: (m, pc, 1) -> (m, c, 0) by cat moving from pc to c
                for pc in c_par[c]:
                    if color.get((m, pc, 1), 0) != 0:
                        continue
                    # cat cannot jump over mouse; allowed if path not blocked or destination is mouse
                    if c != m and cat_path_blocked_by_mouse(pc, c, m):
                        continue
                    if res == CAT_WIN:
                        color[(m, pc, 1)] = CAT_WIN
                        q.append((m, pc, 1))
                    else:
                        degree[(m, pc, 1)] -= 1
                        if degree[(m, pc, 1)] == 0:
                            color[(m, pc, 1)] = res
                            q.append((m, pc, 1))
            else:
                # previous was mouse's turn: (pm, c, 0) -> (m, c, 1) by mouse moving from pm to m
                for pm in m_par[m]:
                    if color.get((pm, c, 0), 0) != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[(pm, c, 0)] = MOUSE_WIN
                        q.append((pm, c, 0))
                    else:
                        degree[(pm, c, 0)] -= 1
                        if degree[(pm, c, 0)] == 0:
