from collections import deque

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        dirs = [(-1,0), (1,0), (0,-1), (0,1)]

        # Collect valid cells and positions of M, C, F
        pos_to_idx = {}
        idx_to_pos = []
        mouse_start = cat_start = food_pos = -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != '#':
                    idx = len(idx_to_pos)
                    pos_to_idx[(r, c)] = idx
                    idx_to_pos.append((r, c))
                    if grid[r][c] == 'M':
                        mouse_start = idx
                    elif grid[r][c] == 'C':
                        cat_start = idx
                    elif grid[r][c] == 'F':
                        food_pos = idx

        n = len(idx_to_pos)

        # Precompute moves for mouse, including staying in place (independent of cat)
        def compute_mouse_moves(jump: int):
            moves = [[] for _ in range(n)]
            for i in range(n):
                r, c = idx_to_pos[i]
                # Staying in place is allowed
                moves[i].append(i)
                for dr, dc in dirs:
                    nr, nc = r, c
                    for _ in range(1, jump + 1):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if grid[nr][nc] == '#':
                            break
                        moves[i].append(pos_to_idx[(nr, nc)])
            return moves

        mouse_moves = compute_mouse_moves(mouseJump)

        # Precompute reverse moves (parents) for mouse
        mouse_parents = [[] for _ in range(n)]
        for src in range(n):
            for dst in mouse_moves[src]:
                mouse_parents[dst].append(src)

        # Precompute cat moves and parents for each mouse position (cat cannot jump over mouse)
        cat_moves_by_m = [[[] for _ in range(n)] for __ in range(n)]
        cat_parents_by_m = [[[] for _ in range(n)] for __ in range(n)]
        for m in range(n):
            mr, mc = idx_to_pos[m]
            for c in range(n):
                r, cc = idx_to_pos[c]
                moves = [c]  # staying in place
                for dr, dc in dirs:
                    nr, nc = r, cc
                    for _ in range(1, catJump + 1):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if grid[nr][nc] == '#':
                            break
                        nxt = pos_to_idx[(nr, nc)]
                        moves.append(nxt)
                        # Cat cannot jump over mouse; can land on mouse, then stop
                        if nxt == m:
                            break
                cat_moves_by_m[m][c] = moves
                for dst in moves:
                    cat_parents_by_m[m][dst].append(c)

        MOUSE_WIN, CAT_WIN = 1, 2

        # color[m][c][t] where t=0 mouse's turn, t=1 cat's turn
        color = [[[0, 0] for _ in range(n)] for __ in range(n)]
        degree = [[[0, 0] for _ in range(n)] for __ in range(n)]

        for m in range(n):
            for c in range(n):
                degree[m][c][0] = len(mouse_moves[m])
                degree[m][c][1] = len(cat_moves_by_m[m][c])

        # Initialize queue with terminal states
        q = deque()
        for m in range(n):
            for c in range(n):
                if m == food_pos:
                    if color[m][c][0] == 0:
                        color[m][c][0] = MOUSE_WIN
                        q.append((m, c, 0))
                    if color[m][c][1] == 0:
                        color[m][c][1] = MOUSE_WIN
                        q.append((m, c, 1))
                elif c == food_pos or c == m:
                    if color[m][c][0] == 0:
                        color[m][c][0] = CAT_WIN
                        q.append((m, c, 0))
                    if color[m][c][1] == 0:
                        color[m][c][1] = CAT_WIN
                        q.append((m, c, 1))

        # Retrograde analysis via BFS
        while q:
            m, c, t = q.popleft()
            res = color[m][c][t]
            if t == 0:
                # Current is mouse's turn, previous was cat's turn
                # Parents: (m, pc, 1) where pc can move to c without jumping over m
                for pc in cat_parents_by_m[m][c]:
                    pt = 1
                    if color[m][pc][pt] != 0:
                        continue
                    if res == CAT_WIN:
                        color[m][pc][pt] = CAT_WIN
                        q.append((m, pc, pt))
                    else:
                        degree[m][pc][pt] -= 1
                        if degree[m][pc][pt] == 0:
                            color[m][pc][pt] = res
                            q.append((m, pc, pt))
            else:
                # Current is cat's turn, previous was mouse's turn
                # Parents: (pm, c, 0) where pm can move to m
                for pm in mouse_parents[m]:
                    pt = 0
                    if color[pm][c][pt] != 0:
                        continue
                    if res == MOUSE_WIN:
                        color[pm][c][pt] = MOUSE_WIN
                        q.append((pm, c, pt))
                    else:
                        degree[pm][c][pt] -= 1
                        if degree[pm][c][pt] == 0:
                            color[pm][c][pt] = res
                            q.append((pm, c, pt))

        # If unresolved, by problem rule it's a cat win (mouse cannot ensure win within limit)
        return color[mouse_start][cat_start][0] == MOUSE_WIN

