class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        if valueDiff < 0:
            return False

        bucket_width = valueDiff + 1
        bucket_map = {}

        for pos, val in enumerate(nums):
            bucket_id = val // bucket_width

            if bucket_id in bucket_map:
                return True

            for adj in (bucket_id - 1, bucket_id + 1):
                if adj in bucket_map and abs(val - bucket_map[adj]) <= valueDiff:
                    return True

            bucket_map[bucket_id] = val

            if pos >= indexDiff:
                out_val = nums[pos - indexDiff]
                out_bucket = out_val // bucket_width
                if out_bucket in bucket_map:
                    del bucket_map[out_bucket]

        return False

