class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        if valueDiff < 0:
            return False

        w = valueDiff + 1
        buckets = {}

        def has_close(bid: int, x: int) -> bool:
            if bid in buckets:
                return True
            if (bid - 1 in buckets) and abs(x - buckets[bid - 1]) <= valueDiff:
                return True
            if (bid + 1 in buckets) and abs(x - buckets[bid + 1]) <= valueDiff:
                return True
            return False

        i = 0
        n = len(nums)
        while i < n:
            x = nums[i]
            b = x // w

            if has_close(b, x):
                return True

            buckets[b] = x

            if i >= indexDiff:
                old = nums[i - indexDiff]
                old_b = old // w
                if old_b in buckets:
                    del buckets[old_b]
            i += 1

        return False

