from typing import List
from bisect import bisect_left, insort

class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        if valueDiff < 0:
            return False

        window: List[int] = []

        for i, x in enumerate(nums):
            pos = bisect_left(window, x)

            if pos < len(window) and window[pos] - x <= valueDiff:
                return True
            if pos > 0 and x - window[pos - 1] <= valueDiff:
                return True

            insort(window, x)

            if i >= indexDiff:
                to_remove = nums[i - indexDiff]
                idx = bisect_left(window, to_remove)
                if idx < len(window) and window[idx] == to_remove:
                    window.pop(idx)

        return False

