from typing import List

class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        if not (valueDiff >= 0):
            return False

        width = valueDiff + 1
        buckets = {}

        for i, num in enumerate(nums):
            bid = num // width

            for off in (0, -1, 1):
                check_id = bid + off
                if check_id in buckets:
                    if off == 0:
                        return True
                    if abs(num - buckets[check_id]) <= valueDiff:
                        return True

            buckets[bid] = num

            if i >= indexDiff:
                old_val = nums[i - indexDiff]
                old_bid = old_val // width
                buckets.pop(old_bid, None)

        return False

