from typing import List

class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0]) if m else 0
        heights = [0] * n
        total = 0

        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1:
                    heights[j] += 1
                else:
                    heights[j] = 0

            stack = []
            row_sum = 0
            for j in range(n):
                cnt = 1
                while stack and stack[-1][0] >= heights[j]:
                    h_prev, c_prev = stack.pop()
                    cnt += c_prev
                    row_sum -= h_prev * c_prev
                row_sum += heights[j] * cnt
                stack.append((heights[j], cnt))
                total += row_sum

        return total

