            if x == cand1:
                count1 += 1
            elif x == cand2:
                count2 += 1

        res = []
        if count1 > n // 3:
            res.append(cand1)
        if cand2 is not None and cand2 != cand1 and count2 > n // 3:
            res.append(cand2)

        return res

