class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        def count_on(arr: List[int], l: int, r: int) -> int:
            total = 0
            i = l
            while i <= r:
                total += arr[i]
                i += 1
            return total

        def place(arr: List[int], l: int, r: int, k: int) -> int:
            placed = 0
            for t in range(r, l - 1, -1):
                if arr[t] == 0:
                    arr[t] = 1
                    placed += 1
                    if placed == k:
                        break
            return placed

        tasks.sort(key=lambda x: x[1])
        max_time = max(e for _, e, _ in tasks)
        used = [0] * (max_time + 2)
        ans = 0

        for s, e, d in tasks:
            already = count_on(used, s, e)
            need = d - already
            if need > 0:
                ans += place(used, s, e, need)

        return ans

