from typing import List

class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        # Sort tasks by their end time to make greedy choices optimally
        tasks.sort(key=lambda x: x[1])
        max_time = max(e for _, e, _ in tasks)

        # used[t] indicates whether time t is already scheduled (1) or not (0)
        used = [0] * (max_time + 2)
        ans = 0

        for s, e, d in tasks:
            # Count how many seconds are already scheduled within [s, e]
            already = 0
            for t in range(s, e + 1):
                already += used[t]

            need = d - already
            if need <= 0:
                continue

            # Greedily schedule needed seconds as late as possible within [s, e]
            t = e
            while need > 0 and t >= s:
                if used[t] == 0:
                    used[t] = 1
                    ans += 1
                    need -= 1
                t -= 1

        return ans

