from typing import List, Optional
from collections import Counter

class Solution:
    def recoverArray(self, n: int, sums: List[int]) -> List[int]:
        def split_groups(arr: List[int], d: int):
            c = Counter(arr)
            lo, hi = [], []
            for s in arr:
                if c[s] == 0:
                    continue
                if c[s + d] == 0:
                    return None
                lo.append(s)
                c[s] -= 1
                c[s + d] -= 1
                hi.append(s + d)
            return lo, hi

        def dfs(arr: List[int], k: int) -> Optional[List[int]]:
            if k == 0:
                return []
            arr.sort()
            d = arr[1] - arr[0]
            split = split_groups(arr, d)
            if split is None:
                return None
            low, high = split

            if 0 in low:
                res = dfs(low, k - 1)
                if res is not None:
                    res.append(d)
                    return res
            else:
                res = dfs(high, k - 1)
                if res is not None:
                    res.append(-d)
                    return res
            return None

        ans = dfs(sorted(sums), n)
        return ans if ans is not None else []

from typing import List

class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 2:
            return -1
        ans = -1
        curr_len = 1
        expected = None  # next expected diff when in a valid sequence

        for i in range(1, n):
            diff = nums[i] - nums[i - 1]
            if curr_len == 1:
                if diff == 1:
                    curr_len = 2
                    expected = -1
                    if curr_len > ans:
                        ans = curr_len
                else:
                    curr_len = 1
                    expected = None
            else:
                if diff == expected:
                    curr_len += 1
                    expected = -expected
                    if curr_len > ans:
                        ans = curr_len
                else:
                    if diff == 1:
                        curr_len = 2
                        expected = -1
                        if curr_len > ans:
                            ans = curr_len
                    else:
                        curr_len = 1
                        expected = None

        return ans

