from typing import List

class Solution:
    def maximizeWin(self, prizePositions: List[int], k: int) -> int:
        n = len(prizePositions)
        right = [0] * n
        count = [0] * n

        r = 0
        for i in range(n):
            while r < n and prizePositions[r] - prizePositions[i] <= k:
                r += 1
            right[i] = r - 1
            count[i] = r - i

        best = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            best[i] = max(best[i + 1], count[i])

        ans = 0
        for i in range(n):
            nxt = right[i] + 1
            second = best[nxt]
            if count[i] + second > ans:
                ans = count[i] + second

        return ans

