from typing import List

class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:
        if not rectangles:
            return False

        def toggle(s: set, pt: tuple) -> None:
            if pt in s:
                s.remove(pt)
            else:
                s.add(pt)

        # First pass: compute bounding box
        x1, y1, x2, y2 = rectangles[0]
        min_x, min_y, max_x, max_y = x1, y1, x2, y2
        for i in range(1, len(rectangles)):
            a, b, c, d = rectangles[i]
            if a < min_x:
                min_x = a
            if b < min_y:
                min_y = b
            if c > max_x:
                max_x = c
            if d > max_y:
                max_y = d

        # Second pass: area and corner toggling
        total_area = 0
        corner_set = set()
        idx = 0
        while idx < len(rectangles):
            x1, y1, x2, y2 = rectangles[idx]
            total_area += (x2 - x1) * (y2 - y1)
            toggle(corner_set, (x1, y1))
            toggle(corner_set, (x1, y2))
            toggle(corner_set, (x2, y1))
            toggle(corner_set, (x2, y2))
            idx += 1

        expected = {(min_x, min_y), (min_x, max_y), (max_x, min_y), (max_x, max_y)}
        if corner_set != expected:
            return False

        return total_area == (max_x - min_x) * (max_y - min_y)

