from typing import List

class Solution:
    def wiggleSort(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        size = len(nums)
        for idx in range(1, size):
            odd_index = (idx & 1) == 1
            left = nums[idx - 1]
            right = nums[idx]
            if (odd_index and right < left) or ((not odd_index) and right > left):
                nums[idx], nums[idx - 1] = left, right

