class Solution:
    def wiggleSort(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        def adjust(k: int) -> None:
            if (k % 2 == 1 and nums[k] < nums[k - 1]) or (k % 2 == 0 and nums[k] > nums[k - 1]):
                nums[k], nums[k - 1] = nums[k - 1], nums[k]

        n = len(nums)
        i = 1
        while i < n:
            adjust(i)
            i += 1

