from typing import List

class Solution:
    def optimalDivision(self, nums: List[int]) -> str:
        n = len(nums)
        if n == 1:
            return str(nums[0])
        if n == 2:
            return f"{nums[0]}/{nums[1]}"

        # DP over intervals to compute max/min values and corresponding expressions
        dp_min = [[0.0] * n for _ in range(n)]
        dp_max = [[0.0] * n for _ in range(n)]
        s_min = [[""] * n for _ in range(n)]
        s_max = [[""] * n for _ in range(n)]

        for i in range(n):
            dp_min[i][i] = dp_max[i][i] = float(nums[i])
            s_min[i][i] = s_max[i][i] = str(nums[i])

        for L in range(2, n + 1):
            for i in range(0, n - L + 1):
                j = i + L - 1
                dp_min[i][j] = float("inf")
                dp_max[i][j] = float("-inf")
                s_min[i][j] = s_max[i][j] = ""
                for k in range(i, j):
                    # For max: maximize numerator and minimize denominator
                    left_max = dp_max[i][k]
                    right_min = dp_min[k + 1][j]
                    if right_min != 0:
                        val_max = left_max / right_min
                        if val_max > dp_max[i][j]:
                            dp_max[i][j] = val_max
                            right_str = s_min[k + 1][j]
                            denom = f"({right_str})" if j - (k + 1) >= 1 else right_str
                            s_max[i][j] = s_max[i][k] + "/" + denom

                    # For min: minimize numerator and maximize denominator
                    left_min = dp_min[i][k]
                    right_max = dp_max[k + 1][j]
                    if right_max != 0:
                        val_min = left_min / right_max
                        if val_min < dp_min[i][j]:
                            dp_min[i][j] = val_min
                            right_str = s_max[k + 1][j]
                            denom = f"({right_str})" if j - (k + 1) >= 1 else right_str
                            s_min[i][j] = s_min[i][k] + "/" + denom

        return s_max[0][n - 1]

