from typing import List

class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        m = len(nums)
        up = [1] * m
        for i, v in enumerate(nums):
            for j in range(i):
                if nums[j] < v:
                    candidate = up[j] + 1
                    if candidate > up[i]:
                        up[i] = candidate

        down = [1] * m
        for i in range(m - 1, -1, -1):
            cur = nums[i]
            for j in range(i + 1, m):
                if nums[j] < cur:
                    nxt = down[j] + 1
                    if nxt > down[i]:
                        down[i] = nxt

        best = max((up[k] + down[k] - 1 for k in range(1, m - 1) if up[k] > 1 and down[k] > 1), default=0)
        return m - best

