from typing import List

class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)

        inc = [1] * n
        i = 0
        while i < n:
            j = 0
            while j < i:
                if nums[j] < nums[i]:
                    cand = inc[j] + 1
                    if cand > inc[i]:
                        inc[i] = cand
                j += 1
            i += 1

        dec = [1] * n
        i = n - 1
        while i >= 0:
            j = i + 1
            while j < n:
                if nums[j] < nums[i]:
                    cand = dec[j] + 1
                    if cand > dec[i]:
                        dec[i] = cand
                j += 1
            i -= 1

        best = 0
        k = 1
        while k <= n - 2:
            if inc[k] > 1 and dec[k] > 1:
                total = inc[k] + dec[k] - 1
                if total > best:
                    best = total
            k += 1

        return n - best

