from typing import List

class Solution:
    def isOneBitCharacter(self, bits: List[int]) -> bool:
        n = len(bits)

        def walk(k: int) -> bool:
            if k == n - 1:
                return True
            if k >= n:
                return False
            if bits[k] == 1:
                return walk(k + 2)
            else:
                return walk(k + 1)

        return walk(0)

