from collections import deque

class Solution:
    def isOneBitCharacter(self, bits: List[int]) -> bool:
        q = deque(bits)
        while len(q) > 1:
            first = q.popleft()
            if first == 1:
                if q:
                    q.popleft()
            else:
                pass
        return len(q) == 1 and q[0] == 0

