from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        counts = [0] * 31  # counts of 2^i
        for x in nums:
            counts[x.bit_length() - 1] += 1

        ops = 0
        for i in range(31):
            if (target >> i) & 1:
                if counts[i] > 0:
                    counts[i] -= 1
                else:
                    j = i + 1
                    while j < 31 and counts[j] == 0:
                        j += 1
                    if j == 31:
                        return -1
                    while j > i:
                        counts[j] -= 1
                        counts[j - 1] += 2
                        ops += 1
                        j -= 1
                    counts[i] -= 1
            if i < 30:
                counts[i + 1] += counts[i] // 2

        return ops

