class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        if total < target:
            return -1

        MAX_BIT = 31
        cnt = [0] * MAX_BIT
        for x in nums:
            cnt[x.bit_length() - 1] += 1

        def find_next_with_count(start_bit: int) -> int:
            k = start_bit + 1
            while k < MAX_BIT and cnt[k] == 0:
                k += 1
            return k

        def pull_down_bits(from_bit: int, to_bit: int) -> int:
            # split one item from from_bit down to to_bit, return operations used
            used_ops = 0
            b = from_bit
            while b > to_bit:
                cnt[b] -= 1
                cnt[b - 1] += 2
                used_ops += 1
                b -= 1
            return used_ops

        ops = 0
        carry = 0
        i = 0
        while i < MAX_BIT:
            carry += cnt[i]
            if (target >> i) & 1:
                if carry > 0:
                    carry -= 1
                else:
                    j = find_next_with_count(i)
                    if j == MAX_BIT:
                        return -1
                    ops += pull_down_bits(j, i)
                    carry += 2  # now we have two units at this bit
                    carry -= 1  # use one for the target's bit
            carry //= 2
            i += 1

        return ops

