from typing import List
import heapq

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        big = []    # max-heap via negatives: values currently > target
        small = []  # max-heap via negatives: values currently <= target
        for x in nums:
            if x <= target:
                heapq.heappush(small, -x)
            else:
                heapq.heappush(big, -x)

        ops = 0
        while target > 0:
            # Reclassify elements that became <= target
            while big and -big[0] <= target:
                heapq.heappush(small, heapq.heappop(big))

            if small:
                take = -heapq.heappop(small)
                target -= take
                continue

            if not big:
                return -1

            y = -heapq.heappop(big)
            half = y // 2
            # split y into two halves
            if half <= target:
                heapq.heappush(small, -half)
                heapq.heappush(small, -half)
            else:
                heapq.heappush(big, -half)
                heapq.heappush(big, -half)
            ops += 1

        return ops

