from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        MAX_BIT = 31
        cnt = [0] * MAX_BIT
        for a in nums:
            cnt[a.bit_length() - 1] += 1

        def process_bit(idx: int, carry: int, acc_ops: int) -> int:
            if idx == MAX_BIT:
                return acc_ops
            carry += cnt[idx]
            if (target >> idx) & 1:
                if carry > 0:
                    carry -= 1
                else:
                    j = idx + 1
                    while j < MAX_BIT and cnt[j] == 0:
                        j += 1
                    if j == MAX_BIT:
                        return -1
                    while j > idx:
                        cnt[j] -= 1
                        cnt[j - 1] += 2
                        acc_ops += 1
                        j -= 1
                    carry += 2
                    carry -= 1
            carry //= 2
            return process_bit(idx + 1, carry, acc_ops)

        return process_bit(0, 0, 0)

