from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        def at_most(limit: int) -> int:
            res = 0
            left = 0
            odd = 0
            for right, v in enumerate(nums):
                if v & 1:
                    odd += 1
                while odd > limit:
                    if nums[left] & 1:
                        odd -= 1
                    left += 1
                res += right - left + 1
            return res

        return at_most(k) - at_most(k - 1)

