from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        odd_idx = [i for i, val in enumerate(nums) if val & 1]
        m = len(odd_idx)
        if m < k:
            return 0
        ans = 0
        n = len(nums)
        for i in range(m - k + 1):
            left_choices = odd_idx[i] - (odd_idx[i - 1] if i > 0 else -1)
            right_choices = (odd_idx[i + k] if i + k < m else n) - odd_idx[i + k - 1]
            ans += left_choices * right_choices
        return ans

