class Solution:
    def numberOfPaths(self, n: int, corridors: List[List[int]]) -> int:
        edges = [(u - 1, v - 1) for u, v in corridors]

        deg = [0] * n
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1

        forward = [set() for _ in range(n)]
        for u, v in edges:
            if deg[u] < deg[v] or (deg[u] == deg[v] and u < v):
                forward[u].add(v)
            else:
                forward[v].add(u)

        count = 0
        for u in range(n):
            if not forward[u]:
                continue
            for v in forward[u]:
                count += len(forward[u].intersection(forward[v]))

        return count

