        for u in range(n):
            if not F[u]:
                continue
            # Mark forward neighbors of u
            for w in F[u]:
                marked[w] = True
            # For each v reachable from u, check how many of its forward neighbors are also in F[u]
            for v in F[u]:
                for w in F[v]:
                    if marked[w]:
                        count += 1
            # Unmark
            for w in F[u]:
                marked[w] = False

        return count

