class Solution:
    def minimumOperations(self, nums: List[int], target: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        def helper(i: int, prev: int) -> int:
            if i >= n:
                return 0
            cur = target[i] - nums[i]
            add = 0
            if prev >= 0 and cur >= 0:
                if cur > prev:
                    add = cur - prev
            elif prev <= 0 and cur <= 0:
                if cur < prev:
                    add = prev - cur
            else:
                add = abs(cur)
            return add + helper(i + 1, cur)

        first = target[0] - nums[0]
        return abs(first) + helper(1, first)

