from typing import List

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        if n <= 1:
            return 0

        # Longest non-decreasing prefix via for-loop
        left = 0
        for k in range(n - 1):
            if arr[k] <= arr[k + 1]:
                left = k + 1
            else:
                break

        if left == n - 1:
            return 0

        # Longest non-decreasing suffix via for-loop
        right = n - 1
        for k in range(n - 1, 0, -1):
            if arr[k - 1] <= arr[k]:
                right = k - 1
            else:
                break

        ans = min(n - (left + 1), right)

        # Reorganized two-pointer bridging: outer for on i, inner while advancing j
        j = right
        for i in range(0, left + 1):
            while j < n and arr[i] > arr[j]:
                j += 1
            if j == n:
                break
            ans = min(ans, j - i - 1)

        return ans

