class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        if n <= 1:
            return 0

        # Find non-decreasing prefix
        l = 0
        while l + 1 < n and arr[l] <= arr[l + 1]:
            l += 1
        if l == n - 1:
            return 0

        # Find non-decreasing suffix
        r = n - 1
        while r - 1 >= 0 and arr[r - 1] <= arr[r]:
            r -= 1

        # Option: remove prefix or suffix entirely
        ans = min(n - (l + 1), r)

        # Algorithmic variant: binary search in the suffix for each prefix index
        suffix_vals = arr[r:]
        for i in range(l + 1):
            pos = bisect_left(suffix_vals, arr[i])
            if pos < len(suffix_vals):
                j = r + pos
                ans = min(ans, j - i - 1)

        return ans

