from typing import List

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        def longest_nondecreasing_prefix(a: List[int]) -> int:
            i = 0
            while i + 1 < len(a) and a[i] <= a[i + 1]:
                i += 1
            return i

        def longest_nondecreasing_suffix_start(a: List[int]) -> int:
            j = len(a) - 1
            while j - 1 >= 0 and a[j - 1] <= a[j]:
                j -= 1
            return j

        def bridge_prefix_suffix(a: List[int], left_end: int, right_start: int) -> int:
            best = float('inf')
            i, j = 0, right_start
            while i <= left_end and j < len(a):
                if a[i] <= a[j]:
                    best = min(best, j - i - 1)
                    i += 1
                else:
                    j += 1
            return best if best != float('inf') else len(a)

        n = len(arr)
        if n <= 1:
            return 0

        l = longest_nondecreasing_prefix(arr)
        if l == n - 1:
            return 0

        r = longest_nondecreasing_suffix_start(arr)
        base = min(n - (l + 1), r)
        merged = bridge_prefix_suffix(arr, l, r)
        return min(base, merged)

