from typing import List
from collections import deque

class Solution:
    def longestWord(self, words: List[str]) -> str:
        class Node:
            __slots__ = ("children", "end")
            def __init__(self):
                self.children = {}
                self.end = False

        root = Node()
        # Build trie
        for w in set(words):
            node = root
            for ch in w:
                if ch not in node.children:
                    node.children[ch] = Node()
                node = node.children[ch]
            node.end = True

        ans = ""
        q = deque()
        q.append(("", root))
        while q:
            path, node = q.popleft()
            for ch in sorted(node.children.keys()):
                nxt = node.children[ch]
                if nxt.end:
                    new_path = path + ch
                    if len(new_path) > len(ans) or (len(new_path) == len(ans) and new_path < ans):
                        ans = new_path
                    q.append((new_path, nxt))
        return ans

