from typing import List

class Solution:
    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        hits = {i: (src, tgt) for i, src, tgt in zip(indices, sources, targets) if s.startswith(src, i)}
        out = []
        i = 0
        n = len(s)
        while i < n:
            pair = hits.get(i)
            if pair is None:
                out.append(s[i])
                i += 1
            else:
                src, tgt = pair
                out.append(tgt)
                i += len(src)
        return ''.join(out)

