from typing import List

class Solution:
    def printVertically(self, s: str) -> List[str]:
        words = s.split()
        max_len = 0
        for w in words:
            if len(w) > max_len:
                max_len = len(w)

        def pick_char(word: str, idx: int) -> str:
            if idx < len(word):
                return word[idx]
            return ' '

        res: List[str] = []
        i = 0
        while i < max_len:
            buf: List[str] = []
            j = 0
            while j < len(words):
                buf.append(pick_char(words[j], i))
                j += 1
            res.append(''.join(buf).rstrip())
            i += 1
        return res

