from typing import List
import heapq

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        n = len(target)
        if n == 1:
            return target[0] == 1

        total = sum(target)
        heap = [-x for x in target]
        heapq.heapify(heap)

        while True:
            max_val = -heapq.heappop(heap)
            rest = total - max_val

            if max_val == 1 or rest == 1:
                return True

            if rest <= 0 or max_val <= rest:
                return False

            new_val = max_val % rest
            if new_val == 0:
                return False

            total = rest + new_val
            heapq.heappush(heap, -new_val)

