from typing import List
import heapq

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        n = len(target)
        if n == 1:
            return target[0] == 1

        total = sum(target)
        pq = [-x for x in target]
        heapq.heapify(pq)

        def recur(current_sum: int, h: List[int]) -> bool:
            max_val = -heapq.heappop(h)
            rest = current_sum - max_val

            if max_val == 1 or rest == 1:
                return True
            if rest <= 0 or rest >= max_val:
                return False

            new_val = max_val % rest
            if new_val == 0:
                return False

            heapq.heappush(h, -new_val)
            return recur(rest + new_val, h)

        return recur(total, pq)

