from typing import List

class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        left, right = 0, len(plants) - 1
        waterA, waterB = capacityA, capacityB
        refills = 0

        while left < right:
            if waterA < plants[left]:
                refills += 1
                waterA = capacityA
            waterA -= plants[left]
            left += 1

            if waterB < plants[right]:
                refills += 1
                waterB = capacityB
            waterB -= plants[right]
            right -= 1

        if left == right:
            if plants[left] > max(waterA, waterB):
                refills += 1

        return refills

