class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        n = len(plants)
        a, b = capacityA, capacityB
        refills = 0

        for k in range(n // 2):
            if a < plants[k]:
                refills += 1
                a = capacityA
            a -= plants[k]

            r = n - 1 - k
            if b < plants[r]:
                refills += 1
                b = capacityB
            b -= plants[r]

        if n % 2 == 1:
            mid = n // 2
            if max(a, b) < plants[mid]:
                refills += 1

        return refills

