class Solution:
    def removeInterval(self, intervals: List[List[int]], toBeRemoved: List[int]) -> List[List[int]]:
        r0, r1 = toBeRemoved
        res: List[List[int]] = []
        i = 0
        n = len(intervals)

        # Add intervals completely before the removal
        while i < n and intervals[i][1] <= r0:
            res.append([intervals[i][0], intervals[i][1]])
            i += 1

        # Process intervals that may overlap with the removal
        while i < n and intervals[i][0] < r1:
            a, b = intervals[i]
            # left piece if it exists
            if a < r0:
                res.append([a, r0])
            # right piece if it exists
            if b > r1:
                res.append([r1, b])
            i += 1

        # Add the remaining intervals after the removal
        while i < n:
            res.append([intervals[i][0], intervals[i][1]])
            i += 1

        return res

