class Solution:
    def removeInterval(self, intervals: List[List[int]], toBeRemoved: List[int]) -> List[List[int]]:
        r0, r1 = toBeRemoved

        def solve(idx: int) -> List[List[int]]:
            if idx == len(intervals):
                return []
            a, b = intervals[idx]
            if b <= r0 or a >= r1:
                return [[a, b]] + solve(idx + 1)
            parts: List[List[int]] = []
            if a < r0:
                parts.append([a, r0])
            if b > r1:
                parts.append([r1, b])
            return parts + solve(idx + 1)

        return solve(0)

