from typing import *

class Solution:
    def maximumLength(self, s: str) -> int:
        # Algorithm/Data-Structure Variant: collect all runs per character and sort
        runs: List[List[int]] = [[] for _ in range(26)]

        n = len(s)
        i = 0
        while i < n:
            ch = s[i]
            j = i
            while j < n and s[j] == ch:
                j += 1
            L = j - i
            runs[ord(ch) - 97].append(L)
            i = j

        for arr in runs:
            if arr:
                arr.sort(reverse=True)

        def enough(arr: List[int], k: int) -> bool:
            ssum = 0
            # Only the first few (at most 3) can contribute to reaching 3
            for L in arr:
                if L < k:
                    break
                ssum += L - k + 1
                if ssum >= 3:
                    return True
            return False

        ans = 0
        for arr in runs:
            if not arr:
                continue
            lo, hi = 1, arr[0]
            best = 0
            while lo <= hi:
                mid = (lo + hi) // 2
                if enough(arr, mid):
                    best = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            if best > ans:
                ans = best

        return ans if ans > 0 else -1

