from typing import *
import heapq

class Solution:
    def maximumLength(self, s: str) -> int:
        # Algorithm/Data-Structure Variant: maintain top-3 runs per character using min-heaps
        heaps: List[List[int]] = [[] for _ in range(26)]

        n = len(s)
        i = 0
        while i < n:
            ch = s[i]
            j = i
            while j < n and s[j] == ch:
                j += 1
            L = j - i
            h = heaps[ord(ch) - 97]
            if len(h) < 3:
                heapq.heappush(h, L)
            else:
                if L > h[0]:
                    heapq.heapreplace(h, L)
            i = j

        # Determine global upper bound for k
        max_top = 0
        for h in heaps:
            if h:
                max_top = max(max_top, max(h))
        if max_top == 0:
            return -1

        def feasible(k: int) -> bool:
            for h in heaps:
                if not h:
                    continue
                ssum = 0
                # h is a min-heap but small; iterate all elements
                for L in h:
                    if L >= k:
                        ssum += L - k + 1
                        if ssum >= 3:
                            return True
            return False

        lo, hi = 1, max_top
        best = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1

        return best if best > 0 else -1

