from typing import List

class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        def has_good_adjacent_pair(a: List[int], t: int) -> bool:
            i = 0
            size = len(a)
            while i < size - 1:
                if a[i] + a[i + 1] >= t:
                    return True
                i += 1
            return False

        if len(nums) <= 2:
            return True
        return has_good_adjacent_pair(nums, m)

