from typing import List
from functools import lru_cache

class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        if n <= 2:
            return True

        prefix = [0]
        for val in nums:
            prefix.append(prefix[-1] + val)

        def range_sum(i: int, j: int) -> int:
            return prefix[j + 1] - prefix[i]

        @lru_cache(None)
        def can(i: int, j: int) -> bool:
            if i == j:
                return True
            for k in range(i, j):
                left_good = (k == i) or (range_sum(i, k) >= m)
                right_good = (k + 1 == j) or (range_sum(k + 1, j) >= m)
                if left_good and right_good:
                    if can(i, k) and can(k + 1, j):
                        return True
            return False

        return can(0, n - 1)

