from bisect import bisect_left, bisect_right

class Solution:
    def countFairPairs(self, nums: List[int], lower: int, upper: int) -> int:
        nums.sort()
        n = len(nums)
        ans = 0
        for i in range(n - 1):
            lo = lower - nums[i]
            hi = upper - nums[i]
            L = bisect_left(nums, lo, i + 1)
            R = bisect_right(nums, hi, i + 1) - 1
            if L <= R:
                ans += (R - L + 1)
        return ans

