from collections import Counter

class Solution:
    def countFairPairs(self, nums: List[int], lower: int, upper: int) -> int:
        cnt = Counter(nums)
        vals = sorted(cnt.keys())
        freqs = [cnt[v] for v in vals]
        m = len(vals)
        suffix = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = suffix[i + 1] + freqs[i]

        def count_leq(t: int) -> int:
            total = 0
            i, j = 0, m - 1
            while i < j:
                s = vals[i] + vals[j]
                if s <= t:
                    total += freqs[i] * (suffix[i + 1] - suffix[j + 1])
                    i += 1
                else:
                    j -= 1
            for k in range(m):
                if vals[k] * 2 <= t:
                    f = freqs[k]
                    total += f * (f - 1) // 2
            return total

        return count_leq(upper) - count_leq(lower - 1)

