from typing import List

class Solution:
    def splitLoopedString(self, strs: List[str]) -> str:
        # Choose the lexicographically larger form (original or reversed) for each string
        best = [max(s, s[::-1]) for s in strs]
        ans = ""
        n = len(strs)

        for i in range(n):
            # Concatenate the rest (strings after i followed by before i) in their best forms
            rest = ''.join(best[i+1:]) + ''.join(best[:i])

            original = strs[i]
            reversed_s = original[::-1]
            for t in (original, reversed_s):
                # Try all cut positions within the current string orientation
                for k in range(len(t)):
                    candidate = t[k:] + rest + t[:k]
                    if candidate > ans:
                        ans = candidate
        return ans

