from typing import List

class Solution:
    def splitLoopedString(self, strs: List[str]) -> str:
        best = [max(s, s[::-1]) for s in strs]
        n = len(strs)
        ans_holder = [""]

        def try_positions(segment: str, rest: str) -> None:
            def recurse(k: int):
                if k == len(segment):
                    return
                cand = segment[k:] + rest + segment[:k]
                if cand > ans_holder[0]:
                    ans_holder[0] = cand
                recurse(k + 1)
            recurse(0)

        for i in range(n):
            rest = ''.join(best[i+1:]) + ''.join(best[:i])
            s = strs[i]
            rs = s[::-1]
            for t in (s, rs):
                try_positions(t, rest)

        return ans_holder[0]

