from typing import List

class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        n = len(colors)
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        stack = [(0, -1, 0)]
        size = [0] * n
        mono = [True] * n
        best = 0

        while stack:
            u, p, state = stack.pop()
            if state == 0:
                stack.append((u, p, 1))
                for v in adj[u]:
                    if v != p:
                        stack.append((v, u, 0))
            else:
                total = 1
                is_mono = True
                for v in adj[u]:
                    if v == p:
                        continue
                    total += size[v]
                    if (not mono[v]) or (colors[v] != colors[u]):
                        is_mono = False
                size[u] = total
                mono[u] = is_mono
                if is_mono and total > best:
                    best = total

        return best

