from typing import List
import math

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure first list is not longer for tighter binary search bounds
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        a_len, b_len = len(nums1), len(nums2)
        total_len = a_len + b_len
        left_count = (total_len + 1) // 2

        low, high = 0, a_len
        INF_POS = math.inf

        while low <= high:
            i = (low + high) // 2
            j = left_count - i

