from typing import List

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        def kth(a: List[int], b: List[int], k: int) -> int:
            # Find the k-th (1-based) smallest element in the union of sorted arrays a and b
            ia = ib = 0
            while True:
                if ia >= len(a):
                    return b[ib + k - 1]
                if ib >= len(b):
                    return a[ia + k - 1]
                if k == 1:
                    return a[ia] if a[ia] <= b[ib] else b[ib]

                step = k // 2
                new_ia = min(ia + step, len(a)) - 1
                new_ib = min(ib + step, len(b)) - 1

                val_a = a[new_ia] if new_ia >= ia else float('inf')
                val_b = b[new_ib] if new_ib >= ib else float('inf')

                if val_a <= val_b:
                    k -= (new_ia - ia + 1)
                    ia = new_ia + 1
                else:
                    k -= (new_ib - ib + 1)
                    ib = new_ib + 1

        total = len(nums1) + len(nums2)
        if total % 2 == 1:
            return float(kth(nums1, nums2, (total + 1) // 2))
        else:
            left = kth(nums1, nums2, total // 2)
            right = kth(nums1, nums2, total // 2 + 1)
            return (left + right) / 2.0

