        from functools import lru_cache

        n_s = len(s)
        n_p = len(p)

        @lru_cache(None)
        def rec(si: int, pj: int) -> bool:
            if pj == n_p:
                return si == n_s

            match_now = si < n_s and (p[pj] == s[si] or p[pj] == '.')
            has_star = pj + 1 < n_p and p[pj + 1] == '*'

            if has_star:
                return rec(si, pj + 2) or (match_now and rec(si + 1, pj))
            return match_now and rec(si + 1, pj + 1)

        return rec(0, 0)

