class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        memo = {}
        ls, lp = len(s), len(p)

        def matches(i: int, j: int) -> bool:
            return i < ls and (p[j] == s[i] or p[j] == '.')

        def solve(i: int, j: int) -> bool:
            key = (i, j)
            if key in memo:
                return memo[key]
            if j == lp:
                memo[key] = (i == ls)
                return memo[key]

            star = (j + 1 < lp and p[j + 1] == '*')
            result = False
            if star:
                if solve(i, j + 2):
                    result = True
                elif matches(i, j) and solve(i + 1, j):
                    result = True
            else:
                if matches(i, j) and solve(i + 1, j + 1):
                    result = True

            memo[key] = result
            return result

        return solve(0, 0)

