class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        ls, lp = len(s), len(p)
        dp = [[False] * (lp + 1) for _ in range(ls + 1)]
        dp[ls][lp] = True

        for j in range(lp - 1, -1, -1):
            if j + 1 < lp and p[j + 1] == '*':
                dp[ls][j] = dp[ls][j + 2]

        for i in range(ls - 1, -1, -1):
            for j in range(lp - 1, -1, -1):
                first = (p[j] == s[i] or p[j] == '.')
                if j + 1 < lp and p[j + 1] == '*':
                    dp[i][j] = dp[i][j + 2] or (first and dp[i + 1][j])
                else:
                    dp[i][j] = first and dp[i + 1][j + 1]

        return dp[0][0]

