class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        ls, lp = len(s), len(p)
        stack = [(0, 0)]
        visited = set()

        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))

            if j == lp:
                if i == ls:
                    return True
                continue

            first = i < ls and (p[j] == s[i] or p[j] == '.')

            if j + 1 < lp and p[j + 1] == '*':
                stack.append((i, j + 2))
                if first:
                    stack.append((i + 1, j))
            else:
                if first:
                    stack.append((i + 1, j + 1))

        return False

